window.COURSE_ASSESSMENTS={"bancos":{"courseId":"bancos","combos":[{"id":"combo-1","title":"Cadastro e busca com integridade","scenario":"Uma biblioteca cadastra exemplares e empréstimos. Cada empréstimo referencia um leitor existente; devolvido_em NULL significa aberto. A busca precisa listar abertos de um leitor em ordem estável.","requiredLessons":[3,4,5,7,8,9],"skills":["Identidade e referências","Ausência e filtros","Ordenação determinística"],"questions":[{"id":"q1","prompt":"A consulta usa leitor_id=7 AND devolvido_em=NULL e não encontra o empréstimo aberto. A FK existe e está ativa. Qual correção preserva o significado do modelo?","options":["Manter a referência por leitor_id e usar devolvido_em IS NULL no filtro.","Trocar NULL pela string NULL em todos os registros.","Remover a FK, pois ela impede consultas de empréstimos abertos.","Retirar o filtro de leitor e ordenar apenas por devolvido_em."],"answer":0,"explanation":"A FK valida a referência, enquanto IS NULL testa ausência. Comparação =NULL não produz o verdadeiro exigido por WHERE.","reviewLessons":[5,8]},{"id":"q2","prompt":"Dois leitores chamados Ana precisam ser cadastrados, mas a mesma matrícula não pode aparecer duas vezes. Qual desenho atende às duas regras?","options":["Nome como única chave, removendo a matrícula.","ID estável como chave e matrícula obrigatória com UNIQUE; nome pode repetir.","Matrícula sem NOT NULL ou UNIQUE porque já existe uma coluna id.","Um campo nome_matricula sem restrição e deduplicação somente na tela."],"answer":1,"explanation":"Identidade e unicidade de negócio são regras distintas. O ID não torna dispensável a proteção da matrícula.","reviewLessons":[3,4]},{"id":"q3","prompt":"Há dois empréstimos abertos no mesmo dia. A tela pede os primeiros dez do leitor 7. Qual consulta descreve uma página previsível?","options":["LIMIT 10 sem ORDER BY, porque inserção define a ordem para sempre.","Ordenar só pelo nome do leitor e aceitar qualquer empate.","Filtrar leitor 7 e abertos, ordenar por data e por id como desempate, depois limitar.","Aplicar OR leitor_id=7 fora dos parênteses para ampliar a busca."],"answer":2,"explanation":"Filtro define o conjunto e ordem com desempate define a página. Limitar sem uma sequência estável não significa pegar os primeiros segundo a regra.","reviewLessons":[7,9]}]},{"id":"combo-2","title":"Relatório que não multiplica fatos","scenario":"O relatório deve mostrar todos os leitores, inclusive sem empréstimos, e contar somente empréstimos válidos. O nome de uma categoria foi repetido em cada livro e ficou contraditório.","requiredLessons":[10,11,13,14,16,17],"skills":["Granularidade","Junção externa","Normalização"],"questions":[{"id":"q1","prompt":"Depois de LEFT JOIN, um leitor sem empréstimos aparece com COUNT(*)=1. Como contar empréstimos mantendo esse leitor com zero?","options":["Trocar LEFT JOIN por INNER JOIN para fazer o zero aparecer.","Somar o ID do leitor para corrigir a contagem.","Adicionar DISTINCT ao nome e remover GROUP BY.","Usar COUNT da chave não nula do empréstimo e agrupar pela identidade do leitor."],"answer":3,"explanation":"A linha preservada pela junção externa existe mesmo sem filho. COUNT da chave direita ignora a parte nula e responde à granularidade desejada.","reviewLessons":[10,14]},{"id":"q2","prompt":"Para manter leitores sem movimento e relacionar apenas empréstimos válidos, onde deve ficar a condição da tabela de empréstimos?","options":["No ON da relação externa, quando o objetivo é restringir correspondências sem eliminar os leitores.","Sempre em WHERE e.status=valido, mesmo que isso elimine os NULL da junção.","Em HAVING leitor_id IS NULL para todos os grupos.","Em ORDER BY, pois ordenar também filtra linhas."],"answer":0,"explanation":"O filtro em WHERE sobre a parte direita pode remover a linha preservada. A posição do predicado precisa corresponder à intenção do relatório.","reviewLessons":[11,14]},{"id":"q3","prompt":"O código de categoria determina seu nome, mas livros do mesmo código guardam nomes diferentes. Qual alteração elimina a causa da divergência?","options":["Copiar o nome da categoria para mais tabelas.","Criar categoria(id,nome) e referenciá-la nos livros, mantendo o nome na fonte determinada pela categoria.","Renomear cada livro para que todos os campos sejam diferentes.","Usar SELECT DISTINCT para esconder qualquer contradição sem mudar o modelo."],"answer":1,"explanation":"A dependência código→nome pertence à categoria. Separá-la evita anomalias de atualização; DISTINCT apenas muda uma apresentação.","reviewLessons":[16,17]}]},{"id":"combo-3","title":"Reserva que suporta falha e repetição","scenario":"Ao emprestar um exemplar, o sistema registra uma operação identificada e reduz disponibilidade. Uma falha pode acontecer entre as etapas ou depois de o cliente perder a resposta.","requiredLessons":[19,20,22,23,25,27],"skills":["Escrita condicional","Atomicidade","Idempotência"],"questions":[{"id":"q1","prompt":"A baixa de disponibilidade mudou uma linha, mas o INSERT do empréstimo falhou. Qual protocolo evita conservar apenas a baixa?","options":["Confirmar a baixa e ignorar o erro do INSERT.","Repetir somente o último SELECT até parecer correto.","Colocar os efeitos na mesma transação e desfazê-la quando qualquer etapa obrigatória falhar.","Usar um alias diferente no UPDATE para criar rollback automático."],"answer":2,"explanation":"Escrita condicional protege a regra local; a transação reúne os efeitos obrigatórios. Falha intermediária deve preservar a unidade de negócio.","reviewLessons":[20,25]},{"id":"q2","prompt":"A operação req-8 foi confirmada, mas a resposta se perdeu. O cliente reenvia a mesma chave e mesmo conteúdo. Qual desenho reduz duplicação de efeitos?","options":["Gerar outra chave a cada timeout e executar novamente.","Ignorar toda violação de chave, inclusive com conteúdo divergente.","Guardar a chave só na memória do navegador após receber resposta.","Guardar a chave única e o resultado junto dos efeitos; reconhecer a repetição e devolver o resultado original."],"answer":3,"explanation":"O registro idempotente precisa sobreviver à resposta perdida e estar coordenado aos efeitos. A mesma chave com outro conteúdo exige tratamento de conflito.","reviewLessons":[19,27]},{"id":"q3","prompt":"Uma CTE calcula total_por_leitor e uma subconsulta calcula a média global desses totais. O objetivo é listar leitores acima dessa média. O que deve ser comparado?","options":["Cada total por leitor com a média dos totais, conservando a granularidade por leitor nas duas etapas.","Cada linha de empréstimo com o maior ID de leitor.","O nome da CTE com uma string que contenha a média.","A média global com a quantidade de colunas do resultado."],"answer":0,"explanation":"CTE nomeia a etapa e subconsulta define o conjunto de referência. Alterar a granularidade de uma das medidas muda a pergunta de negócio.","reviewLessons":[22,23]}]},{"id":"combo-4","title":"Busca evolutiva e recuperação","scenario":"A biblioteca terá busca parametrizada, páginas por cursor e alteração de esquema sem perda de histórico. Uma cópia precisa ser recuperada em destino separado antes da entrega.","requiredLessons":[28,29,30,31,32,34],"skills":["Índices medidos","Binding e cursor","Migração e restore"],"questions":[{"id":"q1","prompt":"A página ordena por titulo,id. O título vem da entrada do usuário e o cursor só guarda id. Qual correção atende segurança e estabilidade?","options":["Concatenar o título na SQL e usar qualquer id como cursor.","Vincular os valores e carregar titulo e id no cursor, com predicado que reproduza a ordem.","Usar placeholder para o nome de toda cláusula ORDER BY e omitir desempate.","Substituir a paginação por LIMIT sem ordem."],"answer":1,"explanation":"Parâmetros protegem os valores e o cursor precisa representar a ordem completa. Segurança e definição da fronteira são responsabilidades diferentes.","reviewLessons":[30,31]},{"id":"q2","prompt":"Um índice foi adicionado e o plano mudou. Isso basta para anunciar ganho de tempo na base real?","options":["Sim, qualquer uso de índice é sempre mais rápido.","Sim, o texto de EXPLAIN equivale a milissegundos garantidos.","Não; confirme o mesmo resultado e meça com dados e carga representativos, registrando custos de manutenção.","Não, porque índices nunca podem melhorar consulta."],"answer":2,"explanation":"O plano mostra a estratégia escolhida. A melhoria precisa de medição comparável e consideração do custo de escrita.","reviewLessons":[28,29]},{"id":"q3","prompt":"Uma coluna obrigatória será acrescentada a dados antigos e há um arquivo de backup recém-criado. Qual evidência falta antes de considerar o procedimento recuperável?","options":["Apenas renomear o backup com a palavra aprovado.","Apagar a origem para obrigar o restore a funcionar.","Confiar que qualquer ALTER possui rollback idêntico em todos os bancos.","Validar os dados anteriores na migração e abrir uma restauração separada com consultas de conferência."],"answer":3,"explanation":"Migração precisa considerar linhas existentes; recuperação precisa ser demonstrada no destino. Criar uma cópia não prova sua utilidade.","reviewLessons":[32,34]}]}],"finalProject":{"id":"final","title":"Biblioteca com empréstimos e recuperação","scenario":"Implemente o banco de uma biblioteca pequena com leitores, títulos, exemplares, empréstimos e devoluções. Entregue um laboratório reproduzível; não use dados pessoais reais.","requirements":["Modelo íntegro: entidades, chaves e cardinalidades documentadas; referências inexistentes e duplicações de negócio são rejeitadas.","Operação atômica: empréstimo e baixa de disponibilidade confirmam juntos ou são desfeitos; tentativa concorrente não produz disponibilidade negativa.","Identidade de operação: repetição da mesma requisição não cria outro empréstimo e conteúdo divergente tem tratamento explícito.","Consultas corretas: listar leitores sem movimento, circulação por período e página com desempate, sem multiplicar medidas de entidades.","Integração e evolução: cliente com valores parametrizados, migração versionada e casos positivos e negativos de integridade.","Recuperação demonstrada: cópia consistente, reabertura em destino separado, comparação de dados e registro de RPO/RTO pretendidos e medidos."],"deliverables":["DDL e dicionário de dados com regras e decisões do modelo.","Scripts de fixture e consultas com resultados esperados.","Cliente, migrações e roteiro de testes reproduzível em banco novo.","Runbook de cópia e restauração com evidências do destino e limitações."],"rubric":[{"id":"r1","title":"Modelo íntegro","description":"Modelo íntegro: entidades, chaves e cardinalidades documentadas; referências inexistentes e duplicações de negócio são rejeitadas.","reviewLessons":[3,4,5,6,16,17]},{"id":"r2","title":"Operação atômica","description":"Operação atômica: empréstimo e baixa de disponibilidade confirmam juntos ou são desfeitos; tentativa concorrente não produz disponibilidade negativa.","reviewLessons":[20,25,26,27]},{"id":"r3","title":"Identidade de operação","description":"Identidade de operação: repetição da mesma requisição não cria outro empréstimo e conteúdo divergente tem tratamento explícito.","reviewLessons":[19,25,27]},{"id":"r4","title":"Consultas corretas","description":"Consultas corretas: listar leitores sem movimento, circulação por período e página com desempate, sem multiplicar medidas de entidades.","reviewLessons":[10,11,13,14,24,30]},{"id":"r5","title":"Integração e evolução","description":"Integração e evolução: cliente com valores parametrizados, migração versionada e casos positivos e negativos de integridade.","reviewLessons":[31,32,33]},{"id":"r6","title":"Recuperação demonstrada","description":"Recuperação demonstrada: cópia consistente, reabertura em destino separado, comparação de dados e registro de RPO/RTO pretendidos e medidos.","reviewLessons":[34,35,36]}],"acceptance":[{"title":"Empréstimo válido e repetido","setup":"Um exemplar disponível e leitor existente; nenhuma operação req-1 registrada.","input":"Solicitar um empréstimo e repetir req-1 com o mesmo conteúdo.","expected":"Um empréstimo ativo, uma baixa e o mesmo resultado identificado nas duas respostas.","reviewLessons":[19,20,25,27]},{"title":"Falha entre efeitos","setup":"Fixture com disponibilidade 1 e erro injetado após a baixa, antes do registro final.","input":"Executar a operação e provocar falha controlada na segunda etapa.","expected":"A transação é desfeita; disponibilidade e quantidade de empréstimos permanecem como antes.","reviewLessons":[20,25,26,33]},{"title":"Restaurar e consultar","setup":"Cópia gerada após dados conhecidos e destino de laboratório vazio.","input":"Abrir a cópia em outro destino e rodar contagens, totalizações e verificação de referências.","expected":"Destino abre, preserva os marcadores e atende aos invariantes; duração e ponto recuperado são registrados.","reviewLessons":[32,33,34,36]}],"questions":[{"id":"q1","prompt":"O relatório de leitores está correto, mas uma transferência parcial ficou gravada após erro. O projeto pode ser aprovado só pela consulta?","options":["Não; precisa corrigir a unidade transacional e provar rollback do estado.","Sim, relatórios substituem testes de escrita.","Sim, basta esconder a linha na tela.","Não, porque consultas nunca são parte do projeto."],"answer":0,"explanation":"Correção de leitura não compensa uma invariante violada na escrita. O teste precisa examinar estado após a falha.","reviewLessons":[25,27,33]},{"id":"q2","prompt":"O backup abriu, mas há referência órfã e contagem divergente da origem conhecida. Qual é o próximo passo?","options":["Marcar sucesso porque o arquivo abriu.","Investigar a origem da divergência e revisar integridade/procedimento de cópia antes de declarar recuperação válida.","Excluir a conferência de FKs para obter ok.","Somar manualmente uma linha no relatório sem reparar os dados."],"answer":1,"explanation":"Reabertura é necessária, mas a recuperação também precisa preservar o estado e as regras esperadas.","reviewLessons":[5,33,34]},{"id":"q3","prompt":"Um projeto escolheu guardar um total derivado para acelerar a tela. Qual entrega justifica essa decisão?","options":["Apenas a frase desnormalização é mais rápida.","Remover os fatos para ninguém encontrar divergência.","Medição da necessidade e política de atualização/reconciliação comparada aos fatos de origem.","Adicionar DISTINCT a toda consulta e dispensar testes."],"answer":2,"explanation":"Redundância intencional exige origem verificável, custo medido e manutenção explícita.","reviewLessons":[18,28,29]}]}},"cpp":{"courseId":"cpp","combos":[{"title":"Catálogo sem referências inválidas","scenario":"Uma CLI mantém produtos em vector e map, remove itens e permite consultas por código. O algoritmo precisa conservar posições válidas e não criar produto só por consultar ausência.","requiredLessons":[4,5,6,7,8,9],"skills":["Referências","Iteradores","Busca e presença"],"questions":[{"prompt":"Um iterador aponta para um elemento do vector. push_back provoca realocação e o código depois usa esse iterador. Como corrigir o acesso?","options":["Reconhecer a invalidação e obter uma posição válida novamente, evitando manter referências/iteradores além de operações que possam invalidá-los.","Assumir que todo iterador continua válido porque o conteúdo parece igual.","Usar o iterador antigo depois de um sleep.","Transformar o iterador em const para impedir realocação do vector."],"answer":0,"explanation":"A duração da coleção não garante a validade das posições internas. Operações de crescimento podem realocar seu armazenamento.","reviewLessons":[5,6,7],"id":"q1"},{"prompt":"Consultar estoque[sku] num std::map fez aparecer um SKU inexistente com zero. Qual acesso corresponde a uma consulta sem inserção?","options":["operator[] porque leitura de map nunca altera a coleção.","find ou contains para distinguir ausência, usando o valor somente quando a chave existir.","Inserir todo SKU desconhecido antes da validação.","Usar o tamanho do map como saldo do produto."],"answer":1,"explanation":"operator[] pode inserir um valor padrão quando a chave não existe. Consulta, ausência e criação deliberada precisam de contratos distintos.","reviewLessons":[4,8,9],"id":"q2"},{"prompt":"Uma função retorna const std::string& para uma variável local criada dentro dela. O chamador lê o título depois do retorno. Qual contrato evita a referência pendente?","options":["Adicionar const torna a variável local eterna.","Usar a referência apenas uma vez, pois a primeira leitura é sempre válida.","Retornar um valor proprietário, ou referenciar apenas um objeto cuja duração seja garantida pelo contrato do chamador.","Guardar a referência num map sem mudar o tempo de vida."],"answer":2,"explanation":"Referência não estende automaticamente a vida de uma variável local destruída. Propriedade e duração precisam fazer parte do contrato da função.","reviewLessons":[4,5,6],"id":"q3"}],"id":"combo-1"},{"title":"Recursos e alteração sem estado parcial","scenario":"Uma operação carrega um lote de reservas usando objetos com recursos exclusivos. Dados inválidos e exceções não podem vazar o recurso nem substituir parcialmente o catálogo válido.","requiredLessons":[11,13,14,15,17,18],"skills":["RAII","Propriedade","Exceções e testes"],"questions":[{"prompt":"Um recurso é adquirido e a validação lança exceção antes da liberação manual. Qual desenho garante limpeza pelo ciclo de vida?","options":["Adicionar delete apenas no último return e ignorar exceções.","Copiar o ponteiro proprietário para várias variáveis e chamar delete em todas.","Usar sleep para esperar que o sistema adivinhe a posse.","Encapsular o recurso num objeto RAII com dono claro, cuja destruição libere o recurso nos caminhos normais e de exceção."],"answer":3,"explanation":"RAII associa a liberação ao tempo de vida do objeto. A limpeza não deve depender de alcançar uma linha final de execução.","reviewLessons":[13,14,17],"id":"q1"},{"prompt":"Dois objetos mantêm shared_ptr um para o outro e nunca são liberados. Qual relação deve ser revista?","options":["A relação de propriedade compartilhada; uma referência observadora pode usar weak_ptr quando não deve prolongar a vida do outro objeto.","Trocar o nome dos ponteiros para observador sem mudar o tipo.","Criar mais uma referência shared_ptr para forçar liberação.","Assumir que shared_ptr coleta ciclos como um coletor de lixo."],"answer":0,"explanation":"Contagem de referências não resolve ciclos de propriedade. weak_ptr expressa observação sem adicionar posse forte.","reviewLessons":[13,14,15],"id":"q2"},{"prompt":"A importação altera o catálogo linha por linha e falha na última. Como oferecer a garantia de manter o estado anterior quando a validação falha?","options":["Capturar qualquer exceção e manter silenciosamente as primeiras alterações.","Construir e validar um estado candidato independente e só efetivar a troca quando todo o lote estiver válido.","Usar assert como única proteção de entrada no executável de entrega.","Apagar o catálogo original antes de tentar ler o lote."],"answer":1,"explanation":"Uma mudança candidata permite rejeitar o lote sem efeito parcial. O teste precisa verificar o estado anterior, além da exceção.","reviewLessons":[11,17,18],"id":"q3"}],"id":"combo-2"},{"title":"Views, parsing e snapshot validado","scenario":"Um relatório usa ranges e janelas de leitura; um snapshot textual versionado é carregado para restaurar o catálogo. O parser precisa consumir campos inteiros e a restauração não pode depender de memória destruída.","requiredLessons":[23,24,25,26,27],"skills":["Contratos genéricos","Lifetime","Parsing e recuperação"],"questions":[{"prompt":"Uma função cria std::string local e retorna string_view apontando para ela. O relatório guarda a view. Qual é o problema?","options":["string_view sempre copia toda a string e não há problema.","const na view torna a string local permanente.","A view não possui os bytes e passa a apontar para armazenamento destruído; o dono precisa sobreviver ao uso ou o resultado deve possuir os dados.","O problema se resolve apenas ordenando a view."],"answer":2,"explanation":"Janelas de leitura não transferem propriedade. Seu contrato deve declarar a duração do armazenamento referenciado.","reviewLessons":[23,24,25],"id":"q1"},{"prompt":"from_chars conseguiu converter o prefixo \"12\" de \"12abc\" sem erro numérico. A quantidade pode ser aceita como 12?","options":["Sim, ausência de erro numérico prova formato completo.","Sim, qualquer sufixo deve ser ignorado silenciosamente.","Não, porque from_chars nunca retorna uma posição.","Não sem conferir consumo completo do campo e a regra do domínio; o ponteiro final precisa alcançar o fim esperado."],"answer":3,"explanation":"Sucesso parcial de conversão e validade completa do campo são coisas distintas. Consumo, faixa e significado precisam ser testados.","reviewLessons":[26,27],"id":"q2"},{"prompt":"O snapshot tem versão desconhecida e alguns registros válidos. Qual ação preserva o catálogo em uso?","options":["Recusar ou migrar por um caminho explícito para a versão, mantendo um estado candidato sem substituir o original enquanto o documento inteiro não for validado.","Aceitar as primeiras linhas e ignorar a versão.","Apagar o catálogo antes de validar o cabeçalho.","Guardar views para o buffer local e liberar o buffer ao terminar."],"answer":0,"explanation":"Formato versionado é um contrato. Validação global e propriedade dos dados são necessárias antes da troca do estado.","reviewLessons":[24,25,26,27],"id":"q3"}],"id":"combo-3"},{"title":"Confirmação concorrente e operação observável","scenario":"Duas threads podem confirmar uma ordem e uma CLI salva snapshots. O invariante liga a verificação de estoque, a baixa e o registro da operação; diagnóstico deve separar correção de velocidade.","requiredLessons":[28,29,30,31,35,36],"skills":["Threads e locks","Idempotência","Medição e entrega"],"questions":[{"prompt":"O saldo é atomic<int>, mas o código faz if(saldo>=qtd) seguido de saldo-=qtd em operações separadas. Isso basta para impedir duas confirmações sobre a última unidade?","options":["Sim, qualquer acesso atomic torna toda a operação de domínio uma transação.","Não; a verificação e a alteração do invariante precisam de uma coordenação conjunta adequada, como região crítica que também inclui a decisão da ordem.","Sim, jthread elimina intercalamento.","Não, porque atomic não pode armazenar inteiros."],"answer":1,"explanation":"Atomicidade de operações isoladas não transforma uma sequência em indivisível. O lock deve proteger a decisão e o efeito relacionados.","reviewLessons":[28,29,30,35],"id":"q1"},{"prompt":"O teste lê o resultado produzido por uma jthread antes de ela terminar e sem sincronização apropriada. O que precisa mudar?","options":["Confiar que a thread é rápida nesta máquina.","Esperar dez milissegundos e remover qualquer outra sincronização.","Definir o ponto de espera/sincronização antes da leitura, conservando também a proteção das variáveis compartilhadas durante o trabalho.","Aumentar o número de threads para uma delas terminar antes."],"answer":2,"explanation":"Ciclo de vida e acesso compartilhado são contratos separados. Esperar deliberadamente o trabalho evita ler um resultado ainda em produção.","reviewLessons":[28,29,31],"id":"q2"},{"prompt":"O mesmo ID de confirmação chega duas vezes. O programa registra o ID, mas a baixa ocorre fora do lock. Qual risco permanece?","options":["Nenhum, pois ter um set em qualquer ponto prova idempotência concorrente.","Só um problema de cor no terminal.","O risco desaparece se usar o mesmo nome de arquivo.","Outra execução pode observar um estado intermediário; deduplicação e alteração de estoque precisam compartilhar a coordenação que preserva o invariante."],"answer":3,"explanation":"Reconhecer uma operação e aplicar seu efeito são partes da mesma decisão. Coordenação parcial pode permitir efeitos duplicados ou resultado inconsistente.","reviewLessons":[29,30,35],"id":"q3"}],"id":"combo-4"}],"finalProject":{"id":"final","title":"Controle local de reservas em C++","scenario":"Construa uma CLI C++20 para reservar materiais, consultar disponibilidade e salvar/restaurar um snapshot versionado. A aplicação deve proteger propriedade, duração e alterações compostas sob erro e concorrência.","requirements":["Definir estados nomeados, quantidades válidas e APIs que não exponham mutação arbitrária de estoque.","Usar RAII e propriedade apropriada; não conservar views, referências ou iteradores além de sua validade.","Verificar parsing completo, versão e dados do snapshot num estado candidato antes de substituir o estado válido.","Proteger reserva, saldo e identidade da operação como um invariante; documentar o limite durável da idempotência.","Testar vazio, ausência, fronteira, erro de parsing, rollback lógico, repetição e disputa sem depender apenas de assert.","Documentar compilação C++20, ferramentas de diagnóstico, comandos CLI, um experimento de desempenho e restauração conferida."],"deliverables":["Fontes da CLI com modelo, casos de uso e armazenamento separados.","Executável de testes e fixtures de snapshot válido/inválido.","README de compilação, execução, propriedade e contratos.","Relatório de concorrência, diagnóstico e reabertura de snapshot."],"rubric":[{"id":"r1","title":"Tipos e invariantes","description":"Definir estados nomeados, quantidades válidas e APIs que não exponham mutação arbitrária de estoque.","reviewLessons":[4,10,11,16]},{"id":"r2","title":"Propriedade e lifetime","description":"Usar RAII e propriedade apropriada; não conservar views, referências ou iteradores além de sua validade.","reviewLessons":[6,7,13,14,15,24]},{"id":"r3","title":"Entrada e recuperação","description":"Verificar parsing completo, versão e dados do snapshot num estado candidato antes de substituir o estado válido.","reviewLessons":[17,25,26,27]},{"id":"r4","title":"Concorrência e repetição","description":"Proteger reserva, saldo e identidade da operação como um invariante; documentar o limite durável da idempotência.","reviewLessons":[28,29,30,35]},{"id":"r5","title":"Evidências de comportamento","description":"Testar vazio, ausência, fronteira, erro de parsing, rollback lógico, repetição e disputa sem depender apenas de assert.","reviewLessons":[16,17,18,29,35]},{"id":"r6","title":"Entrega diagnosticável","description":"Documentar compilação C++20, ferramentas de diagnóstico, comandos CLI, um experimento de desempenho e restauração conferida.","reviewLessons":[31,32,33,34,36]}],"acceptance":[{"title":"Reserva e repetição","setup":"SKU A possui 5 unidades; operação o-1 não foi aplicada.","input":"Confirmar 2 unidades e repetir o-1 com o mesmo conteúdo.","expected":"Saldo 3 e um efeito de confirmação, dentro do limite de persistência documentado.","reviewLessons":[11,29,35]},{"title":"Snapshot recusado","setup":"Catálogo em memória válido com saldo 5.","input":"Carregar arquivo de versão desconhecida ou quantidade \"12abc\".","expected":"Erro contextualizado; catálogo original continua com saldo 5 e nenhum registro parcialmente substituído.","reviewLessons":[17,25,26,27]},{"title":"Última unidade concorrente","setup":"Saldo 1 e duas threads com operações distintas.","input":"Ambas tentam reservar uma unidade; espere o término antes de verificar.","expected":"Uma confirma e outra é recusada; saldo 0 e estruturas internas permanecem consistentes.","reviewLessons":[18,28,29,30]}],"questions":[{"prompt":"O projeto usa smart pointers, mas retorna string_view para uma string local. A gestão de lifetime está resolvida?","options":["Não; smart pointers em outras partes não corrigem uma view cujo armazenamento já foi destruído.","Sim, usar qualquer unique_ptr resolve todas as referências.","Sim, string_view guarda cópia automática.","Não, porque referências nunca podem ser usadas."],"answer":0,"explanation":"Cada janela de leitura precisa de um dono vivo; a escolha de propriedade é local a cada contrato.","reviewLessons":[13,14,24],"id":"q1"},{"prompt":"Um teste negativo passa com assert, mas essa verificação pode ser removida no build de entrega. Como manter proteção de entrada?","options":["Depender somente de assert e renomear o executável.","Validar entradas no fluxo normal com resultado/erro explícito e usar testes para comprovar rejeição e estado preservado.","Aceitar qualquer snapshot no build Release.","Substituir toda validação por comentários."],"answer":1,"explanation":"Assert não deve ser a única implementação de uma regra exigida em execução.","reviewLessons":[16,17,18,26],"id":"q2"},{"prompt":"A CLI reabre o snapshot, mas IDs de operações não foram persistidos. Pode prometer deduplicação após reinício?","options":["Sim, porque o nome do arquivo é estável.","Sim, std::set recria seus elementos automaticamente.","Não; deve persistir a informação necessária de maneira consistente ou declarar que a garantia se limita ao processo.","Não, porque C++ não permite persistir dados."],"answer":2,"explanation":"A recuperação precisa conservar todos os dados envolvidos na garantia anunciada.","reviewLessons":[25,27,35,36],"id":"q3"}]}},"csharp":{"courseId":"csharp","combos":[{"title":"Cadastro validado e consulta por identidade","scenario":"Um aplicativo console recebe quantidades como texto e armazena itens por código. Ausência, zero e erro de formato devem ser estados diferentes; uma entrada recusada não pode alterar o catálogo.","requiredLessons":[2,3,5,6,7,8],"skills":["Conversão","Funções","Coleções e presença"],"questions":[{"prompt":"int.TryParse retorna true para \"-2\", mas a regra aceita somente quantidades positivas. Qual verificação ainda falta antes de salvar?","options":["Validar o intervalo e o significado da quantidade numa função de domínio, recusando o valor sem alterar o catálogo.","Nenhuma; conversão bem-sucedida prova qualquer regra do negócio.","Trocar -2 por 0 silenciosamente e anunciar sucesso.","Imprimir o número e considerar a escrita concluída."],"answer":0,"explanation":"TryParse verifica o formato representável, não a regra de quantidade positiva. A decisão deve anteceder o efeito.","reviewLessons":[2,3,5,6],"id":"q1"},{"prompt":"Um Dictionary guarda A com estoque 0 e não guarda B. Como a consulta pode distinguir esses dois casos sem criar uma entrada?","options":["Considerar valor zero como prova de ausência em qualquer consulta.","Usar TryGetValue e tratar separadamente o booleano de presença e o valor do estoque.","Usar o tamanho do código como saldo.","Inserir B com valor 0 antes de responder se existe."],"answer":1,"explanation":"Presença da chave e quantidade são dimensões diferentes. A consulta deve conservar o catálogo e respeitar o contrato de ausência.","reviewLessons":[3,5,8],"id":"q2"},{"prompt":"Duas variáveis referenciam a mesma List<Item>. Uma função adiciona um item por uma delas e a outra lista observada muda. Qual contrato precisa ficar explícito?","options":["Toda atribuição de lista faz cópia profunda automática.","O efeito é impossível porque o parâmetro tem outro nome.","Se a função altera a coleção recebida ou produz uma coleção independente, considerando também referências aos objetos internos.","Basta transformar o nome local em const para copiar os objetos."],"answer":2,"explanation":"Copiar uma referência não copia a coleção. Mesmo uma cópia do contêiner pode continuar compartilhando objetos internos.","reviewLessons":[5,7,8],"id":"q3"}],"id":"combo-1"},{"title":"Relatório LINQ com estado e recursos controlados","scenario":"Um relatório agrupa registros, usa records como valores e lê um recurso descartável. A execução adiada e as cópias rasas não podem surpreender o contrato da resposta nem os testes.","requiredLessons":[11,13,14,16,17,18],"skills":["Records","LINQ","Exceções, descarte e testes"],"questions":[{"prompt":"Um record contém List<string> Tags. b = a with { } é criado e b.Tags.Add(\"novo\") também afeta a.Tags. Qual conclusão é correta?","options":["with sempre faz cópia profunda de qualquer objeto interno.","Records impedem toda mutação de objetos referenciados.","O problema desaparece ao enumerar a lista duas vezes.","A cópia do record é rasa e compartilha a lista; é preciso copiar ou trocar a representação interna quando a independência for necessária."],"answer":3,"explanation":"Igualdade por valor e cópia de um record não significam imutabilidade profunda. A coleção interna continua tendo identidade e mutabilidade próprias.","reviewLessons":[11,13],"id":"q1"},{"prompt":"var consulta = itens.Where(...); é criado, depois itens recebe outro elemento e só então a consulta é enumerada. Se o contrato exige um retrato no momento da criação, o que mudar?","options":["Materializar o resultado no ponto de corte apropriado e definir se também é necessário copiar os objetos mutáveis do resultado.","Assumir que Where executa e congela os dados imediatamente.","Enumerar mais rápido para impedir mudanças anteriores.","Trocar o nome consulta por snapshot sem mudar a operação."],"answer":0,"explanation":"LINQ pode ter execução adiada. Materializar fixa os membros do resultado naquele momento, mas não torna todos os objetos internos imutáveis.","reviewLessons":[11,13,14],"id":"q2"},{"prompt":"A leitura lança uma exceção dentro de using. Qual teste verifica o contrato do recurso e da falha?","options":["Testar somente que o método retornou alguma string.","Conferir que Dispose foi chamado e que o erro esperado foi observado ou traduzido com sua causa, sem transformar a falha em relatório válido.","Aceitar qualquer exceção como prova de relatório correto.","Depender da coleta de lixo imediata em vez de using."],"answer":1,"explanation":"Descarte determinístico e propagação de erro são efeitos observáveis distintos. O teste deve verificar ambos os caminhos do contrato.","reviewLessons":[16,17,18],"id":"q3"}],"id":"combo-2"},{"title":"API, cancelamento e snapshot validado","scenario":"Uma API local recebe JSON, acessa uma dependência HTTP e pode restaurar um snapshot. Identidade, autorização, validação e prazo precisam ser tratados antes de substituir o estado em uso.","requiredLessons":[20,21,23,25,26,27],"skills":["DTO e snapshots","HTTP","Cancelamento e autorização"],"questions":[{"prompt":"O corpo do POST contém donoId de outro usuário e um pedido de alteração. Qual decisão deve preceder a escrita?","options":["Aceitar donoId como prova de identidade porque veio em JSON.","Alterar primeiro e retornar 403 depois.","Usar a identidade autenticada, verificar a propriedade/permissão sobre o recurso e validar o DTO antes do efeito.","Autorizar qualquer usuário que saiba o ID da entidade."],"answer":2,"explanation":"JSON é dado não confiável. Autenticação identifica a pessoa e autorização verifica a operação sobre o recurso solicitado.","reviewLessons":[20,26,27],"id":"q1"},{"prompt":"O endpoint usa CancellationToken, mas não o passa para HttpClient. O cliente encerrou a requisição; qual comportamento não está garantido?","options":["Que uma variável local deixou de existir.","Que a rota tenha um nome.","Que HttpClient reconheça códigos de status.","Que a operação dependente interrompeu o trabalho; o token precisa chegar à API cooperativa e o resultado ainda pode ser incerto."],"answer":3,"explanation":"Receber um token não cancela automaticamente todas as dependências. Prazo, cancelamento e efeito externo precisam de contratos próprios.","reviewLessons":[23,25,26],"id":"q2"},{"prompt":"Um snapshot possui JSON válido, versão desconhecida e estoque negativo. Qual restauração preserva o estado ativo?","options":["Desserializar para um candidato, verificar versão e invariantes e só então efetivar uma troca válida; caso contrário manter o estado anterior.","Substituir o estado logo após desserializar, porque sintaxe válida basta.","Aplicar os registros válidos e ignorar o resto sem regra de aceitação parcial.","Converter o estoque negativo em zero silenciosamente."],"answer":0,"explanation":"A fronteira do formato não valida o domínio. Estado candidato e troca após validação evitam uma restauração parcial ou incompatível.","reviewLessons":[20,21],"id":"q3"}],"id":"combo-3"},{"title":"Fila limitada, diagnóstico e confirmação única","scenario":"O serviço processa confirmações com Channels e guarda chaves de operações. O número de tarefas, as regiões críticas e as evidências de desempenho precisam preservar o mesmo resultado de negócio.","requiredLessons":[28,29,30,31,33,35],"skills":["Locks","Channels","Diagnóstico e idempotência"],"questions":[{"prompt":"O código verifica se a operação já existe fora do lock, debita estoque dentro e só depois registra a operação. Duas chamadas iguais podem passar pela primeira checagem. O que corrigir?","options":["Adicionar apenas Interlocked.Increment num contador de logs.","Proteger verificação, efeito e registro da operação na mesma coordenação do invariante, com contrato de persistência definido.","Proteger somente o texto da resposta.","Presumir que await impede intercalamento de requisições."],"answer":1,"explanation":"A sequência composta precisa de um limite comum; operações atômicas isoladas e assincronia não tornam a decisão inteira indivisível.","reviewLessons":[28,35],"id":"q1"},{"prompt":"Um Channel sem limite cresce e a latência aumenta, mas o relatório só mostra tarefas concluídas. Que revisão combina controle e diagnóstico?","options":["Remover todo log para afirmar que a fila desapareceu.","Criar consumidores ilimitados sem medir recursos escassos.","Definir capacidade/política de pressão e observar fila, tempo de espera, falhas e correlação de cada operação.","Contar apenas requisições aceitas e tratar as demais como concluídas."],"answer":2,"explanation":"Conclusão é só uma parte do fluxo. Backpressure e sinais de espera ajudam a entender a diferença entre admissão e capacidade de processamento.","reviewLessons":[29,33],"id":"q2"},{"prompt":"A versão paralela executa em menos tempo numa rodada, mas devolve soma diferente da sequencial. Ela pode ser declarada uma otimização válida?","options":["Sim, qualquer redução de tempo compensa resultado errado.","Sim, Task.Run valida a soma automaticamente.","Não, porque .NET proíbe medir CPU.","Não; primeiro preserve a correção e compare a mesma carga em condições documentadas, com limite de paralelismo."],"answer":3,"explanation":"Medição de desempenho depende de trabalho equivalente e resultado correto. Agendamento e quantidade de tarefas também têm custo e limites.","reviewLessons":[30,31],"id":"q3"}],"id":"combo-4"}],"finalProject":{"id":"final","title":"Central local de empréstimos em C#","scenario":"Entregue uma aplicação .NET com CLI e API local para emprestar equipamentos. O mesmo domínio atende as duas interfaces, com snapshot validado, fila de trabalho limitada e confirmação repetível.","requirements":["Validar identificadores, quantidades e transições por operações encapsuladas; distinguir igualdade, identidade e cópia rasa.","Expor casos de uso por CLI/ASP.NET Core, validar DTOs e autorização antes de alterar recursos.","Salvar um formato versionado e restaurar por estado candidato, preservando os dados necessários à garantia de repetição anunciada.","Descartar recursos, propagar tokens de cancelamento e encerrar produtor/consumidor sem fila ou tarefa ilimitada.","Proteger o invariante de disponibilidade e deduplicação e verificar falha, fronteira e disputa com testes determinísticos.","Documentar SDK/projetos corretos, comandos, logs correlacionados, medições em configuração adequada e reabertura de backup."],"deliverables":["Solução .NET com domínio, CLI, API e persistência separados.","Testes e fixtures de entrada, snapshot, disputa e repetição.","README de instalação, execução e contratos de acesso/cancelamento.","Relatório de recuperação e de um experimento de desempenho, com limites."],"rubric":[{"id":"r1","title":"Contratos de domínio","description":"Validar identificadores, quantidades e transições por operações encapsuladas; distinguir igualdade, identidade e cópia rasa.","reviewLessons":[6,8,10,11]},{"id":"r2","title":"Interface e acesso","description":"Expor casos de uso por CLI/ASP.NET Core, validar DTOs e autorização antes de alterar recursos.","reviewLessons":[12,20,26,27,34]},{"id":"r3","title":"Persistência e recuperação","description":"Salvar um formato versionado e restaurar por estado candidato, preservando os dados necessários à garantia de repetição anunciada.","reviewLessons":[19,20,21,35]},{"id":"r4","title":"Ciclo de vida","description":"Descartar recursos, propagar tokens de cancelamento e encerrar produtor/consumidor sem fila ou tarefa ilimitada.","reviewLessons":[17,22,23,24,29]},{"id":"r5","title":"Concorrência e testes","description":"Proteger o invariante de disponibilidade e deduplicação e verificar falha, fronteira e disputa com testes determinísticos.","reviewLessons":[18,28,30,35]},{"id":"r6","title":"Entrega e evidências","description":"Documentar SDK/projetos corretos, comandos, logs correlacionados, medições em configuração adequada e reabertura de backup.","reviewLessons":[25,26,31,33,36]}],"acceptance":[{"title":"Confirmação válida e duplicata","setup":"Equipamento E possui 3 unidades; operação e-1 é inédita.","input":"Emprestar 1 unidade e repetir e-1 com o mesmo conteúdo.","expected":"Uma confirmação, saldo 2 e resposta da operação original na repetição dentro da garantia documentada.","reviewLessons":[10,28,35]},{"title":"Restauração inválida","setup":"Estado ativo válido e snapshot com versão desconhecida ou quantidade negativa.","input":"Solicitar carga do snapshot.","expected":"Erro identificável e estado anterior preservado, sem troca parcial.","reviewLessons":[18,20,21]},{"title":"Cancelamento e encerramento","setup":"Fila limitada com consumidor em operação cooperativa e registros de correlação.","input":"Sinalizar encerramento e aguardar até o prazo definido.","expected":"Admissão cessa, tarefas são concluídas/canceladas segundo o contrato e não há promessa falsa de efeito externo desfeito.","reviewLessons":[23,29,33,36]}],"questions":[{"prompt":"A API recebe um token de cancelamento, mas a chamada HTTP o ignora. Qual critério final continua pendente?","options":["Propagação do cancelamento até o trabalho cooperativo e tratamento do resultado incerto.","A existência de uma rota apenas.","A escolha de uma cor para erros.","O uso de namespace no código."],"answer":0,"explanation":"O ciclo de vida precisa atravessar as dependências, não ficar apenas na assinatura do endpoint.","reviewLessons":[23,25,26],"id":"q1"},{"prompt":"O backup reabre, mas não contém as chaves que impediam duplicar confirmações. Pode manter a mesma promessa de idempotência após recuperar?","options":["Sim, o arquivo JSON recria qualquer dado omitido.","Não sem restaurar consistentemente essa informação ou restringir explicitamente o contrato da garantia.","Sim, locks sobrevivem automaticamente ao processo.","Não, porque C# não permite serializar chaves."],"answer":1,"explanation":"A informação necessária ao invariante faz parte do estado recuperável.","reviewLessons":[20,21,35,36],"id":"q2"},{"prompt":"Um teste confirma que houve erro, mas não verifica o saldo depois da tentativa. O que falta para provar recusa sem efeito parcial?","options":["Apenas uma mensagem maior no console.","Um delay para dar tempo de esconder a alteração.","Asserções sobre estoque, confirmação e identidade da operação depois da falha.","Trocar todos os tipos por dynamic."],"answer":2,"explanation":"O resultado e o estado final precisam ser observados juntos.","reviewLessons":[18,28,35],"id":"q3"}]}},"css":{"courseId":"css","combos":[{"id":"combo-1","title":"Cartão legível sem largura surpresa","scenario":"Um cartão de catálogo tem título longo, botão e rótulo de disponibilidade. Ele deve caber no espaço previsto e continuar compreensível sem depender apenas de cor.","requiredLessons":[1,2,3,4,6,8],"skills":["Cascata","Box model","Overflow e informação"],"questions":[{"id":"q1","options":["284px; para um total de 240px incluindo borda e padding, use border-box e verifique o conteúdo.","240px, pois padding e borda não ocupam espaço.","264px, pois só uma lateral entra no cálculo.","280px, pois bordas nunca entram no tamanho."],"answer":0,"prompt":"O cartão usa width:240px, padding:20px e border:2px em cada lado, com box-sizing:content-box. Qual largura externa horizontal deve ser prevista antes das margens?","explanation":"Em content-box a largura declarada é do conteúdo. Some as duas laterais de padding e borda; overflow depende do espaço que o cartão realmente ocupa.","reviewLessons":[4,6]},{"id":"q2","options":["A primeira regra sempre vence porque foi carregada antes.","A declaração posterior da mesma propriedade vence, e o texto ainda comunica o estado sem depender só da cor.","A cor torna o texto desnecessário para qualquer pessoa.","Adicionar um nome de classe novo sempre apaga a herança inteira."],"answer":1,"prompt":"Duas regras normais para .status estão na mesma origem e camada, com a mesma especificidade. A segunda muda a cor, mas o rótulo textual permanece. Qual resultado combina cascata e informação acessível?","explanation":"A ordem resolve esse empate da cascata. A apresentação visual de estado deve ter uma alternativa textual ou outro sinal que preserve o significado.","reviewLessons":[1,2,3,8]},{"id":"q3","options":["Aplicar display:none ao código e ao estado para eliminar o problema.","Aumentar a largura fixa até funcionar só no monitor atual.","Investigar o mínimo e o contexto do item e permitir quebra apropriada do texto, preservando o conteúdo e o rótulo de estado.","Usar apenas vermelho para que o usuário adivinhe a parte oculta."],"answer":2,"prompt":"Um código de livro longo força o cartão para fora da tela. Qual estratégia atende conteúdo e leitura, em vez de esconder a informação?","explanation":"Conteúdo extremo precisa de regra de adaptação. Corrija os limites de tamanho e a quebra conforme o domínio, sem remover uma informação necessária apenas para a tela caber.","reviewLessons":[4,6,8]}]},{"id":"combo-2","title":"Layout de página e componente reutilizável","scenario":"Um painel tem área principal em Grid e barra de ações em Flexbox. O mesmo cartão será usado na página inteira e numa lateral estreita.","requiredLessons":[10,11,13,15,16,18],"skills":["Flexbox e mínimos","Grid fluido","Container queries"],"questions":[{"id":"q1","options":["flex-shrink garante ignorar qualquer mínimo de conteúdo.","Trocar o texto por um espaço vazio é a única solução.","Grid no ancestral elimina todos os mínimos de qualquer descendente.","O mínimo automático do item pode impedir a redução; avaliar min-width:0 ou o mínimo lógico adequado e o tratamento do conteúdo."],"answer":3,"prompt":"Um item flex contém texto longo e não encolhe como esperado apesar de flex-shrink. Qual hipótese e ajuste devem ser testados?","explanation":"O algoritmo flex respeita limites mínimos. O ajuste precisa permitir o tamanho pretendido e ainda definir como o texto será mostrado.","reviewLessons":[10,11,16]},{"id":"q2","options":["Limitar o mínimo ao espaço disponível, por exemplo minmax(min(100%,15rem),1fr), e testar a grade no container estreito.","Assumir que 1fr sempre reduz qualquer mínimo fixo.","Acrescentar mais colunas fixas de 15rem.","Usar overflow:hidden na página e ignorar os itens cortados."],"answer":0,"prompt":"A grade usa repeat(auto-fit,minmax(15rem,1fr)), mas o container fica menor que 15rem. Como tornar o mínimo compatível com esse caso?","explanation":"A trilha tem um mínimo; fr distribui o restante sem apagar esse limite. Um mínimo que considera a largura disponível melhora a resiliência do componente.","reviewLessons":[13,15,16]},{"id":"q3","options":["Somente uma media query de viewport grande, pois ela conhece a lateral.","Uma container query sobre um ancestral de consulta adequado, mantendo uma base utilizável sem a melhoria.","Uma largura fixa igual à largura do monitor do autor.","A ordem física do arquivo CSS como substituto de uma condição de tamanho."],"answer":1,"prompt":"O cartão precisa mudar sua disposição quando estiver numa lateral estreita, mesmo com viewport grande. Qual condição corresponde ao requisito?","explanation":"O tamanho do componente pode variar independentemente do viewport. Declare o contexto de consulta e verifique a composição nos dois lugares.","reviewLessons":[13,16,18]}]},{"id":"combo-3","title":"Estados, teclado e camadas visuais","scenario":"Um formulário tem validação, cabeçalho sticky e diálogo visual. A interface deve funcionar por teclado e respeitar preferência de movimento reduzido.","requiredLessons":[19,20,21,23,24,26],"skills":["Foco e estados","Sticky e stacking context","Movimento reduzido"],"questions":[{"id":"q1","options":["Remover todo outline e declarar o problema resolvido.","Mudar apenas a cor do botão sem conferir sua posição.","Verificar a região de rolagem, a posição do foco e medidas como scroll-margin para manter o controle focalizado visível.","Impedir uso de Tab em toda a página."],"answer":2,"prompt":"O botão recebe foco, mas o cabeçalho sticky cobre o controle. Qual revisão combina navegação e rolagem?","explanation":"Foco precisa ser perceptível e o alvo não deve ficar encoberto. Sticky atua no contexto de rolagem; teste a sequência real de teclado.","reviewLessons":[19,21,23]},{"id":"q2","options":["Usar um número maior garante atravessar todos os contextos.","Remover os rótulos do formulário para reduzir a pilha.","Adicionar uma transição para que o z-index deixe de importar.","Inspecionar os contextos dos ancestrais e ajustar a estrutura/camada correta, em vez de apenas aumentar o número no descendente."],"answer":3,"prompt":"Um painel com z-index:9999 continua atrás de outro porque pertence a um stacking context inferior. Qual investigação é apropriada?","explanation":"z-index é comparado dentro de hierarquias de empilhamento. Identifique quem cria o contexto e qual relação de camadas o produto precisa.","reviewLessons":[20,23,24]},{"id":"q3","options":["Manter mensagem/rótulo e foco visíveis, e reduzir ou remover a animação não essencial quando a preferência pedir.","Retirar a mensagem para usuários com movimento reduzido.","Usar apenas animação como indicação de erro.","Desativar o formulário inteiro sempre que houver erro."],"answer":0,"prompt":"A validação muda cor e executa uma animação longa. Qual comportamento preserva informação e respeita prefers-reduced-motion?","explanation":"O estado não pode depender apenas de cor ou movimento. A adaptação reduz o efeito, sem suprimir a informação necessária à tarefa.","reviewLessons":[19,20,21,26]}]},{"id":"combo-4","title":"Tema, arquitetura e saída compartilhável","scenario":"O painel recebe temas claro/escuro, conteúdo em outra direção de escrita e uma versão impressa. As regras precisam continuar previsíveis sem crescer em especificidade.","requiredLessons":[25,28,29,31,34,35],"skills":["Tokens e layers","Direção de escrita","Impressão e resiliência"],"questions":[{"id":"q1","options":["Afirmar que layers sempre vencem qualquer regra sem camada.","A ordem das camadas e a presença de regras fora delas, antes de aumentar a especificidade dos componentes.","Adicionar !important a todas as declarações como arquitetura padrão.","Remover todos os tokens de tema, mesmo os que não participam do conflito."],"answer":1,"prompt":"Uma regra normal sem layer vence o estilo normal colocado numa layer, apesar da intenção de centralizar os componentes. O que revisar primeiro?","explanation":"A cascata considera camadas antes de comparar especificidade nesse cenário. Organize o sistema de regras; não trate cada conflito apenas com um seletor mais forte.","reviewLessons":[25,28,29]},{"id":"q2","options":["Fixar margin-left em todos os componentes e assumir que início sempre é esquerda.","Duplicar todo o conteúdo em HTML para cada idioma.","Usar propriedades lógicas como margin-inline-start/end conforme o lado pretendido e testar as duas direções.","Usar a cor do tema para determinar o espaçamento."],"answer":2,"prompt":"O espaçamento do ícone deve ficar no início da linha em LTR e RTL. Qual escolha expressa a intenção e reduz duplicação?","explanation":"Propriedades lógicas descrevem relações de escrita, não só lados físicos. Teste direção, conteúdo e o espaço disponível.","reviewLessons":[25,31,35]},{"id":"q3","options":["Ocultar toda seção que tenha rolagem, incluindo os dados.","Assumir que a tela e a impressão têm exatamente os mesmos limites.","Forçar tema escuro e chamar isso de versão impressa testada.","Criar regras de impressão que exponham o conteúdo necessário, ajustem overflow/tamanho e sejam verificadas na prévia de impressão."],"answer":3,"prompt":"Na impressão, botões podem sumir, mas dados importantes do relatório não podem ser cortados por um container rolável. Qual revisão atende ao objetivo?","explanation":"Impressão é outro contexto de apresentação. Preservar informação exige conferir as quebras, a extensão do conteúdo e os elementos realmente dispensáveis.","reviewLessons":[31,34,35]}]}],"finalProject":{"id":"final","title":"Painel de biblioteca responsivo e acessível","scenario":"Entregue uma interface de catálogo, empréstimos e relatório de uma biblioteca fictícia usando HTML semântico e CSS. O projeto deve resistir a conteúdo longo, teclado, zoom, temas e impressão; a avaliação visual exige observação real no navegador.","requirements":["Criar páginas ou estados de catálogo, formulário de empréstimo e relatório com estrutura HTML e rótulos claros.","Organizar tokens, camadas e componentes para que a aparência possa variar sem especificidade descontrolada.","Combinar Flexbox e Grid com mínimos e comportamento fluidos em espaços de 320px até desktop.","Garantir foco perceptível, mensagens de estado compreensíveis e reflow com conteúdo longo e zoom.","Oferecer temas e adaptação de movimento e direção sem eliminar informação ou dependência exclusiva de cor.","Preparar saída de impressão do relatório e registrar uma revisão manual com limites e falhas encontradas."],"deliverables":["Arquivos HTML/CSS e assets locais necessários, com conteúdo fictício e estados de teste.","README com estrutura dos estilos, instruções para abrir e matriz de cenários.","Registro de revisão de largura, zoom, teclado, temas, direção e movimento, com observações reais.","Relatório impresso/PDF de teste e lista de ajustes ou limitações ainda observados."],"rubric":[{"id":"r1","title":"Estrutura e significado","description":"Os controles têm rótulos e o conteúdo mantém uma hierarquia compreensível.","reviewLessons":[1,7,8,19,20]},{"id":"r2","title":"Arquitetura de estilos","description":"Tokens, escopo e camadas explicam os conflitos sem elevar seletor a cada alteração.","reviewLessons":[3,25,28,29,30]},{"id":"r3","title":"Layout adaptável","description":"Flex/Grid e mínimos suportam conteúdo e containers variados sem esconder erros de tamanho.","reviewLessons":[4,6,10,11,13,15,16,18]},{"id":"r4","title":"Interação acessível","description":"Foco, estados e ordem do documento são conferidos por teclado e sob reflow.","reviewLessons":[14,19,20,21,23,24]},{"id":"r5","title":"Preferências e direção","description":"Temas e movimento respeitam preferência; propriedades lógicas atendem LTR/RTL.","reviewLessons":[25,26,27,31,35]},{"id":"r6","title":"Saída e diagnóstico","description":"Impressão e DevTools geram evidências reais; não se anuncia correção visual automática.","reviewLessons":[32,33,34,35,36]}],"acceptance":[{"title":"Conteúdo extremo e reflow","setup":"Use título de 150 caracteres, URL longa, lista vazia e vinte registros fictícios.","input":"Abra em 320px e desktop e aplique zoom de 200%, observando rolagem e conteúdo.","expected":"Controles e informação continuam acessíveis; rolagem localizada justificada é distinta de conteúdo essencial cortado. Registre qualquer exceção.","reviewLessons":[4,6,15,16,21,35]},{"title":"Teclado e preferências","setup":"Prepare formulário com erro e painel com cabeçalho sticky.","input":"Percorra por Tab/Shift+Tab, ative controles e teste movimento reduzido, temas e direção RTL.","expected":"Foco permanece perceptível e não encoberto; mensagens não dependem só de cor; a redução de movimento não remove a função.","reviewLessons":[19,20,23,24,26,31]},{"title":"Impressão do relatório","setup":"Preencha relatório com dados suficientes para mais de uma página.","input":"Abra a prévia de impressão e revise todas as páginas ou exporte um PDF de conferência.","expected":"Dados e cabeçalhos necessários aparecem sem recorte por overflow; controles dispensáveis são removidos conscientemente. A inspeção é manual.","reviewLessons":[21,33,34,35]}],"questions":[{"id":"q1","options":["Não; a informação cortada precisa de um desenho de layout ou rolagem apropriado, não só ocultação do sintoma.","Sim, ausência de barra horizontal prova que nenhum conteúdo foi perdido.","Sim, qualquer elemento fora da tela é opcional.","Não, porque media queries não podem ser usadas."],"answer":0,"prompt":"O projeto escondeu o overflow do body e a barra lateral sumiu em 320px. Isso comprova adaptação responsiva?","explanation":"Reflow precisa preservar uso e conteúdo. Investigue o elemento que ultrapassa os limites e as restrições de layout antes de esconder a página.","reviewLessons":[6,11,16,21,35]},{"id":"q2","options":["A criação obrigatória de um servidor backend.","Informação de estado redundante e compreensível, além da apresentação por cor.","A remoção de todos os tokens de tema.","Nenhum requisito, pois trocar cor basta para todos."],"answer":1,"prompt":"O tema escuro ficou legível, mas o estado de erro só muda de verde para vermelho e não tem mensagem. Qual requisito permanece ausente?","explanation":"Contraste e cor fazem parte da apresentação; o significado de erro também precisa de texto/estrutura ou outra indicação adequada.","reviewLessons":[8,19,20,25]},{"id":"q3","options":["Sim, um quiz executa qualquer navegador automaticamente.","Sim, responder sobre Grid substitui abrir o layout.","Não; os cenários reais de largura, foco, conteúdo e impressão ainda precisam ser observados.","Não, porque conceitos nunca ajudam a diagnosticar."],"answer":2,"prompt":"As três perguntas conceituais foram respondidas corretamente. Isso prova que todo o CSS do projeto não tem falhas visuais?","explanation":"Correção conceitual e inspeção do artefato são evidências complementares. Use os roteiros de aceitação para registrar o comportamento real.","reviewLessons":[18,19,33,34,35]}]}},"docker":{"courseId":"docker","combos":[{"id":"combo-1","title":"Imagem, processo e dados persistentes","scenario":"Uma equipe publica uma aplicação de anotações. O serviço lê /dados/notas.txt, o processo encerra ao receber SIGTERM e os dados devem sobreviver à troca do container.","requiredLessons":[2,3,4,5,8,9],"skills":["Imagem e contexto","Processo principal","Volume e recuperação"],"questions":[{"id":"q1","options":["Montar um volume em /dados e testar a reabertura dos dados no container novo.","Alterar somente a tag da imagem para persistente.","Usar EXPOSE 8080 sem volume.","Executar docker stop e concluir que docker rm terá o mesmo efeito sobre os dados."],"answer":0,"prompt":"O arquivo foi criado apenas na camada gravável do container. Depois de remover o container e criar outro da mesma imagem, o que preservaria o arquivo por projeto?","explanation":"A imagem e a camada gravável não substituem um volume independente. Revise remoção de containers e o ciclo de vida do volume; a prova é ler os dados depois da substituição.","reviewLessons":[2,8]},{"id":"q2","options":["Substituir COPY por EXPOSE e manter a pasta no contexto.","Restringir o contexto com .dockerignore e manter dados de execução em volume próprio.","Mudar WORKDIR para /dados e assumir que isso cria um volume.","Criar uma tag nova e conservar todo o contexto."],"answer":1,"prompt":"O Dockerfile usa COPY . /app e o contexto contém uma pasta de dados locais. Qual combinação evita transportar esses dados por acidente e separa a persistência?","explanation":"COPY trabalha a partir do contexto de build; WORKDIR só muda o diretório de trabalho. Conteúdo de execução deve ter ciclo de vida separado da imagem.","reviewLessons":[4,5,8]},{"id":"q3","options":["O número de containers listados por docker ps, sem conferir o arquivo.","Uma porta publicada em todas as interfaces.","Abrir a cópia restaurada em um novo container e verificar um conteúdo conhecido.","Somente o tamanho não zero de um arquivo chamado backup."],"answer":2,"prompt":"A equipe copiou os arquivos do volume, mas ainda não iniciou um container com o destino restaurado. Qual evidência está faltando?","explanation":"Uma cópia só se torna evidência de recuperação ao ser reaberta e conferida. Faça a verificação no destino, sem sobrescrever o volume de origem.","reviewLessons":[3,8,9]}]},{"id":"combo-2","title":"Aplicação e banco em Compose","scenario":"Um serviço HTTP e seu banco local devem conversar pela rede interna do Compose. Somente a aplicação precisa ser acessível no host; o build não pode deixar credenciais na imagem.","requiredLessons":[10,11,13,14,15,18],"skills":["DNS por serviço","Publicação restrita","Readiness e segredos"],"questions":[{"id":"q1","options":["Publicar 5432 em 0.0.0.0 e manter localhost dentro de app.","Trocar apenas EXPOSE por uma porta maior.","Colocar a senha no nome da rede e manter o endereço.","Usar db:5432 na configuração da aplicação e deixar a porta do banco sem publicação no host."],"answer":3,"prompt":"O serviço app tenta conectar em localhost:5432 e o banco está no serviço db da mesma rede. Qual ajuste atende à comunicação e evita exposição desnecessária?","explanation":"Dentro de app, localhost é o próprio container. O DNS interno resolve o serviço db; exposição ao host é uma decisão diferente da comunicação entre serviços.","reviewLessons":[10,11,13,14]},{"id":"q2","options":["Definir um healthcheck apropriado, condicionar a dependência à saúde e manter retentativas limitadas na aplicação.","Adicionar somente sleep infinito em app.","Assumir que estar running equivale a aceitar consultas.","Publicar a porta do banco em toda interface para acelerar o boot."],"answer":0,"prompt":"depends_on iniciou db antes de app, mas a primeira conexão falhou porque o banco ainda inicializava. Qual solução combina ordem e prontidão?","explanation":"Ordem de criação não garante prontidão. O sinal de saúde precisa verificar a capacidade necessária, e a aplicação ainda deve tolerar falhas transitórias.","reviewLessons":[13,14,15]},{"id":"q3","options":["Porque ARG sempre fica criptografado dentro da imagem.","ARG pode deixar o segredo em lugares do build ou metadados; um mount de segredo é temporário e não deve ser copiado para camadas.","Porque qualquer variável em Compose vira automaticamente segredo de build.","Porque secret mount permite publicar a credencial no README."],"answer":1,"prompt":"Uma etapa de build baixa uma dependência privada. Por que ARG TOKEN seguido de RUN não é a mesma garantia de um secret mount temporário?","explanation":"Configuração, segredo de runtime e segredo temporário de build possuem fronteiras diferentes. Mesmo com mount, o comando não deve gravar o segredo no resultado.","reviewLessons":[14,18]}]},{"id":"combo-3","title":"Imagem pequena, processo saudável e limites","scenario":"A aplicação cresce e passa por builds repetidos. O container deve respeitar memória/CPU, executar com menos privilégios e encerrar sem perder trabalho em andamento.","requiredLessons":[16,17,19,20,23,24],"skills":["Build multi-stage","Recursos e privilégio mínimo","Diagnóstico de encerramento"],"questions":[{"id":"q1","options":["Copiar todo o diretório raiz do builder e chamar isso de multi-stage.","Remover limites de memória para compensar a imagem maior.","Copiar apenas os artefatos necessários para o estágio final e configurar um usuário de execução apropriado.","Usar exec no container como substituto permanente do Dockerfile."],"answer":2,"prompt":"O estágio final precisa somente do binário, mas recebeu compilador e cache do estágio de build. Qual alteração atende tamanho e superfície de execução?","explanation":"Multi-stage é útil quando há uma fronteira de artefatos. O estágio final deve conter o necessário para rodar, com usuário e permissões compatíveis.","reviewLessons":[16,17,20]},{"id":"q2","options":["Concluir OOM só porque exit code é diferente de zero.","Aumentar memória indefinidamente sem reproduzir a carga.","Adicionar cache de build ao container em execução.","Correlacionar inspect, estado OOMKilled, logs e métricas de uso com o instante da falha."],"answer":3,"prompt":"O container termina sob carga. Como diferenciar problema de memória de um encerramento normal antes de alterar o limite?","explanation":"Exit code isolado não explica a causa. Observe recursos e evidências do processo; uma mudança de limite precisa de uma hipótese e um ensaio comparável.","reviewLessons":[19,23,24]},{"id":"q3","options":["Usar a forma exec apropriada ou um init adequado e verificar que o servidor recebe o sinal e termina dentro do prazo.","Transformar o healthcheck em comando de build.","Parar de enviar qualquer sinal e usar apenas encerramento forçado.","Executar como root para que sinais passem automaticamente ao filho."],"answer":0,"prompt":"Um shell permanece como PID 1 e não encaminha SIGTERM ao servidor filho. Que mudança deve ser testada junto da rotina de encerramento?","explanation":"A árvore de processos e o comportamento de PID 1 afetam entrega de sinais. Saúde e encerramento são verificações diferentes; teste os efeitos na aplicação.","reviewLessons":[20,23,24]}]},{"id":"combo-4","title":"Entrega reproduzível e recuperação","scenario":"Uma versão nova foi publicada num registry local. A equipe precisa provar qual imagem executou, detectar uma regressão e recuperar o banco sem depender de uma tag mutável.","requiredLessons":[28,29,30,31,32,33],"skills":["Testes de entrega","Identidade de imagem","Rollback e restauração"],"questions":[{"id":"q1","options":["Guardar apenas o texto latest no histórico.","Registrar digest e configuração da versão anterior e testar a implantação dessa referência exata.","Apagar a versão anterior imediatamente após o push.","Usar SBOM como substituto do conteúdo da imagem."],"answer":1,"prompt":"A tag atual aponta para outro conteúdo após um novo push. Como tornar a versão implantada identificável e permitir uma reversão reproduzível?","explanation":"A tag é um nome mutável. Digest identifica o conteúdo; rollback também depende de configuração e compatibilidade de dados, não só da referência.","reviewLessons":[29,30,31,33]},{"id":"q2","options":["Porque testes em container nunca validam nada.","Porque o registry reverte o banco automaticamente.","O esquema/dados podem ter deixado de ser compatíveis; é necessário um plano de compatibilidade e recuperação testado.","Porque trocar um digest apaga toda migração."],"answer":2,"prompt":"Os testes da imagem passaram, mas a migração da versão nova alterou o banco. Por que voltar apenas a imagem antiga pode não recuperar o serviço?","explanation":"Testes de imagem e reversão de dados cobrem riscos diferentes. Documente a migração, a janela de compatibilidade e o procedimento de recuperação.","reviewLessons":[28,31,32,33]},{"id":"q3","options":["Marcar sucesso porque o arquivo foi importado sem erro de shell.","Sobrescrever a origem até os números coincidirem.","Afirmar que provenance substitui consultas de validação.","Investigar a divergência e manter o ensaio de recuperação como não concluído, preservando origem e logs."],"answer":3,"prompt":"Um dump foi importado num banco vazio separado e as consultas de conferência divergiram. Qual decisão corresponde à evidência?","explanation":"Restauração precisa preservar as propriedades esperadas do dado. Logs, retorno do processo e conferência de domínio devem concordar antes de concluir.","reviewLessons":[30,32,33]}]}],"finalProject":{"id":"final","title":"Serviço de catálogo com entrega e recuperação demonstradas","scenario":"Entregue um catálogo fictício com uma aplicação HTTP e um banco local. Outra pessoa deve conseguir iniciar a versão documentada, executar os testes, substituir o container e recuperar uma cópia sem credenciais nos arquivos publicados.","requirements":["Construir a imagem da aplicação com estágio final contendo somente artefatos de execução e usuário adequado.","Executar aplicação e banco por Compose, usando DNS interno e publicando somente a entrada necessária no host.","Separar configuração, segredos e dados; os dados precisam sobreviver à substituição do container.","Definir healthcheck, recursos e rotina de encerramento com observação do processo.","Executar testes locais antes de publicar num registry de laboratório e registrar digest e configuração da entrega.","Produzir backup lógico, restaurar em destino separado e demonstrar rollback de aplicação com análise de compatibilidade dos dados."],"deliverables":["Dockerfile, .dockerignore e compose.yaml sem credenciais reais.","README com ambiente, comandos, versão/digest, entradas de teste e limites do laboratório.","Relatório de testes, prontidão, recursos e encerramento com saídas reais identificadas.","Runbook de backup, restauração e rollback com evidências do destino recuperado."],"rubric":[{"id":"r1","title":"Imagem reproduzível","description":"O contexto exclui arquivos indevidos e o estágio final contém os artefatos definidos.","reviewLessons":[4,5,16,17]},{"id":"r2","title":"Rede e configuração","description":"A aplicação usa nomes de serviço, exposição restrita e configuração sem segredos embutidos.","reviewLessons":[10,11,13,14,18,31]},{"id":"r3","title":"Ciclo dos dados","description":"A substituição do container preserva registros via armazenamento planejado.","reviewLessons":[7,8,9]},{"id":"r4","title":"Processo operável","description":"Saúde, limites e encerramento possuem ensaios e interpretação, além de configuração declarada.","reviewLessons":[15,19,20,22,23,24]},{"id":"r5","title":"Entrega verificável","description":"Testes e identidade da imagem permitem reproduzir a versão e investigar regressões.","reviewLessons":[25,28,29,30]},{"id":"r6","title":"Recuperação demonstrada","description":"Uma cópia é aberta, conferida e relacionada ao plano de reversão e aos limites reais.","reviewLessons":[9,32,33,36]}],"acceptance":[{"title":"Dados após substituição","setup":"Inicie a stack num diretório de laboratório e crie um item identificável no catálogo.","input":"Substitua o container da aplicação e reinicie o serviço do banco mantendo o volume previsto.","expected":"O item continua consultável; registre os IDs de containers e a referência do volume, sem confundir volume com backup.","reviewLessons":[2,8,13]},{"title":"Prontidão e encerramento","setup":"Configure o healthcheck e uma operação curta observável na aplicação.","input":"Inicie a stack com banco ainda inicializando e depois solicite encerramento gracioso.","expected":"O cliente trata a indisponibilidade inicial; o processo recebe o sinal e encerra dentro do prazo definido, com logs suficientes para conferir.","reviewLessons":[15,23,24]},{"title":"Cópia recuperada e versão exata","setup":"Preserve origem, dump e digest da entrega. Crie um banco de restauração vazio separado.","input":"Restaure o dump, execute consultas de domínio e inicie a referência de aplicação compatível com esse estado.","expected":"Quantidade/valores conhecidos coincidem no destino e a versão executada corresponde ao digest registrado; divergência permanece uma falha a investigar.","reviewLessons":[29,31,32,33]}],"questions":[{"id":"q1","options":["Montagem e ciclo de vida do armazenamento, distinguindo imagem, camada gravável e volume.","Assumir que o digest deveria conter os registros do banco.","Alterar a cor da interface.","Remover o healthcheck e declarar recuperação."],"answer":0,"prompt":"No projeto, container novo inicia com banco vazio apesar de a imagem correta estar identificada por digest. Que parte revisar primeiro?","explanation":"Digest identifica a imagem, não o estado de dados. Confira destino da montagem, volume efetivamente usado e se houve troca involuntária do armazenamento.","reviewLessons":[6,8,9,29]},{"id":"q2","options":["Sim, funcionar prova que o segredo foi protegido.","Não; refaça a separação de segredos de build/runtime e revise os artefatos antes de compartilhar.","Sim, um container cifra todo arquivo automaticamente.","Não, porque Compose não aceita configuração."],"answer":1,"prompt":"A aplicação funciona, mas o segredo aparece no histórico da imagem e no compose.yaml publicado. O requisito de entrega passou?","explanation":"Funcionamento e proteção de credenciais são requisitos independentes. Elimine a exposição dos artefatos e trate qualquer credencial real exposta segundo o procedimento do serviço.","reviewLessons":[14,18,30,31]},{"id":"q3","options":["Tudo passou porque algum banco abriu.","Tudo passou porque a tag antiga existe.","Recuperação da cópia passou, porém rollback da aplicação está bloqueado pela incompatibilidade ainda não resolvida.","Backup e rollback são sempre a mesma operação."],"answer":2,"prompt":"O backup restaurou corretamente, mas a imagem anterior não entende o esquema novo. Qual resultado deve constar no relatório de rollback?","explanation":"Relate separadamente a cópia recuperada e a compatibilidade da versão. Um resultado positivo não elimina a falha do outro caminho.","reviewLessons":[28,31,32,33]}]}},"go":{"courseId":"go","combos":[{"title":"Catálogo e reserva com erro explícito","scenario":"Uma CLI em Go mantém produtos por SKU, recebe texto UTF-8 e tenta reservar unidades. O catálogo não pode criar produto ao consultar uma chave ausente nem alterar o saldo quando a regra falha.","requiredLessons":[4,5,6,7,9],"skills":["Coleções","Métodos","UTF-8 e erros"],"questions":[{"prompt":"O catálogo map[string]int contém A:3 e não contém B. A consulta saldo := catalogo[\"B\"] devolve 0. Como distinguir B ausente de um produto existente com saldo zero antes de reservar?","options":["Usar saldo, ok := catalogo[sku] e validar ok e quantidade antes de alterar o map.","Tratar todo saldo zero como SKU inexistente, sem outra informação.","Inserir o SKU automaticamente sempre que a leitura retornar zero.","Contar os bytes do SKU e reservar se o comprimento for positivo."],"answer":0,"explanation":"O resultado zero não informa presença. O segundo retorno do acesso ao map separa ausência de saldo legítimo; validação precisa preceder a mutação.","reviewLessons":[4,5,9],"id":"q1"},{"prompt":"Uma função recebe p Produto por valor e faz p.Estoque -= 2; o chamador continua com saldo 3. Qual contrato permite atualizar deliberadamente o produto original e ainda recusar saldo insuficiente?","options":["Um método por valor sem retorno, pois structs sempre compartilham todos os campos.","Um método com receptor *Produto que valida a quantidade e retorna erro antes de alterar o campo.","Um panic obrigatório para qualquer saldo insuficiente.","Converter o saldo para string e concatenar -2."],"answer":1,"explanation":"A struct recebida por valor é copiada. Um receptor ponteiro torna a alteração do original explícita, enquanto error representa a recusa esperada.","reviewLessons":[4,7,9],"id":"q2"},{"prompt":"O nome do produto é \"ação\". A interface precisa limitar a quatro pontos de código Unicode e manter a mensagem de erro. Qual abordagem corresponde a esse requisito?","options":["Usar len(nome)==4, porque toda letra UTF-8 ocupa um byte.","Cortar sempre nos primeiros quatro bytes, mesmo no meio de uma codificação.","Contar runes, sem supor que len da string mede caracteres, e retornar erro de validação ao exceder o limite.","Remover a validação, porque strings não podem ter regras."],"answer":2,"explanation":"len mede bytes em Go. Runas representam pontos de código; isso ainda não equivale a grafemas visuais, portanto o contrato deve usar a unidade definida.","reviewLessons":[4,6,9],"id":"q3"}],"id":"combo-1"},{"title":"Importação cancelável e testes de fronteira","scenario":"Um importador lê registros JSON de um Reader, valida cada pedido e processa tarefas por um pool limitado. Cancelar deve liberar recursos e os testes precisam provar a regra sem depender de sleeps.","requiredLessons":[11,12,13,16,17,18],"skills":["I/O","Testes","Cancelamento e sincronização"],"questions":[{"prompt":"O pool recebe cancelamento quando um worker tenta enviar o último resultado para um consumidor que já saiu. Qual desenho evita deixar a goroutine presa?","options":["Aumentar o buffer sem limite e assumir que todo consumidor voltará.","Usar time.Sleep(1*time.Second) como prova de término.","Fechar o canal de resultados a partir de qualquer worker, mesmo com outros enviando.","Fazer o envio selecionar entre o canal de resultados e ctx.Done(), e aguardar os workers no encerramento."],"answer":3,"explanation":"Cancelamento precisa alcançar operações bloqueantes. A posse do fechamento e a espera pelos workers dão um ciclo de vida definido.","reviewLessons":[16,17,18],"id":"q1"},{"prompt":"O registro tem quantidade 0, e a regra exige quantidade positiva. Qual teste oferece evidência útil do importador?","options":["Fornecer um Reader com esse JSON, verificar o erro de domínio e confirmar que nenhum pedido foi aplicado.","Testar somente se o programa imprime alguma linha.","Usar uma rede pública para introduzir demora aleatória.","Executar benchmark e considerar rapidez como correção."],"answer":0,"explanation":"O caso de fronteira deve falhar pela razão prevista e conservar o estado. Reader e dados locais controlam a entrada do ensaio.","reviewLessons":[11,12,13],"id":"q2"},{"prompt":"Quatro workers atualizam um total com total += valor. Todos terminam, mas o resultado varia. Qual correção protege o invariante?","options":["Aguardar a execução por dois segundos e manter o acesso sem sincronização.","Proteger leitura e escrita do total com sincronização apropriada, ou centralizar a soma num consumidor, e testar também com o detector de corrida.","Adicionar mais goroutines para compensar perdas.","Assumir que terminar as goroutines torna toda escrita anterior atômica."],"answer":1,"explanation":"Esperar o término resolve o ciclo de vida, mas não protege atualizações concorrentes. A região compartilhada precisa de sincronização ou de outro modelo de propriedade.","reviewLessons":[13,16,18],"id":"q3"}],"id":"combo-2"},{"title":"Confirmação HTTP com persistência","scenario":"Uma API recebe uma chave idempotente e confirma um pedido, reservando estoque no banco. Autorização e validação antecedem os efeitos; a mesma confirmação pode chegar de novo após timeout.","requiredLessons":[19,20,21,22,23,24],"skills":["HTTP","Autorização","SQL e transações"],"questions":[{"prompt":"A API busca o pedido, debita estoque e só depois verifica se o usuário é dono. Que alteração de ordem é necessária?","options":["Manter a ordem e esconder a mensagem de saldo.","Trocar a consulta parametrizada por concatenação.","Verificar identidade e autorização sobre o recurso antes de iniciar o efeito de confirmação.","Usar status 200 também quando a autorização falhar."],"answer":2,"explanation":"Conhecer o ID de um pedido não autoriza sua confirmação. A fronteira deve recusar o acesso antes de gravar estoque ou pedido.","reviewLessons":[19,21,23],"id":"q1"},{"prompt":"A baixa de estoque foi confirmada, mas a marcação do pedido falhou em outra conexão. Como evitar esse estado parcial?","options":["Abrir uma goroutine para cada UPDATE e confirmar ambos independentemente.","Enviar a resposta HTTP antes das escritas.","Repetir apenas o UPDATE do pedido sem conhecer o estado do estoque.","Usar a mesma transação para checar e gravar os efeitos e fazer rollback em qualquer falha, conferindo o resultado da baixa condicional."],"answer":3,"explanation":"O invariante atravessa várias escritas. Todas precisam compartilhar o limite transacional e o cliente deve verificar se a condição de estoque foi atendida.","reviewLessons":[22,23,24],"id":"q2"},{"prompt":"O cliente recebeu timeout após o servidor possivelmente confirmar. Qual contrato permite repetir a chamada sem reservar de novo?","options":["Uma chave de operação única persistida junto dos efeitos, com verificação de conteúdo e retorno do resultado anterior para a mesma operação.","Supor que timeout sempre desfez a transação.","Gerar nova chave em toda tentativa automática.","Guardar a chave só numa variável do handler e reiniciar o processo para limpar."],"answer":0,"explanation":"Timeout deixa o resultado incerto. Identidade durável da operação e atomicidade dos seus efeitos permitem reconhecer uma repetição válida.","reviewLessons":[20,22,23],"id":"q3"}],"id":"combo-3"},{"title":"Serviço observável sob falha e encerramento","scenario":"O serviço possui worker pool, dependências HTTP e shutdown com prazo. Uma investigação deve separar custo de CPU, retenção de memória e falhas de entrega, sem prometer exatamente uma vez entre sistemas.","requiredLessons":[28,29,30,31,32,35],"skills":["Diagnóstico","Shutdown","Repetição distribuída"],"questions":[{"prompt":"Durante shutdown, novas requisições continuam entrando e os workers aguardam para sempre uma API externa. Qual protocolo precisa ser combinado?","options":["Encerrar o processo imediatamente e anunciar que toda tarefa terminou.","Parar a admissão, propagar cancelamento ou prazo às dependências e aguardar trabalho em andamento até um limite explícito.","Esperar sem prazo, pois isso sempre garante durabilidade.","Usar um único sleep como substituto de sinais e espera."],"answer":1,"explanation":"Encerramento exige limite de admissão, cooperação das operações e prazo. Um processo sair não prova a conclusão dos efeitos.","reviewLessons":[30,31,35],"id":"q1"},{"prompt":"O serviço retém pedidos antigos numa fila sem limite. A CPU está baixa, mas a memória cresce. Qual primeira investigação corresponde ao sintoma?","options":["Aumentar goroutines porque memória sempre significa falta de CPU.","Reescrever todos os handlers sem coletar evidência.","Medir retenção e tamanho da fila com uma carga reproduzível, usar perfil de memória e definir limites/descartes conforme o contrato.","Declarar vazamento apenas porque ocorreu uma coleta de lixo."],"answer":2,"explanation":"Alocação e retenção não são a mesma medida. Uma fila que continua referenciando objetos pode impedir sua coleta mesmo sem alta CPU.","reviewLessons":[28,29,32],"id":"q2"},{"prompt":"Um worker fez o efeito externo e caiu antes de confirmar a mensagem da fila. Qual requisito continua necessário na reentrega?","options":["Anunciar exatamente uma vez só por usar goroutines.","Confirmar toda mensagem antes do efeito para eliminar qualquer perda.","Apagar os identificadores das operações após cada tentativa.","Reconhecer a operação já aplicada no destino e tratar repetição de maneira idempotente, com retenção e rastreabilidade."],"answer":3,"explanation":"Existe uma janela entre efeito e confirmação. O protocolo precisa tolerar reentrega onde o efeito é decidido e explicar seus limites.","reviewLessons":[31,32,35],"id":"q3"}],"id":"combo-4"}],"finalProject":{"id":"final","title":"Central de reservas em Go","scenario":"Entregue uma aplicação local de reserva de equipamentos, acessível por CLI e HTTP, que mantém disponibilidade e histórico sob repetição, erro e encerramento. Use dados fictícios e dependências locais substituíveis.","requirements":["Validar SKU, quantidade positiva e transições de reserva antes de alterar o estado.","Reutilizar o mesmo caso de uso por CLI e HTTP, com códigos de saída/status e mensagens de erro coerentes.","Persistir reserva, baixa condicional e chave idempotente na mesma transação, sem SQL concatenado.","Executar tarefas auxiliares com capacidade limitada, cancelamento e propriedade clara dos recursos.","Manter testes de fronteira, duplicata, falha intermediária, autorização e corrida, incluindo verificação do estado final.","Documentar build, configuração sem segredos, backup/restauração local, logs correlacionados e shutdown com prazo."],"deliverables":["Código do módulo com CLI, API e adaptador de persistência.","Testes automatizados e resultados locais, com fixtures e comandos exatos.","README de instalação, contratos, decisões e limites.","Runbook de recuperação e encerramento com evidências do destino restaurado."],"rubric":[{"id":"r1","title":"Contratos de domínio","description":"Validar SKU, quantidade positiva e transições de reserva antes de alterar o estado.","reviewLessons":[4,7,9,21]},{"id":"r2","title":"Duas interfaces","description":"Reutilizar o mesmo caso de uso por CLI e HTTP, com códigos de saída/status e mensagens de erro coerentes.","reviewLessons":[10,12,19,24]},{"id":"r3","title":"Persistência consistente","description":"Persistir reserva, baixa condicional e chave idempotente na mesma transação, sem SQL concatenado.","reviewLessons":[22,23]},{"id":"r4","title":"Concorrência com limites","description":"Executar tarefas auxiliares com capacidade limitada, cancelamento e propriedade clara dos recursos.","reviewLessons":[16,17,18,30]},{"id":"r5","title":"Evidências de correção","description":"Manter testes de fronteira, duplicata, falha intermediária, autorização e corrida, incluindo verificação do estado final.","reviewLessons":[13,14,15,21,23]},{"id":"r6","title":"Entrega e recuperação","description":"Documentar build, configuração sem segredos, backup/restauração local, logs correlacionados e shutdown com prazo.","reviewLessons":[28,31,32,33,35,36]}],"acceptance":[{"title":"Reserva válida","setup":"SKU A possui 5 unidades; operação op-1 ainda não existe.","input":"Reservar 2 unidades de A com op-1.","expected":"Saldo 3, uma reserva confirmada e resultado persistido para op-1.","reviewLessons":[7,21,22,23]},{"title":"Repetição e conflito","setup":"op-1 já confirmou 2 unidades e saldo é 3.","input":"Repetir op-1 com mesmo conteúdo; depois reutilizar op-1 para 4 unidades.","expected":"Primeira repetição retorna resultado anterior sem baixa; conteúdo diferente é recusado e saldo permanece 3.","reviewLessons":[20,23,35]},{"title":"Falha e recuperação","setup":"Base nova com saldo 5; falha injetada depois da baixa e antes de registrar a reserva.","input":"Executar a operação, encerrar o processo e reabrir base/cópia conforme o roteiro.","expected":"Não persiste metade da operação; o estado recuperado satisfaz os invariantes e a falha aparece correlacionada nos logs.","reviewLessons":[13,17,23,31,32,36]}],"questions":[{"prompt":"O projeto passa no caminho feliz, mas não testa falha entre as duas escritas. Que evidência essencial está faltando?","options":["Um ensaio que provoque a falha intermediária e confirme rollback dos efeitos e possibilidade de repetir a operação.","Mais cores no terminal.","Um benchmark sem conferir saldo.","Apenas contar arquivos do módulo."],"answer":0,"explanation":"A unidade transacional precisa ser observada no caminho em que pode quebrar, não apenas na confirmação normal.","reviewLessons":[13,22,23],"id":"q1"},{"prompt":"CLI e HTTP implementam validações divergentes para a mesma reserva. Qual organização reduz essa inconsistência?","options":["Copiar e colar o handler em outro pacote.","Colocar a regra e a transação num caso de uso compartilhado e deixar cada adaptador traduzir entrada e saída.","Fazer o domínio depender de ResponseWriter.","Remover validação da CLI por ser local."],"answer":1,"explanation":"Fronteiras pequenas permitem reaproveitar regras sem acoplar o domínio ao protocolo de apresentação.","reviewLessons":[4,19,24],"id":"q2"},{"prompt":"O runbook contém um arquivo de backup, mas não reabre seu conteúdo. Qual situação deve permanecer não comprovada?","options":["A existência de nomes de tabelas no código.","A versão declarada no go.mod.","A capacidade de recuperar o estado e seus invariantes no destino.","A possibilidade de escrever um README."],"answer":2,"explanation":"Criar um arquivo não basta: a recuperação deve abrir e conferir os dados esperados.","reviewLessons":[22,23,32,36],"id":"q3"}]}},"java":{"courseId":"java","combos":[{"title":"Reserva tipada e comparação correta","scenario":"Uma aplicação console recebe código e quantidade, encontra um recurso e tenta reservá-lo. Estados finitos, igualdade de texto e validação na criação devem produzir resultados previsíveis.","requiredLessons":[2,3,4,6,7,8],"skills":["Tipos","Igualdade","Invariantes e estados"],"questions":[{"prompt":"O código digitado tem o mesmo conteúdo de um código carregado, mas codigo == cadastrado retorna false. Qual comparação e validação correspondem à busca?","options":["Comparar conteúdo com equals de forma segura para a nulidade e validar a quantidade antes de efetuar a reserva.","Manter == porque strings de entrada sempre compartilham a mesma referência.","Usar apenas o comprimento das duas strings.","Reservar primeiro e comparar conteúdo depois."],"answer":0,"explanation":"== compara referências de objetos. Igualdade de conteúdo e regra da quantidade precisam ser verificadas antes da alteração do recurso.","reviewLessons":[3,4,6,7],"id":"q1"},{"prompt":"A taxa é calculada por int percentual = 3/2*100 e aparece 100 em vez de 150. Qual revisão separa representação e regra?","options":["Mudar o texto exibido para 150 sem alterar o cálculo.","Reconhecer a divisão inteira e escolher um cálculo com escala/tipo adequado, preservando a validação dos limites.","Esperar que multiplicar depois recupere a parte fracionária já perdida.","Trocar todos os nomes para String."],"answer":1,"explanation":"3/2 com inteiros produz 1; a multiplicação posterior não recupera a fração. A representação deve corresponder à unidade pretendida.","reviewLessons":[2,3,4],"id":"q2"},{"prompt":"Uma Reserva pode nascer com quantidade -1 e só depois receber estado CONFIRMADA. Que contrato impede criar esse objeto inválido?","options":["Deixar todos os campos públicos para qualquer valor.","Usar números mágicos e presumir que a interface enviará dados corretos.","Validar no construtor/fábrica e nas transições, representando os estados permitidos com um tipo finito apropriado.","Validar apenas quando imprimir o objeto."],"answer":2,"explanation":"Encapsulamento protege o invariante desde a criação. Enum representa o conjunto de estados, mas a legalidade de cada transição continua sendo uma regra.","reviewLessons":[3,7,8],"id":"q3"}],"id":"combo-1"},{"title":"Relatório com coleções e ausência explícita","scenario":"O relatório agrupa pedidos por cliente, ordena por total e usa objetos como chaves. Um cliente pode não ter pedidos; chaves mutáveis e acumuladores externos não devem comprometer o resultado.","requiredLessons":[12,14,15,16,17,18],"skills":["Igualdade e hash","Coleções","Streams e Optional"],"questions":[{"prompt":"Um objeto usado como chave de HashMap altera um campo que participa de equals/hashCode depois de inserido. A busca falha. Qual correção preserva o contrato?","options":["Recalcular manualmente o bucket com um número fixo.","Trocar apenas o nome da variável do mapa.","Assumir que HashMap procura por todos os campos após qualquer mutação.","Usar uma chave de identidade estável e imutável, mantendo dados mutáveis fora da identidade da chave."],"answer":3,"explanation":"As regras de hash e igualdade precisam permanecer estáveis enquanto o objeto funciona como chave. Estado mutável não deve alterar essa identidade.","reviewLessons":[12,14,17],"id":"q1"},{"prompt":"Dois pedidos têm o mesmo total. O relatório exige ordem reproduzível por total e depois ID. Qual abordagem atende sem risco de overflow na subtração?","options":["Compor comparadores com comparing/thenComparing ou comparações apropriadas, incluindo o ID como desempate.","Retornar a.total-b.total como único comparador de inteiros para qualquer faixa.","Confiar que um Set produz ordem de inserção em toda implementação.","Omitir desempate porque empates não podem ocorrer em dinheiro."],"answer":0,"explanation":"Comparador deve respeitar seu contrato e o domínio numérico. Desempate explícito torna a apresentação determinística.","reviewLessons":[14,15,17],"id":"q2"},{"prompt":"A consulta devolve Optional.empty para cliente sem pedido. O que a camada de relatório deve fazer?","options":["Chamar get porque Optional sempre contém um valor.","Tratar a ausência deliberadamente, com saída ou valor de domínio definido, sem chamar get cegamente nem inventar pedido.","Converter ausência em erro de sintaxe.","Criar um pedido de valor zero sem regra de negócio."],"answer":1,"explanation":"Optional explicita um resultado possível ausente. A decisão de apresentação ou regra deve ocorrer na fronteira adequada.","reviewLessons":[16,17,18],"id":"q3"}],"id":"combo-2"},{"title":"Entrada HTTP e confirmação transacional","scenario":"Uma aplicação Maven recebe JSON de um serviço local, converte para DTO e confirma pedidos em JDBC. Testes controlam respostas e comprovam rollback quando a reserva não pode ser concluída.","requiredLessons":[20,21,23,24,25,26],"skills":["DTO e HTTP","JUnit","JDBC e atomicidade"],"questions":[{"prompt":"O JSON foi desserializado para um DTO com quantidade 0. Isso autoriza o serviço a debitar estoque?","options":["Sim, desserializar valida qualquer regra do negócio.","Sim, zero é sempre uma quantidade válida.","Não; o DTO ainda precisa de validação do domínio e o teste deve provar a recusa sem escrita.","Não, porque DTOs não podem conter números."],"answer":2,"explanation":"Mapear o formato não valida os valores do caso de uso. O teste precisa observar recusa e estado preservado.","reviewLessons":[20,21,23,26],"id":"q1"},{"prompt":"Uma consulta de cliente é montada concatenando nome recebido pelo HTTP. Qual revisão usa corretamente a fronteira JDBC?","options":["Concatenar e chamar commit para neutralizar o conteúdo.","Remover apenas espaços do nome.","Confiar que o DTO torna o texto parte segura da sintaxe SQL.","Usar PreparedStatement com parâmetros para valores, verificando o resultado e fechando os recursos."],"answer":3,"explanation":"Parâmetros mantêm valores fora da estrutura SQL. Recursos e transação precisam de ciclo de vida próprio; commit não corrige concatenação.","reviewLessons":[23,24,25,26],"id":"q2"},{"prompt":"O teste força falha depois do débito e antes de inserir a confirmação. Qual evidência demonstra atomicidade?","options":["Após rollback, estoque e quantidade de confirmações correspondem ao estado anterior, e o erro é observado pelo chamador.","Apenas verificar que houve uma exceção qualquer.","Aceitar estoque menor se não existir confirmação.","Ignorar a exceção e retornar sucesso."],"answer":0,"explanation":"Erro isolado não prova que os efeitos foram desfeitos. O teste deve conferir a unidade de estado e a propagação da falha.","reviewLessons":[20,21,25,26],"id":"q3"}],"id":"combo-3"},{"title":"Concorrência, limites e diagnóstico na JVM","scenario":"A API disputa estoque, chama dependências com tarefas concorrentes e expõe contratos HTTP. Uma investigação de desempenho deve usar evidências e o cliente não pode confundir timeout com interrupção confirmada.","requiredLessons":[27,28,29,30,31,35],"skills":["Atualização condicional","Concorrência","Timeouts e observabilidade"],"questions":[{"prompt":"Dois pedidos disputam uma unidade. Ambos leram saldo 1 antes de gravar. Qual operação permite detectar o perdedor sem saldo negativo?","options":["Proteger só uma variável local em cada requisição com volatile.","Uma baixa condicional no banco dentro da transação, conferindo quantidade de linhas alteradas e retornando conflito quando não houver efeito.","Gravar sempre zero e confirmar ambos os pedidos.","Usar mais virtual threads para tornar a disputa impossível."],"answer":1,"explanation":"A condição precisa participar da escrita que decide o efeito. Memória local e maior concorrência não substituem o invariante no banco.","reviewLessons":[27,28,35],"id":"q1"},{"prompt":"Uma virtual thread por chamada faz I/O barato, mas todas disputam um pool de dez conexões. Qual limite permanece necessário?","options":["Nenhum, porque virtual threads criam conexões de banco infinitas.","Aumentar tarefas sem limite e esconder timeout.","Controlar admissão/concorrência e tempo de espera pelo recurso escasso, observando cancelamento e saturação.","Trocar todo I/O por laços de CPU."],"answer":2,"explanation":"Virtual threads reduzem um custo de agendamento, não eliminam a capacidade finita das dependências.","reviewLessons":[27,29,30,31],"id":"q2"},{"prompt":"Um CompletableFuture estourou o prazo do resultado. Isso prova que o efeito HTTP ou SQL já parou?","options":["Sim, timeout desfaz qualquer transação externa.","Sim, toda tarefa morre no mesmo instante.","Não, porque futures nunca possuem timeout.","Não; o cancelamento e a capacidade de interromper a operação precisam ser propagados e verificados pelo protocolo."],"answer":3,"explanation":"Prazo de espera e término do trabalho são contratos diferentes. Resultado incerto também influencia repetição e a resposta da API.","reviewLessons":[29,30,35],"id":"q3"}],"id":"combo-4"}],"finalProject":{"id":"final","title":"Agenda de reservas em Java","scenario":"Construa uma aplicação local de reserva de salas/equipamentos, com interface de terminal e consulta/confirmação HTTP. As reservas devem respeitar capacidade e conservar seu resultado sob falha e repetição.","requirements":["Modelar identidades, estados e valores monetários/temporais com tipos coerentes e invariantes por construção.","Produzir filtros e relatórios por coleções/streams com tratamento de ausência, empate e vazio.","Usar JDBC parametrizado e uma transação para reserva, disponibilidade e chave idempotente, verificando a escrita condicional.","Separar casos de uso de CLI/HTTP, validar DTOs e entradas, definir status e recusar acesso indevido antes de efeitos.","Limitar trabalho concorrente, propagar interrupção/prazo e testar rejeições e falhas com JUnit e colaboradores controlados.","Fornecer build Maven/JAR reproduzível, dados locais de teste, hipótese de desempenho e restauração conferida."],"deliverables":["Projeto Maven com domínio, adaptadores e interfaces executáveis.","Testes JUnit e cenários locais de concorrência e falha.","README com comandos de build, execução, configuração e contratos.","Relatório de recuperação de dados e investigação de uma hipótese de desempenho."],"rubric":[{"id":"r1","title":"Modelo estável","description":"Modelar identidades, estados e valores monetários/temporais com tipos coerentes e invariantes por construção.","reviewLessons":[7,8,11,12]},{"id":"r2","title":"Consultas determinísticas","description":"Produzir filtros e relatórios por coleções/streams com tratamento de ausência, empate e vazio.","reviewLessons":[14,15,17,18]},{"id":"r3","title":"Persistência atômica","description":"Usar JDBC parametrizado e uma transação para reserva, disponibilidade e chave idempotente, verificando a escrita condicional.","reviewLessons":[25,26,27,36]},{"id":"r4","title":"Fronteiras e acesso","description":"Separar casos de uso de CLI/HTTP, validar DTOs e entradas, definir status e recusar acesso indevido antes de efeitos.","reviewLessons":[23,24,33,34,35]},{"id":"r5","title":"Concorrência e testes","description":"Limitar trabalho concorrente, propagar interrupção/prazo e testar rejeições e falhas com JUnit e colaboradores controlados.","reviewLessons":[20,21,28,29,30]},{"id":"r6","title":"Entrega verificável","description":"Fornecer build Maven/JAR reproduzível, dados locais de teste, hipótese de desempenho e restauração conferida.","reviewLessons":[19,22,31,32,36]}],"acceptance":[{"title":"Reserva com capacidade","setup":"Recurso R tem 3 vagas e operação res-1 ainda não existe.","input":"Reservar 2 vagas usando res-1.","expected":"Uma reserva confirmada e uma vaga disponível; resultado persistido para a operação.","reviewLessons":[7,25,26,27,36]},{"title":"Disputa pela última vaga","setup":"Uma vaga e duas conexões/tentativas independentes.","input":"Cada tentativa solicita uma vaga com chave própria.","expected":"Somente uma confirma; a outra recebe recusa/conflito e a disponibilidade não fica negativa.","reviewLessons":[20,21,26,27]},{"title":"Falha e retorno da operação","setup":"Falha de comunicação após possível commit; base reaberta conforme o roteiro.","input":"Repetir res-1 com mesmo conteúdo.","expected":"A resposta corresponde à reserva original sem nova baixa; conteúdo divergente para a chave é recusado.","reviewLessons":[24,26,34,35,36]}],"questions":[{"prompt":"A interface console e o endpoint HTTP confirmam a mesma reserva com regras diferentes. Qual parte do desenho precisa ser consolidada?","options":["O caso de uso e seus invariantes, mantendo só tradução de protocolo nos adaptadores.","Apenas a quantidade de classes.","O nome do arquivo JAR.","O método toString de todo objeto."],"answer":0,"explanation":"Reutilização deve ocorrer na regra, não na cópia de detalhes de apresentação.","reviewLessons":[9,34,35],"id":"q1"},{"prompt":"O teste de concorrência verifica apenas que as duas threads terminaram. O que falta para provar a regra da última vaga?","options":["Usar nomes diferentes nas threads apenas.","Conferir exatamente uma confirmação, a recusa concorrente e o saldo final sem negatividade.","Adicionar um sleep maior sem asserções.","Executar o teste somente no computador do autor."],"answer":1,"explanation":"Término de trabalho não comprova o invariante de negócio.","reviewLessons":[20,21,27,28],"id":"q2"},{"prompt":"Uma medição do JFR mostra espera por conexões, mas a solução proposta só troca List por Set. Qual decisão é mais fundamentada?","options":["Fazer a troca porque qualquer Set elimina espera no banco.","Descartar a medição para preservar a hipótese inicial.","Investigar a saturação e o limite do pool com a mesma carga antes de alterar estruturas sem relação com o sinal.","Afirmar que memória e espera são sempre a mesma causa."],"answer":2,"explanation":"A otimização deve corresponder à evidência observada e manter o resultado correto.","reviewLessons":[27,29,31],"id":"q3"}]}},"javascript":{"courseId":"javascript","combos":[{"title":"Relatório de carrinho sem alterar a entrada","scenario":"Um carrinho chega com preços textuais, produtos identificados por SKU e objetos compartilhados. O relatório deve validar números, calcular o total e ordenar uma cópia sem modificar o carrinho em uso.","requiredLessons":[2,4,7,8,9],"skills":["Conversão","Referências","Coleções e relatório"],"questions":[{"prompt":"O preço recebido é \"12.50\" e a quantidade é 2. Qual sequência evita somar texto e mantém a validação na regra?","options":["Converter o preço explicitamente, verificar número finito e domínio e só então calcular numa função que retorna o total.","Usar preço + quantidade, porque + sempre converte tudo em número.","Confiar que qualquer string JSON é um preço válido.","Ordenar o carrinho antes de validar e tratar NaN como zero silenciosamente."],"answer":0,"explanation":"Conversão e validação são etapas distintas. O operador + pode concatenar; um resultado inválido não deve virar total aceito.","reviewLessons":[2,4,9],"id":"q1"},{"prompt":"copia = [...carrinho] e copia[0].quantidade++ mudam o objeto observado pelo carrinho original. Qual é a explicação e a correção para esse campo simples?","options":["O spread realizou cópia profunda e o motor errou.","O spread copiou o array, mas manteve as referências aos objetos; criar também um novo objeto para o item a alterar.","Arrays nunca contêm referências a objetos.","É necessário transformar todos os objetos em variáveis globais."],"answer":1,"explanation":"Copiar o contêiner não copia recursivamente seus elementos. O nível mutável alterado precisa ser independente para preservar a entrada.","reviewLessons":[7,8,9],"id":"q2"},{"prompt":"Uma Map armazena SKU A com quantidade 0. if (!map.get(\"A\")) informa que ele não existe. Como preservar a distinção entre presença e quantidade?","options":["Tratar zero como ausência em qualquer domínio.","Apagar a chave quando get retornar falso, sem outra regra.","Consultar map.has(\"A\") para presença e validar separadamente o valor retornado por get.","Usar o tamanho do nome do SKU como quantidade."],"answer":2,"explanation":"Valor falsy não equivale a chave ausente. O contrato do catálogo deve separar identidade e valor do estoque.","reviewLessons":[2,8,9],"id":"q3"}],"id":"combo-1"},{"title":"Modelo testável com fronteira de entrada","scenario":"Um módulo ESM modela inscrições e depende de um repositório injetado. Entrada inválida não pode alterar o estado; os testes devem demonstrar a regra e não apenas a existência de uma classe.","requiredLessons":[11,12,13,16,17,18],"skills":["Invariantes","Módulos","Validação e testes"],"questions":[{"prompt":"A função de inscrição captura qualquer exceção e retorna sucesso vazio. O teste só verifica que não houve throw. Qual teste e tratamento são mais úteis?","options":["Continuar retornando sucesso para simplificar a interface.","Testar apenas o nome da função.","Remover toda validação porque o código é ESM.","Verificar a recusa esperada e a ausência de alteração, traduzindo só falhas conhecidas e preservando causas inesperadas."],"answer":3,"explanation":"Um teste precisa distinguir sucesso real, recusa de domínio e defeito. Esconder exceção pode confirmar uma operação que não ocorreu.","reviewLessons":[16,17,18],"id":"q1"},{"prompt":"O domínio chama diretamente console e um armazenamento global. Como permitir o mesmo caso de uso em CLI e interface web com testes controlados?","options":["Receber dependências por contratos pequenos e retornar um resultado que cada adaptador apresenta no seu ambiente.","Copiar o método para cada tela e manter regras separadas.","Expor toda variável do módulo como global.","Guardar o elemento DOM dentro de cada entidade de domínio."],"answer":0,"explanation":"Composição separa a decisão do efeito externo e da apresentação. O módulo pode ser testado com um repositório controlado.","reviewLessons":[11,12,13,18],"id":"q2"},{"prompt":"A entrada JSON contém status \"concluida\" e quantidade -2; a sintaxe JSON é válida. Em que momento a entidade deve rejeitar esses valores?","options":["Depois de salvar e enviar resposta 200.","Na fronteira de validação e nas operações que preservam o invariante, antes de salvar ou confirmar a transição.","Nunca, porque JSON válido significa domínio válido.","Somente quando o usuário atualizar a página."],"answer":1,"explanation":"Formato válido não prova regra de negócio. Estados e quantidades precisam de validação explícita antes dos efeitos.","reviewLessons":[11,17,18],"id":"q3"}],"id":"combo-2"},{"title":"Formulário acessível e resposta HTTP segura","scenario":"Uma tela envia inscrições a uma API local. Ela deve bloquear submissões duplicadas durante a espera, explicar erros por texto e exibir nomes recebidos sem interpretá-los como HTML.","requiredLessons":[19,21,23,24,25,27],"skills":["Assincronia","Acessibilidade","HTTP e renderização segura"],"questions":[{"prompt":"fetch resolveu normalmente com status 409. A tela pode anunciar inscrição concluída só porque a Promise resolveu?","options":["Sim, fetch rejeita automaticamente qualquer status fora de 200.","Sim, uma Promise resolvida prova confirmação de negócio.","Não; deve verificar o status/contrato da resposta e apresentar o conflito de modo acessível.","Não, porque 409 nunca pode retornar JSON."],"answer":2,"explanation":"fetch pode resolver em erros HTTP. A interface precisa distinguir transporte, status e resultado do domínio e comunicar o estado além de cor.","reviewLessons":[19,24,25],"id":"q1"},{"prompt":"O servidor devolveu o nome \"<img src=x onerror=...>\". Qual atualização mostra esse nome como dado e mantém a mensagem compreensível?","options":["Montar innerHTML com o nome para preservar o formato recebido.","Executar eval no texto antes de inserir.","Esconder o erro apenas mudando o botão para vermelho.","Atribuir o nome por textContent e publicar a mensagem de resultado numa região de status adequada."],"answer":3,"explanation":"Texto não confiável não deve ser interpretado como marcação executável. A comunicação de estado também deve chegar a quem usa leitor de tela.","reviewLessons":[23,24,27],"id":"q2"},{"prompt":"O usuário sai da tela enquanto a requisição demora. Qual desenho evita uma atualização tardia em estado já descartado?","options":["Propagar cancelamento quando suportado e tratar o encerramento da tela, verificando se o resultado ainda pertence à interação ativa.","Deixar toda requisição atualizar qualquer tela para sempre.","Usar um timeout na aparência e supor que isso interrompeu o trabalho remoto.","Criar requisições ilimitadas para tentar obter uma resposta rápida."],"answer":0,"explanation":"Limite de espera não garante parada do servidor. A interface precisa coordenar ciclo de vida, cancelamento e validade do resultado recebido.","reviewLessons":[19,21,23,25],"id":"q3"}],"id":"combo-3"},{"title":"API com arquivos, pressão de fluxo e repetição","scenario":"O backend local processa um arquivo grande, publica um resultado HTTP e mantém operações idempotentes. O serviço deve observar limites, conservar resultados após reinício quando prometido e medir antes de otimizar.","requiredLessons":[28,29,31,32,34,35],"skills":["Streams","Fronteiras","Diagnóstico e idempotência"],"questions":[{"prompt":"O destino grava mais devagar do que a origem produz dados. Qual composição impede que o processo acumule todo o arquivo em memória?","options":["Transformar cada chunk em tarefa sem aguardar nem limitar.","Usar pipeline/streams com pressão do consumidor, tratar erros de todas as etapas e definir limites de recursos.","Ler tudo para uma variável global antes de iniciar a gravação.","Ignorar erros de escrita e contar bytes lidos como sucesso."],"answer":1,"explanation":"Backpressure conecta o ritmo das etapas. Leitura concluída não comprova gravação e retenção ilimitada pode esgotar memória.","reviewLessons":[28,29,34],"id":"q1"},{"prompt":"Um cálculo de CPU bloqueia a API. O que justifica mover essa etapa para worker threads?","options":["Qualquer uso de await prova paralelismo de CPU.","Workers tornam desnecessária a validação dos resultados.","Uma medição mostra custo de CPU relevante; o desenho controla mensagens, falhas e término do worker e compara o resultado correto.","Criar um worker por elemento sem limite sempre melhora desempenho."],"answer":2,"explanation":"O uso de workers deve responder a uma evidência de custo e incluir ciclo de vida e limite. Assincronia sozinha não torna cálculo pesado paralelo.","reviewLessons":[31,32,34],"id":"q2"},{"prompt":"A chave de confirmação só existe numa Map em memória. Depois de reiniciar, o mesmo pedido baixa estoque outra vez. Qual promessa estava incorreta?","options":["A de que Map pode guardar chaves.","A de que HTTP pode enviar JSON.","A de que arrays possuem tamanho.","A de deduplicação durável após reinício; operação e efeito precisam de persistência consistente para essa garantia."],"answer":3,"explanation":"Uma demonstração em memória tem limite de processo. Garantia de repetição atravessando reinício exige estado durável e um limite atômico adequado.","reviewLessons":[28,34,35],"id":"q3"}],"id":"combo-4"}],"finalProject":{"id":"final","title":"Portal local de inscrições em JavaScript","scenario":"Entregue uma interface web acessível e uma API local para gerenciar vagas de oficinas. Duas pessoas podem disputar a última vaga e uma requisição pode ser repetida depois de resultado incerto.","requirements":["Validar capacidade, identidade da inscrição e transições por um caso de uso compartilhado, sem misturar DOM e regra.","Implementar formulário com rótulos, foco, mensagens de status e recuperação de erro sem depender de cor ou mouse.","Aplicar método, rota, limite de corpo e validação, conferir respostas de fetch e renderizar dados com segurança.","Definir persistência e protocolo idempotente, distinguindo demonstração em memória de garantia após reinício.","Processar importação por etapas com backpressure e, se necessário, CPU em workers com encerramento controlado.","Fornecer testes node:test, cenários de interface, medições reproduzíveis e roteiro de execução/recuperação local."],"deliverables":["Fontes ESM da interface e API, com regras compartilhadas.","Testes e fixtures de validação, concorrência lógica e repetição.","README com ambiente, instalação, formatos e limites.","Roteiro de uso por teclado, falha de rede e recuperação do estado."],"rubric":[{"id":"r1","title":"Regras do domínio","description":"Validar capacidade, identidade da inscrição e transições por um caso de uso compartilhado, sem misturar DOM e regra.","reviewLessons":[4,11,12,17,34]},{"id":"r2","title":"Interface acessível","description":"Implementar formulário com rótulos, foco, mensagens de status e recuperação de erro sem depender de cor ou mouse.","reviewLessons":[22,23,24]},{"id":"r3","title":"API e dados externos","description":"Aplicar método, rota, limite de corpo e validação, conferir respostas de fetch e renderizar dados com segurança.","reviewLessons":[25,26,27]},{"id":"r4","title":"Estado e repetição","description":"Definir persistência e protocolo idempotente, distinguindo demonstração em memória de garantia após reinício.","reviewLessons":[28,34,35]},{"id":"r5","title":"Trabalho limitado","description":"Processar importação por etapas com backpressure e, se necessário, CPU em workers com encerramento controlado.","reviewLessons":[21,29,31,33]},{"id":"r6","title":"Validação da entrega","description":"Fornecer testes node:test, cenários de interface, medições reproduzíveis e roteiro de execução/recuperação local.","reviewLessons":[18,30,32,36]}],"acceptance":[{"title":"Inscrição válida","setup":"Oficina com capacidade 2 e nenhuma inscrição.","input":"Enviar nome válido e chave op-1 uma vez.","expected":"Uma inscrição, uma vaga restante e resultado apresentado por mensagem acessível.","reviewLessons":[17,23,24,26,35]},{"title":"Conteúdo não confiável","setup":"Oficina disponível e nome contendo texto parecido com uma tag HTML.","input":"Submeter e depois exibir o nome na lista.","expected":"O nome aparece como texto; nenhum HTML recebido é executado.","reviewLessons":[17,25,27]},{"title":"Última vaga e repetição","setup":"Uma vaga disponível; duas operações diferentes e uma repetição da vencedora.","input":"Tentar as duas inscrições e repetir a confirmação aceita.","expected":"A capacidade não fica negativa; só uma vence e a repetição não cria outra inscrição dentro da garantia documentada.","reviewLessons":[18,26,34,35]}],"questions":[{"prompt":"A tela mostrou sucesso após receber 500 com JSON válido. Qual fronteira precisa ser revisada?","options":["A interpretação conjunta de status e corpo no cliente, antes de atualizar o estado como confirmado.","A cor do ícone apenas.","A quantidade de arquivos no projeto.","O uso de const em qualquer variável."],"answer":0,"explanation":"Parsing e sucesso de negócio são verificações independentes.","reviewLessons":[23,25,26],"id":"q1"},{"prompt":"Os testes exercitam só a função pura, mas o formulário perde o foco depois de um erro. O projeto está completamente validado?","options":["Sim, teste unitário cobre qualquer navegador.","Não; a aceitação precisa verificar também o fluxo de interação e sua acessibilidade.","Sim, foco não participa do comportamento.","Não, porque funções puras não podem ser testadas."],"answer":1,"explanation":"As camadas possuem contratos próprios; a interface precisa de evidências de uso.","reviewLessons":[18,23,24,36],"id":"q2"},{"prompt":"O autor promete confirmação exatamente uma vez em qualquer queda usando apenas uma Map. O que deve mudar?","options":["Basta renomear a Map como banco.","Basta colocar await antes de set.","O contrato precisa declarar o limite da memória ou implementar persistência e coordenação compatíveis com a promessa.","Basta usar um nome de chave mais longo."],"answer":2,"explanation":"A garantia deve corresponder à durabilidade e à atomicidade reais.","reviewLessons":[28,34,35,36],"id":"q3"}]}},"kubernetes":{"courseId":"kubernetes","combos":[{"id":"combo-1","title":"Reconciliar e localizar o serviço","scenario":"Um Deployment roda duas réplicas no namespace treino. Um Service deve alcançá-las por labels e consumidores de outro namespace precisam usar o endereço correto.","requiredLessons":[2,3,4,5,7,8],"skills":["Reconciliação","Labels e endpoints","DNS por namespace"],"questions":[{"id":"q1","options":["Corrigir a correspondência de labels/selector no manifesto adequado e verificar os endpoints resultantes.","Entrar em cada Pod e alterar seu /etc/hosts manualmente.","Mudar somente o nome visível do namespace.","Aumentar réplicas sem corrigir o selector."],"answer":0,"prompt":"Os Pods estão Running, mas o Service não tem endpoints porque seu selector usa app=portal e os Pods possuem app=reservas. Qual reparo atende ao modelo declarativo?","explanation":"O Service seleciona Pods por labels. Running não garante associação ao Service; corrija a fonte declarativa e confira as relações observadas.","reviewLessons":[2,3,5,7]},{"id":"q2","options":["Usar localhost para alcançar qualquer namespace.","Usar um nome qualificado pelo namespace, como portal.treino.svc, e verificar o DNS e a porta do Service.","Trocar a label do cliente por uma senha.","Assumir que nomes curtos sempre procuram todos os namespaces."],"answer":1,"prompt":"Um cliente no namespace relatorios usa portal e encontra um serviço diferente do existente em treino. Qual endereço expressa o destino pretendido?","explanation":"A resolução de nomes curtos depende do namespace do cliente. DNS e Service descrevem descoberta, não um atalho para o processo local.","reviewLessons":[3,7,8]},{"id":"q3","options":["O cluster restaurou automaticamente um backup completo do banco.","Apagar o Pod deve remover para sempre o Deployment.","É a reconciliação mantendo o estado desejado; confira controlador, réplicas e labels, sem depender do nome efêmero do Pod.","O nome novo prova que o Service ganhou um endereço público."],"answer":2,"prompt":"Um Pod gerenciado pelo Deployment foi apagado e outro apareceu com nome diferente. Como interpretar e verificar isso?","explanation":"Pods são unidades substituíveis e o controlador mantém o número pretendido. Disponibilidade e dados persistentes precisam de verificações próprias.","reviewLessons":[2,4,5,7]}]},{"id":"combo-2","title":"Prontidão, configuração e dados","scenario":"Uma API lê configuração e credencial por mecanismos separados, usa PVC para seu estado e não deve receber tráfego enquanto inicializa. O cluster tem recursos limitados.","requiredLessons":[10,11,12,13,17,18],"skills":["Configuração e segredo","Probes","PVC e recursos"],"questions":[{"id":"q1","options":["Usar readiness como prova de que o PVC tem backup.","Publicar o Secret na imagem para iniciar mais rápido.","Eliminar todos os requests para que a liveness espere.","Usar startup probe para a fase inicial e readiness para indicar quando a API pode receber tráfego, com liveness adequada ao comportamento posterior."],"answer":3,"prompt":"A API demora quarenta segundos para iniciar, mas a liveness começa agressivamente e reinicia o Pod antes disso. Qual desenho preserva inicialização e controle de tráfego?","explanation":"Inicialização, prontidão e recuperação do processo são funções diferentes. Os parâmetros precisam corresponder ao tempo de boot observado e ao estado útil da aplicação.","reviewLessons":[10,12,13]},{"id":"q2","options":["Montar efetivamente o claim no caminho usado pela aplicação e testar dados conhecidos após a substituição.","Apenas dar ao Pod um nome de StatefulSet sem montar o volume.","Adicionar os arquivos ao Secret.","Afirmar que existir um PVC prova que qualquer arquivo será persistido."],"answer":0,"prompt":"Um Pod substituído perdeu arquivos porque a aplicação gravava em diretório efêmero, embora exista um PVC no namespace. Qual evidência e ajuste são necessários?","explanation":"A existência do claim não conecta automaticamente o caminho de escrita. Estado persistente depende de montagem, driver, política e do ciclo de vida efetivo.","reviewLessons":[17,18]},{"id":"q3","options":["Manter a senha no ConfigMap e mudar apenas seu nome para secreto.","Mover a credencial para mecanismo de segredo e limitar acesso; reconhecer que Secret não cifra automaticamente todo caminho nem elimina gestão de credenciais.","Usar base64 como prova de sigilo completo.","Montar o PVC no navegador para esconder a senha."],"answer":1,"prompt":"A senha foi guardada em ConfigMap e os manifests são compartilhados. Qual separação é apropriada sem atribuir proteção inexistente ao Secret?","explanation":"ConfigMap é configuração não secreta. Secret tem uso e permissões próprios, mas exposição de manifests, RBAC e proteção em repouso/transporte continuam relevantes.","reviewLessons":[10,11,17]}]},{"id":"combo-3","title":"Isolamento verificável e mudança declarativa","scenario":"A equipe limita privilégios de uma aplicação, define NetworkPolicy e promove mudanças por uma fonte declarativa. Uma conexão proibida ainda funciona no kind.","requiredLessons":[19,20,21,22,24,27],"skills":["RBAC","Segurança do Pod","Política de rede e drift"],"questions":[{"id":"q1","options":["A existência do YAML basta para declarar tráfego bloqueado.","RBAC sempre bloqueia automaticamente todo pacote de rede.","A política declarada não comprovou isolamento; configure um provedor que a implemente e execute testes permitidos e recusados.","Um Pod sem root torna qualquer conexão impossível."],"answer":2,"prompt":"A NetworkPolicy está criada, porém o CNI do laboratório não a aplica. O tráfego proibido continuou funcionando. Que conclusão é correta?","explanation":"NetworkPolicy depende de implementação no dataplane. Teste o comportamento real e mantenha a etapa como pendente se o laboratório não possui suporte.","reviewLessons":[19,20,21,24]},{"id":"q2","options":["Colocar o token de administrador dentro da imagem.","Substituir o Service por ClusterIP e concluir que privilégios acabaram.","Remover o usuário do sistema Linux e manter o token de administrador.","Uma identidade própria com Role/RoleBinding limitados e testes de autorização para ações permitidas e recusadas."],"answer":3,"prompt":"A aplicação só precisa ler um ConfigMap do seu namespace, mas usa uma ServiceAccount com poderes de administrador do cluster. Qual desenho deve ser demonstrado?","explanation":"Identidade Kubernetes e usuário do processo são camadas diferentes. Mínimo privilégio exige verificar permissões efetivas, não só o nome da conta.","reviewLessons":[19,20,24]},{"id":"q3","options":["Atualizar a fonte declarativa autorizada, revisar a promoção e verificar a convergência dos objetos.","Repetir edições manuais indefinidamente sem alterar a fonte.","Mudar somente o nome do Pod.","Tratar o retorno do estado como prova de falha do DNS sem investigar o manifesto."],"answer":0,"prompt":"Um operador corrigiu manualmente o Service, mas a reconciliação GitOps voltou ao selector incorreto. Qual ação corrige a causa duradoura?","explanation":"Um reconciliador tenta restabelecer a fonte desejada. A correção precisa estar nesse fluxo e ser comprovada nos seletores/endpoints observados.","reviewLessons":[22,24,27]}]},{"id":"combo-4","title":"Escalar, drenar e recuperar","scenario":"O portal recebe carga variável. A equipe prepara HPA, rollout e manutenção de nós, e precisa demonstrar uma recuperação sem confundir réplicas com backup.","requiredLessons":[28,29,30,31,33,36],"skills":["Métricas e HPA","Rollout e manutenção","Recuperação"],"questions":[{"id":"q1","options":["Aumentar maxReplicas e afirmar que qualquer falta de métrica será resolvida.","Confirmar coleta de métricas, requests coerentes e o comportamento do alvo sob uma carga definida.","Criar mais labels sem instalar o pipeline de métricas necessário.","Declarar que HPA substitui um teste de carga."],"answer":1,"prompt":"O HPA por CPU não apresenta uma utilização válida e a API não tem requests de CPU. Qual conjunto de evidências deve vir antes de prometer escala automática?","explanation":"HPA depende do sinal observado e do denominador quando a métrica usa utilização relativa. Configurar máximos não prova o ciclo de escala.","reviewLessons":[28,29,36]},{"id":"q2","options":["Remover todo PDB por padrão e chamar isso de manutenção sem impacto.","Apagar o volume de dados para liberar a drenagem.","Conferir réplicas saudáveis, disponibilidade mínima e capacidade de reassentamento antes de modificar o plano de manutenção.","Assumir que cordon move todos os Pods imediatamente."],"answer":2,"prompt":"Um drain é bloqueado pelo orçamento de interrupção. Qual resposta preserva a intenção do PDB e permite investigar manutenção?","explanation":"Cordon impede novos agendamentos e drain evacua conforme regras aplicáveis. PDB e capacidade precisam ser considerados junto da disponibilidade real.","reviewLessons":[30,31,36]},{"id":"q3","options":["Sim, três réplicas guardam qualquer versão histórica para sempre.","Sim, rollout undo sempre restaura todos os dados.","Não, porque métricas são proibidas em recuperação.","Não; deve restaurar o estado necessário em destino isolado e validar dados e comportamento, com escopo e tempo registrados."],"answer":3,"prompt":"Há três réplicas da API, mas nenhuma restauração do estado foi aberta. A equipe pode declarar recuperação de desastre comprovada?","explanation":"Réplicas e rollout não substituem cópias recuperáveis. Um ensaio precisa conferir o estado restaurado e explicitar se abrange aplicação, volumes ou controle do cluster.","reviewLessons":[28,30,33,36]}]}],"finalProject":{"id":"final","title":"Portal de reservas em cluster local com operação demonstrada","scenario":"Entregue um portal HTTP de reservas no kind, com manifests versionados, dados fictícios e procedimentos de operação. Separe o que foi realmente ensaiado no laboratório do que apenas foi projetado para outro ambiente.","requirements":["Declarar namespace, Deployment e Service com selectors coerentes e referência de imagem identificável.","Separar ConfigMaps e Secrets, usar ServiceAccount própria e permissões compatíveis com a função da aplicação.","Configurar probes, requests/limits e demonstrar agendamento e prontidão sob uma carga conhecida.","Persistir o estado necessário usando armazenamento compatível com o laboratório e documentar suas limitações.","Produzir uma mudança de versão, observar rollout e demonstrar reversão compatível, além de planejar manutenção com PDB quando aplicável.","Restaurar cópia do estado num destino de teste e validar dados e serviço; comprovar NetworkPolicy somente se o CNI a aplicar."],"deliverables":["Manifests base e overlays/values escolhidos, sem credenciais reais, com versões e pré-requisitos do kind.","README com comandos de criação, acesso, diagnóstico, atualização e limpeza do laboratório.","Relatório de testes de serviço, probes, recursos, permissões e rede com saídas reais.","Runbook de mudança, manutenção e restauração com escopo, resultados, tempo e limitações."],"rubric":[{"id":"r1","title":"Objetos reconciliáveis","description":"Labels, selectors, namespace e controladores correspondem ao desenho e à fonte versionada.","reviewLessons":[2,3,4,5,7,25,27]},{"id":"r2","title":"Configuração e acesso","description":"Identidades e dados de configuração estão separados; ações recusadas são verificadas.","reviewLessons":[10,11,19,20]},{"id":"r3","title":"Prontidão e capacidade","description":"Probes e recursos foram conferidos no comportamento observado, sem prometer escala não testada.","reviewLessons":[12,13,14,15,28,29]},{"id":"r4","title":"Estado persistente","description":"A montagem e o ciclo de vida dos dados foram testados; PVC não é tratado como backup.","reviewLessons":[16,17,18]},{"id":"r5","title":"Diagnóstico e isolamento","description":"Falhas de serviço e políticas foram investigadas com evidência e pré-requisitos reais.","reviewLessons":[21,22,23,24]},{"id":"r6","title":"Mudança e recuperação","description":"Rollout/reversão e destino restaurado têm evidências distintas, com limites de manutenção e compatibilidade.","reviewLessons":[30,31,32,33,36]}],"acceptance":[{"title":"Descoberta e prontidão","setup":"Crie o cluster e o namespace com a aplicação e seu Service.","input":"Consulte endpoints e faça requisições durante a inicialização e após readiness.","expected":"O Service aponta para os Pods esperados; tráfego útil só é encaminhado conforme prontidão e a consulta retorna um marcador conhecido.","reviewLessons":[5,7,8,12]},{"title":"Privilégio e rede","setup":"Use uma ServiceAccount restrita e um CNI capaz de aplicar NetworkPolicy, se esse ensaio fizer parte da entrega.","input":"Execute uma ação autorizada e outra negada; teste conexão permitida e proibida.","expected":"Resultados correspondem às regras; se o CNI não aplicar políticas, registre a etapa de rede como não comprovada em vez de aprovada.","reviewLessons":[19,20,21,24]},{"title":"Reabrir estado e versão","setup":"Crie reservas fictícias e preserve a cópia de recuperação antes da mudança.","input":"Substitua Pod, faça uma mudança/reversão controlada e restaure os dados num destino separado.","expected":"Persistência após substituição e recuperação independente são verificadas separadamente; as reservas e a versão esperada funcionam no destino.","reviewLessons":[17,18,30,33,36]}],"questions":[{"id":"q1","options":["Isolamento de rede efetivo, que exige suporte do dataplane e teste do comportamento.","A existência do namespace está automaticamente refutada.","Todo o backup está necessariamente corrompido.","Nada falta, pois YAML é prova de execução."],"answer":0,"prompt":"O projeto apresenta YAML de NetworkPolicy e Pods saudáveis, mas não informa CNI nem conexão negada. Que critério permanece sem evidência?","explanation":"O relatório precisa distinguir intenção declarativa de efeito aplicado. Complete o ensaio ou marque explicitamente essa limitação.","reviewLessons":[2,21,24]},{"id":"q2","options":["Somente o nome visual do Deployment.","Compatibilidade de aplicação e dados, com plano de mudança e recuperação que trate os dois estados.","Aumentar HPA como substituto de compatibilidade.","Assumir que rollback restaura volumes automaticamente."],"answer":1,"prompt":"Depois de rollout undo, a API antiga falha ao ler dados migrados pela versão nova. Qual ponto consolidado deve ser revisto?","explanation":"Reversão de Pod e recuperação de dados são caminhos diferentes. Planeje janelas compatíveis e demonstre qual estado cada etapa recupera.","reviewLessons":[18,30,32,33]},{"id":"q3","options":["Há agora disponibilidade geográfica comprovada.","Toda manutenção de nós futuros será sem impacto.","O procedimento local e os dados foram verificados; tolerância à perda da máquina inteira ainda exige outro desenho e ensaio.","O local dos arquivos deixa de importar."],"answer":2,"prompt":"A restauração de reservas passou numa segunda instância no mesmo notebook. Qual conclusão corresponde ao escopo do ensaio?","explanation":"Um teste local é útil, mas não cria independência de infraestrutura. Relate precisamente destino, falha simulada e tempo observado.","reviewLessons":[17,18,31,33,36]}]}},"logica":{"courseId":"logica","combos":[{"title":"Orçamento com unidades e regras de decisão","scenario":"Um orçamento recebe quantidade textual e preço em centavos. Há faixas de desconto e uma condição de bloqueio; o algoritmo deve classificar fronteiras sem confundir formato, unidade e significado.","requiredLessons":[3,4,5,6,8,9],"skills":["Contrato","Conversão e unidades","Decisões compostas"],"questions":[{"prompt":"A quantidade chega como \"3\" e o preço é 1250 centavos. Qual sequência corresponde ao contrato de um total numérico?","options":["Converter e validar a quantidade, calcular 3×1250 e apresentar 3750 centavos ou uma conversão monetária explicitada.","Concatenar \"3\" e \"1250\" e chamar o texto de total.","Dividir o preço por 100 antes de definir como tratar frações e unidades.","Aceitar qualquer texto porque possui pelo menos um caractere."],"answer":0,"explanation":"Formato textual não é quantidade validada. O cálculo precisa conservar uma unidade conhecida e tratar a conversão antes de operar.","reviewLessons":[4,5,6],"id":"q1"},{"prompt":"A regra dá desconto especial a quantidade>=10, mas o primeiro ramo testa quantidade>=5 e encerra a decisão. O que acontece com quantidade 10 e como corrigir?","options":["Ela executa automaticamente todos os ramos e soma os descontos.","Ela entra na faixa mais ampla primeiro; ordenar pela condição específica ou tornar as faixas disjuntas preserva o desconto especial.","A ordem dos ramos nunca altera a classificação.","É preciso remover todos os testes de fronteira."],"answer":1,"explanation":"Uma decisão que escolhe o primeiro ramo verdadeiro precisa de prioridade coerente. O valor de fronteira 10 distingue a regra correta da incorreta.","reviewLessons":[6,8,9],"id":"q2"},{"prompt":"O requisito é: cliente ativo E (pedido pago OU crédito aprovado). Qual decomposição deixa o bloqueio claro?","options":["Usar (ativo E pago) OU crédito aprovado, permitindo inativo com crédito.","Validar somente pago e ignorar os outros dados.","Verificar ativo e agrupar pago OU crédito aprovado como a segunda condição composta.","Trocar E por OU em todas as relações para aceitar mais pedidos."],"answer":2,"explanation":"O agrupamento define o alcance da exigência de ativo. Uma tabela de decisão deve incluir o cliente inativo com crédito para detectar o erro.","reviewLessons":[3,8,9],"id":"q3"}],"id":"combo-1"},{"title":"Resumo de movimentos com término e funções","scenario":"Um algoritmo percorre movimentos, calcula quantidade e total e oferece uma função de consulta. Dados vazios e todos negativos precisam de saídas definidas; a consulta não deve mudar a lista.","requiredLessons":[10,11,12,15,16,18],"skills":["Repetição","Ausência","Funções e efeitos"],"questions":[{"prompt":"Um while repete enquanto pendentes>0, mas um ramo de erro não reduz pendentes nem sai. Que propriedade precisa ser garantida?","options":["O laço terminará porque o computador executa rápido.","Basta aumentar o valor inicial de pendentes.","Transformar o contador em texto garante a parada.","Em todo caminho repetido deve haver progresso para o término ou uma saída definida, mantendo contagem e estado coerentes."],"answer":3,"explanation":"A condição inicial não prova término. Uma medida de progresso deve aproximar o algoritmo da saída em cada caminho relevante.","reviewLessons":[10,11,12],"id":"q1"},{"prompt":"O algoritmo procura o maior valor inicializando maior=0. Para [-8,-3,-10] ele retorna 0. Qual contrato corrige esse caso e o vazio?","options":["Inicializar a partir de um elemento válido quando existir e representar explicitamente ausência para a coleção vazia.","Manter 0 porque todo máximo é não negativo.","Escolher sempre a última posição sem comparar.","Usar um número negativo fixo sem conhecer os limites do domínio."],"answer":0,"explanation":"A inicialização precisa pertencer ao domínio observado ou usar um estado de ausência explícito. Um valor legítimo não deve servir de sentinela ambígua.","reviewLessons":[12,15,16],"id":"q2"},{"prompt":"A função resumo recebe a lista de movimentos e remove valores negativos durante a consulta. O chamador descobre a lista menor. Qual mudança torna o efeito claro?","options":["Supor que mudar o nome do parâmetro faz cópia automática.","Produzir um resultado separado sem alterar a entrada, ou declarar explicitamente uma operação de transformação que modifica a coleção.","Guardar a lista numa variável global para evitar a surpresa.","Ignorar a mudança porque funções nunca têm efeitos."],"answer":1,"explanation":"Contrato de função inclui efeitos sobre dados compartilhados. Separar consulta de transformação facilita prever e testar o comportamento.","reviewLessons":[15,16,18],"id":"q3"}],"id":"combo-2"},{"title":"Cadastro, validação e escolha de busca","scenario":"Um cadastro possui identificadores estáveis, saldos e um relatório de frequência por código. Consultas podem usar busca binária apenas quando a pré-condição de ordenação é verdadeira.","requiredLessons":[19,20,21,23,26,27],"skills":["Identidade","Validação antes do efeito","Agrupamento e pré-condições"],"questions":[{"prompt":"O registro ID 42 está na posição 0 da lista. A busca retorna 0 e o chamador interpreta como não encontrado. Qual contrato evita essa ambiguidade?","options":["Renumerar todo ID conforme a posição toda vez que consultar.","Considerar que posição 0 nunca contém dados.","Distinguir identificador de posição e representar ausência explicitamente, sem usar uma posição válida como sentinela indistinguível.","Alterar o registro encontrado para provar que existe."],"answer":2,"explanation":"Posição e identidade têm significados diferentes. O protocolo de retorno deve conservar a primeira posição válida e distinguir a falta de resultado.","reviewLessons":[19,20],"id":"q1"},{"prompt":"Uma confirmação já reduz o saldo antes de descobrir quantidade negativa ou estado não permitido. Como conservar o estado em uma recusa?","options":["Alterar e imprimir erro depois, sem restaurar nada.","Remover a validação de negativos para evitar a falha.","Conferir somente se o texto do ID é longo.","Validar tipo, faixa, identidade e regra da operação antes da alteração, e tratar o conjunto de mudanças como uma decisão coerente."],"answer":3,"explanation":"Recusar é um comportamento que deve preservar o estado previsto. Validação tardia pode deixar efeito parcial mesmo quando o algoritmo informa erro.","reviewLessons":[19,20,21],"id":"q2"},{"prompt":"O relatório agrupa ocorrências por código, mas guarda os pares na ordem de chegada. Pode aplicar busca binária por código só porque o agrupamento já terminou?","options":["Não; a coleção precisa estar ordenada pela mesma chave/comparação da busca, ou deve ser escolhida outra estrutura de consulta adequada.","Sim, agrupar automaticamente ordena qualquer representação.","Sim, busca binária funciona em qualquer ordem com o mesmo resultado.","Não, porque códigos nunca podem ser comparados."],"answer":0,"explanation":"Agrupamento e ordenação são propriedades diferentes. A redução de candidatos da busca binária só é válida quando sua pré-condição corresponde à coleção.","reviewLessons":[19,23,26,27],"id":"q3"}],"id":"combo-3"},{"title":"Estados, hierarquia e confirmação repetível","scenario":"Uma ordem contém grupos e subgrupos de itens. O algoritmo soma a hierarquia, valida transições e confirma a baixa uma única vez por operação. Contraexemplos e testes de fronteira devem sustentar a explicação.","requiredLessons":[28,29,30,31,34,35],"skills":["Recursão","Invariantes","Estados e idempotência"],"questions":[{"prompt":"Uma função soma subgrupos recursivamente, mas chama a si mesma sempre com o mesmo nó. Qual combinação de critérios demonstra término e resultado?","options":["Apenas usar uma função com o nome recursiva.","Caso-base para folhas/vazio e redução para subproblemas menores, com regra de soma que inclua cada item uma vez e tratamento de ciclos se o domínio os permitir.","Esperar que a execução pare quando o total ficar grande.","Ignorar filhos para evitar chamadas, mesmo quando o requisito inclui a hierarquia."],"answer":1,"explanation":"Recursão exige um caso simples e uma redução real. A estrutura pode ser árvore ou grafo; isso muda o cuidado necessário com revisitas.","reviewLessons":[28,29,30],"id":"q1"},{"prompt":"A transição permite confirmar somente ordem ABERTA e quantidade até o saldo. Que conjunto pequeno distingue regras de estado e fronteira?","options":["Testar apenas uma ordem ABERTA com saldo muito alto.","Usar somente nomes diferentes com a mesma quantidade válida.","Testar ABERTA com quantidade abaixo, igual e acima do saldo, além de tentar confirmar uma ordem já CONFIRMADA.","Testar só a velocidade do algoritmo em lista vazia."],"answer":2,"explanation":"Partições e fronteiras exercitam decisões diferentes. A tentativa no estado final verifica que a transição não está liberada indiscriminadamente.","reviewLessons":[30,31,34],"id":"q2"},{"prompt":"A mesma operação de confirmação chega novamente depois da primeira baixa. Qual regra expressa idempotência no modelo?","options":["Criar uma identidade nova para cada repetição automática.","Subtrair novamente e apenas esconder a segunda mensagem.","Marcar qualquer pedido como novo quando estiver CONFIRMADO.","Reconhecer a identidade e o conteúdo da operação já aplicada e devolver seu resultado sem realizar a baixa outra vez."],"answer":3,"explanation":"Repetir uma solicitação não deve repetir um efeito já aplicado. Identidade da operação, estado e conteúdo precisam participar da decisão.","reviewLessons":[30,34,35],"id":"q3"}],"id":"combo-4"}],"finalProject":{"id":"final","title":"Algoritmo verificável de ordens e estoque","scenario":"Especifique e implemente uma solução pequena para cadastrar itens, abrir ordens e confirmar baixas. Use pseudocódigo preciso e o Python simples da trilha para demonstrar os casos, sem exigir serviços externos.","requirements":["Definir campos, unidades, tipos aceitos, faixas e resultados de sucesso/recusa antes de implementar.","Representar itens e ordens por identificadores estáveis e estados com transições permitidas explícitas.","Validar todas as condições antes do efeito e preservar o estado quando a ordem não puder ser confirmada.","Reconhecer uma confirmação já aplicada e impedir segunda baixa para a mesma operação, incluindo conflito de conteúdo.","Justificar as estruturas e buscas usadas, seus limites, término e invariantes, sem prometer tempos exatos só pela complexidade.","Entregar testes de fronteira, vazio, ausência, repetição e estado inválido, guardando contraexemplos como regressões."],"deliverables":["Especificação de dados, operações e tabela de transições.","Pseudocódigo e implementação simples com funções de contrato definido.","Tabela de testes com entrada, resultado previsto, observado e justificativa.","Relatório de invariantes, término, escolhas e contraexemplos corrigidos."],"rubric":[{"id":"r1","title":"Contrato de entrada","description":"Definir campos, unidades, tipos aceitos, faixas e resultados de sucesso/recusa antes de implementar.","reviewLessons":[1,3,4,5,20]},{"id":"r2","title":"Identidade e estado","description":"Representar itens e ordens por identificadores estáveis e estados com transições permitidas explícitas.","reviewLessons":[19,22,34]},{"id":"r3","title":"Alteração coerente","description":"Validar todas as condições antes do efeito e preservar o estado quando a ordem não puder ser confirmada.","reviewLessons":[20,21,30,34]},{"id":"r4","title":"Repetição controlada","description":"Reconhecer uma confirmação já aplicada e impedir segunda baixa para a mesma operação, incluindo conflito de conteúdo.","reviewLessons":[21,30,35]},{"id":"r5","title":"Algoritmos explicáveis","description":"Justificar as estruturas e buscas usadas, seus limites, término e invariantes, sem prometer tempos exatos só pela complexidade.","reviewLessons":[16,17,23,26,27,28,30]},{"id":"r6","title":"Evidências de correção","description":"Entregar testes de fronteira, vazio, ausência, repetição e estado inválido, guardando contraexemplos como regressões.","reviewLessons":[15,31,32,33,36]}],"acceptance":[{"title":"Confirmação e repetição","setup":"Item A possui 5 unidades; ordem O está ABERTA e operação op-1 é inédita.","input":"Confirmar 2 unidades; repetir op-1 com os mesmos dados.","expected":"Saldo 3, ordem CONFIRMADA e somente uma baixa; a repetição devolve o resultado anterior.","reviewLessons":[19,21,34,35]},{"title":"Recusa preserva estado","setup":"Saldo 5, ordem ABERTA e nenhum efeito aplicado.","input":"Tentar quantidade -1, 0 e 6 em cenários separados.","expected":"Cada tentativa é recusada por sua regra; saldo 5 e ordem ABERTA permanecem.","reviewLessons":[20,21,31,32]},{"title":"Identidade e ausência","setup":"Lista começa na posição 0 com item ID 42 e também contém outros IDs.","input":"Consultar ID 42 e depois um ID inexistente.","expected":"Primeiro item é encontrado corretamente; ausência é retorno explícito e nenhuma consulta altera o cadastro.","reviewLessons":[19,22,30,33]}],"questions":[{"prompt":"Os exemplos escolhidos passam, mas não há justificativa de término do while. Que revisão ainda é necessária?","options":["Definir uma medida de progresso ou saída em todo caminho relevante e testar um contraexemplo que antes não avançava.","Aumentar a velocidade do computador.","Renomear o laço para finito.","Remover o caso de erro do enunciado."],"answer":0,"explanation":"Testes finitos ajudam a encontrar falhas, mas o raciocínio de término precisa explicar a repetição.","reviewLessons":[11,30,31],"id":"q1"},{"prompt":"O algoritmo imprime \"recusado\", mas já diminuiu o saldo. Esse caso atende ao contrato de recusa sem efeito?","options":["Sim, a mensagem determina sozinha o estado.","Não; a verificação precisa ocorrer antes da alteração ou a unidade deve ser desfeita de modo definido e testado.","Sim, qualquer recusa pode debitar uma unidade.","Não, porque mensagens de erro são proibidas."],"answer":1,"explanation":"O estado observado é parte do resultado do algoritmo, além da saída textual.","reviewLessons":[20,21,32],"id":"q2"},{"prompt":"Uma função passa a chamar busca binária, mas a entrada pode chegar em qualquer ordem. Qual evidência precisa mudar?","options":["Apenas o nome da função no relatório.","O tempo previsto deve ser declarado zero.","A pré-condição de ordenação deve ser satisfeita e testada, ou a escolha de busca precisa ser revista.","Toda consulta deve apagar o cadastro antes."],"answer":2,"explanation":"A correção do algoritmo depende das hipóteses sob as quais ele foi escolhido.","reviewLessons":[26,27,30,33],"id":"q3"}]}},"mariadb":{"courseId":"mariadb","combos":[{"id":"combo-1","title":"Estoque com retorno de escrita","scenario":"Um cadastro em MariaDB 11.4 LTS recebe produtos, quantidades e categorias. A API precisa de valores exatos, domínio válido e retorno ligado à linha inserida.","requiredLessons":[2,3,4,5,6,7],"skills":["Tipos e domínio","NULL e referências","INSERT RETURNING"],"questions":[{"id":"q1","prompt":"O preço usa DECIMAL, mas o contrato também exige presença e valor não negativo. Qual desenho aplica as três intenções?","options":["DECIMAL com NOT NULL e CHECK apropriado ao preço.","Apenas DECIMAL, porque ele conhece a regra de negócio.","FLOAT sem constraint e correção somente no relatório.","Nomear a coluna como preco_valido sem restrições."],"answer":0,"explanation":"Representação exata, obrigatoriedade e intervalo são responsabilidades diferentes. O tipo sozinho não torna todo valor aceitável.","reviewLessons":[2,6]},{"id":"q2","prompt":"Categoria ausente significa item ainda não classificado; categoria informada precisa existir. Como distinguir as duas situações?","options":["Usar 0 como categoria inexistente e remover a FK.","Permitir NULL se a regra aceitar ausência e usar FK para os valores efetivamente informados, consultando ausência com IS NULL.","Guardar a string NULL e presumir que ela satisfaz qualquer referência.","Usar =NULL para localizar a ausência e aceitar qualquer ID."],"answer":1,"explanation":"Ausência é uma decisão de nulabilidade; referência válida é uma regra relacional. O predicado de consulta deve respeitar a lógica de NULL.","reviewLessons":[3,5]},{"id":"q3","prompt":"O INSERT precisa devolver a identidade da linha recém-criada sem buscar MAX(id) compartilhado. Qual recurso do dialeto serve ao contrato?","options":["SELECT MAX(id) antes de inserir, mesmo sob concorrência.","Remover a chave para permitir qualquer retorno.","INSERT ... RETURNING com uma chave primária que identifique a linha.","Copiar a sintaxe de qualquer versão MySQL supondo compatibilidade total."],"answer":2,"explanation":"O retorno deve estar associado à escrita e à identidade do registro. MariaDB e MySQL não são dialetos intercambiáveis em todos os recursos.","reviewLessons":[4,7]}]},{"id":"combo-2","title":"Relatório e programação no banco","scenario":"Uma rotina registra itens e uma trigger gera histórico por linha. O relatório precisa contar clientes sem pedidos e classificar seus totais sem multiplicar medidas.","requiredLessons":[10,11,12,13,17,18],"skills":["Cardinalidade e agregação","CTE e janela","Rotina e trigger"],"questions":[{"id":"q1","prompt":"Um LEFT JOIN produz uma linha para cliente sem pedidos e COUNT(*) mostra 1. Como calcular número de pedidos e receita sem excluir esse cliente?","options":["Trocar por INNER JOIN e declarar que os ausentes foram preservados.","Somar o ID do cliente e chamar o resultado de receita.","Aplicar DISTINCT ao nome sem examinar as linhas da relação.","Contar a chave do pedido, definir a granularidade da soma e tratar ausência na medida de apresentação."],"answer":3,"explanation":"A linha externa preservada não é um pedido real. Contagem e receita precisam corresponder ao fato que cada medida descreve.","reviewLessons":[10,11]},{"id":"q2","prompt":"Uma CTE calcula total por cliente e a consulta externa usa RANK sobre esses totais. Por que agrupar antes pode ser necessário?","options":["Para que a janela classifique clientes e não cada linha de item, mantendo a granularidade pretendida.","Porque toda CTE materializa uma tabela permanente.","Porque RANK elimina automaticamente qualquer multiplicação de JOIN.","Porque agrupar sempre torna a consulta mais rápida em qualquer volume."],"answer":0,"explanation":"A CTE organiza a etapa de agregação; a janela opera sobre as linhas resultantes. O desenho depende da unidade que deve receber a classificação.","reviewLessons":[12,13]},{"id":"q3","prompt":"Uma procedure executa um INSERT com três linhas e há trigger AFTER INSERT FOR EACH ROW. Quantas execuções de trigger são esperadas, e o que conferir?","options":["Uma execução porque a procedure foi chamada uma vez.","Três execuções, conferindo as linhas de histórico e o contrato de cada inserção.","Zero, pois procedures desativam triggers.","Três commits independentes obrigatórios, um por trigger."],"answer":1,"explanation":"O evento por linha não muda por estar dentro de uma procedure. Chamada de rotina e quantidade de linhas afetadas possuem granularidades diferentes.","reviewLessons":[17,18]}]},{"id":"combo-3","title":"Documentos, histórico e acesso medido","scenario":"O sistema recebe JSON, transforma arrays em linhas e guarda histórico temporal de preços. Outra rotina atualiza estoque sob disputa; a equipe investiga consultas.","requiredLessons":[19,20,21,22,24,27],"skills":["JSON e relações","Histórico versus coordenação","Índices e medição"],"questions":[{"id":"q1","prompt":"JSON_TABLE expande três itens de um documento em três linhas. Qual cuidado evita somar três vezes um total que pertence ao documento inteiro?","options":["Somar o total do documento em cada linha e corrigir com arredondamento.","Afirmar que JSON_TABLE nunca aumenta a quantidade de linhas.","Separar medida do documento e medida do item, agregando na granularidade correta após a expansão.","Converter todo JSON em número sem especificar caminho."],"answer":2,"explanation":"A representação JSON e sua projeção relacional não removem o problema de cardinalidade. O total do pai se repete quando os filhos são expandidos.","reviewLessons":[19,20]},{"id":"q2","prompt":"A tabela de preço possui versionamento de sistema. Isso impede por si só que duas reservas concorrentes reduzam o mesmo estoque com decisão obsoleta?","options":["Sim, guardar histórico serializa automaticamente qualquer operação do banco.","Sim, FOR SYSTEM_TIME ALL reserva a última unidade.","Não, porque tabelas versionadas não armazenam linhas atuais.","Não; histórico registra versões, enquanto a reserva exige escrita/locks e tratamento de conflito apropriados."],"answer":3,"explanation":"Rastreabilidade temporal não substitui o protocolo que protege a invariante concorrente. São propriedades complementares.","reviewLessons":[21,27]},{"id":"q3","prompt":"Um índice foi criado sobre coluna gerada usada no filtro. ANALYZE FORMAT=JSON apresentou medições. Qual conclusão é justificável?","options":["Avaliar o acesso e o trabalho medido com dados/resultados comparáveis, lembrando que ANALYZE executa a consulta.","Afirmar tempo universal a partir de uma amostra pequena.","Tratar o nome do índice como prova de menor custo em qualquer escrita.","Supor que ANALYZE apenas formata texto e nunca executa o trabalho."],"answer":0,"explanation":"Coluna/índice precisam corresponder à consulta e as medições ao ambiente. A leitura do plano não substitui validar resultado e carga.","reviewLessons":[22,24]}]},{"id":"combo-4","title":"Evolução, acesso limitado e cópias","scenario":"A equipe altera o esquema e prepara uma cópia lógica com posição de replicação. O cliente possui uma conta limitada e valores fornecidos por usuários.","requiredLessons":[25,28,29,31,33,35],"skills":["DDL e migração","Roles e binding","Dump e GTID"],"questions":[{"id":"q1","prompt":"Uma migration executa ALTER TABLE comum em InnoDB e pretende usar ROLLBACK para desfazer qualquer etapa. O que o plano precisa corrigir?","options":["Supor que START TRANSACTION torna todo DDL reversível como DML.","Reconhecer limites de commit implícito do DDL e projetar etapas compatíveis e recuperação própria da migration.","Usar COMMIT depois do erro e chamar isso de rollback.","Copiar o comportamento transacional de outro SGBD sem conferir."],"answer":1,"explanation":"DDL e DML não compartilham automaticamente o mesmo limite de desfazer. A migration precisa conhecer o contrato MariaDB do comando usado.","reviewLessons":[25,35]},{"id":"q2","prompt":"A conta tem SELECT apenas na tabela de relatório, mas o cliente concatena o filtro recebido. Qual melhoria ainda é necessária?","options":["Aumentar privilégios para resolver qualquer erro.","Usar placeholders para substituir livremente nomes de tabela.","Vincular valores com PREPARE/API apropriada e manter testes de operações permitidas e recusadas.","Afirmar que uma role limitada torna toda concatenação correta."],"answer":2,"explanation":"Menor privilégio limita o alcance, mas não valida a estrutura do SQL. Marcadores representam valores e não toda a sintaxe.","reviewLessons":[28,29]},{"id":"q3","prompt":"O dump lógico foi criado e existe uma posição GTID MariaDB. Isso prova que há réplica funcional e recuperação histórica testada?","options":["Sim, imprimir GTID realiza o restore.","Sim, qualquer GTID MySQL pode ser usado como equivalente sem adaptação.","Não, porque dumps nunca podem ser restaurados.","Não; restore e replicação precisam de seus próprios ensaios, preservando os artefatos e posições corretos para MariaDB."],"answer":3,"explanation":"Posição e arquivo são insumos de procedimentos distintos. GTID MariaDB não é identidade intercambiável com o protocolo MySQL.","reviewLessons":[31,33]}]}],"finalProject":{"id":"final","title":"Pedidos e histórico operável em MariaDB","scenario":"Construa um banco MariaDB 11.4 LTS para uma loja fictícia com pedidos, itens, estoque e evolução de preços. O projeto deve usar recursos do dialeto conscientemente e registrar os limites de cada ensaio.","requirements":["Modelo válido: chaves, FKs, nulabilidade, valores exatos e regras de quantidade/status rejeitam estados inválidos.","Escrita rastreável: retorno de inserção, rotinas e triggers têm contrato definido; UPDATE sem mudança não gera histórico indevido quando a regra exigir.","Consulta coerente: relatórios não multiplicam fatos; JSON/JSON_TABLE e versões temporais têm semântica de leitura documentada.","Concorrência protegida: estoque e pedido pertencem à mesma unidade; locks, timeout e deadlock possuem tratamento e retry limitado.","Acesso e evolução: conta restrita, parâmetros ligados, migration compatível e diferenças MariaDB/MySQL identificadas.","Recuperação e disponibilidade: dump restaurado, procedimento físico distinguido de prepare e desenho GTID/Galera com ensaios executados ou pendentes explicitados."],"deliverables":["DDL, migrations, fixtures e matriz das diferenças de dialeto relevantes.","Rotinas e cliente parametrizado com contrato de erros e efeitos.","Testes de relatórios, concorrência e histórico com saídas esperadas.","Runbook de dump/restore e disponibilidade, com provas e pendências por cenário."],"rubric":[{"id":"r1","title":"Modelo válido","description":"Modelo válido: chaves, FKs, nulabilidade, valores exatos e regras de quantidade/status rejeitam estados inválidos.","reviewLessons":[2,4,5,6]},{"id":"r2","title":"Escrita rastreável","description":"Escrita rastreável: retorno de inserção, rotinas e triggers têm contrato definido; UPDATE sem mudança não gera histórico indevido quando a regra exigir.","reviewLessons":[7,17,18]},{"id":"r3","title":"Consulta coerente","description":"Consulta coerente: relatórios não multiplicam fatos; JSON/JSON_TABLE e versões temporais têm semântica de leitura documentada.","reviewLessons":[10,11,19,20,21]},{"id":"r4","title":"Concorrência protegida","description":"Concorrência protegida: estoque e pedido pertencem à mesma unidade; locks, timeout e deadlock possuem tratamento e retry limitado.","reviewLessons":[25,26,27]},{"id":"r5","title":"Acesso e evolução","description":"Acesso e evolução: conta restrita, parâmetros ligados, migration compatível e diferenças MariaDB/MySQL identificadas.","reviewLessons":[28,29,35]},{"id":"r6","title":"Recuperação e disponibilidade","description":"Recuperação e disponibilidade: dump restaurado, procedimento físico distinguido de prepare e desenho GTID/Galera com ensaios executados ou pendentes explicitados.","reviewLessons":[31,32,33,34,36]}],"acceptance":[{"title":"Regra e histórico","setup":"Produto existente e rotina de alteração com trigger preparado.","input":"Alterar um valor e executar também atualização que não muda o valor, conforme contrato documentado.","expected":"Dados atuais e auditoria correspondem às mudanças efetivas; o resultado não é inferido apenas da presença do trigger.","reviewLessons":[8,17,18]},{"title":"Último item disputado","setup":"Estoque 1 e duas sessões em tabelas persistentes do laboratório.","input":"Tentar confirmar dois pedidos que exigem a última unidade.","expected":"Somente um confirma; a recusa é tratada, não há saldo negativo nem pedido incompleto.","reviewLessons":[25,26,27]},{"title":"Dump e restauração","setup":"Fixture conhecida e banco de restore exclusivo previamente criado.","input":"Criar dump, importar no destino e conferir contagens, valores e regras.","expected":"Destino contém o ponto copiado e atende às verificações; backup físico/replicação não são declarados ensaiados por esse teste lógico.","reviewLessons":[31,32,33]}],"questions":[{"id":"q1","prompt":"O código usa uma função JSON de MySQL e falha em MariaDB. Qual correção atende ao projeto?","options":["Conferir a versão e o contrato MariaDB, adaptar a consulta e testar os mesmos dados/resultado esperado.","Trocar somente o nome do arquivo para mysql.sql.","Supor que ambos compartilham todas as funções e representação JSON.","Remover a validação e declarar equivalência."],"answer":0,"explanation":"Compatibilidade precisa ser verificada por recurso e versão. A representação JSON do MariaDB também merece consideração explícita.","reviewLessons":[19,20,35]},{"id":"q2","prompt":"mariadb-backup --backup e --prepare passaram. Isso basta para afirmar recuperação de uma nova instância?","options":["Sim, prepare já inicia e consulta o destino automaticamente.","Não; falta restaurar num alvo apropriado, iniciá-lo e conferir dados e regras.","Sim, diretório não vazio prova qualquer RTO.","Não, porque backup físico não existe no MariaDB."],"answer":1,"explanation":"Cópia preparada é um estágio do procedimento. Recuperabilidade exige um destino realmente aberto e validado.","reviewLessons":[31,32,36]},{"id":"q3","prompt":"O relatório é correto, mas a conta do cliente pode administrar roles e a rotina repete efeitos após deadlock. Quais pontos revisar?","options":["Somente o título do relatório.","Apenas a numeração dos IDs retornados.","Menor privilégio e protocolo de retry/idempotência da unidade, com testes de recusa e repetição.","Remover logs para não observar os erros."],"answer":2,"explanation":"Integridade de leitura não substitui acesso limitado nem estabilidade dos efeitos sob falha.","reviewLessons":[27,28,29]}]}},"markdown":{"courseId":"markdown","combos":[{"id":"combo-1","title":"Procedimento com exemplos literais","scenario":"Uma página ensina a executar um comando dentro de uma etapa numerada e precisa mostrar a sintaxe de um bloco cercado sem encerrar o próprio exemplo.","requiredLessons":[2,4,5,7,8,9],"skills":["Hierarquia","Listas e blocos","Cercas e quebras"],"questions":[{"id":"q1","options":["Ajustar linhas em branco e indentação do bloco segundo o conteúdo do item e conferir a lista no renderizador declarado.","Acrescentar espaços aleatórios só no título da página.","Trocar toda a lista por parágrafos separados por vírgulas.","Assumir que qualquer bloco após uma lista pertence automaticamente ao último item."],"answer":0,"prompt":"O comando deve pertencer ao passo 2 de uma lista, mas o bloco de código aparece fora dela. Qual revisão atende à estrutura pretendida?","explanation":"Listas combinam marcadores, indentação e limites de blocos. Verifique a estrutura renderizada, não apenas a aparência do texto no editor.","reviewLessons":[4,5,7]},{"id":"q2","options":["Usar a mesma cerca externa de três crases e esperar que as internas nunca sejam interpretadas.","Usar uma cerca externa de quatro crases e manter as três crases do exemplo dentro dela.","Remover uma crase do conteúdo sem avisar que o exemplo foi alterado.","Colocar somente um ponto e vírgula após a cerca interna."],"answer":1,"prompt":"Um trecho precisa exibir literalmente três crases que abrem e fecham um exemplo Markdown. Qual estratégia evita fechar a cerca externa cedo?","explanation":"A cerca externa deve superar a sequência interna que poderia fechá-la. Confira também o resultado após copiar o exemplo.","reviewLessons":[7,8,9]},{"id":"q3","options":["Porque uma quebra simples sempre cria um item numerado automaticamente.","Porque títulos substituem todos os passos de um procedimento.","Porque expressa etapas e ordem de maneira estrutural, sem depender de como quebras suaves são apresentadas.","Porque espaços finais são obrigatórios em toda linha de qualquer documento."],"answer":2,"prompt":"O autor separou três ações de um procedimento apenas por uma quebra simples de linha. Por que uma lista numerada pode representar melhor a intenção?","explanation":"Quebras de linha têm contratos próprios. Use estrutura de lista para uma sequência de ações e confira os blocos de cada passo.","reviewLessons":[2,4,9]}]},{"id":"combo-2","title":"Navegação, imagens e dialeto","scenario":"Um guia contém links internos, uma imagem que explica uma decisão e uma tabela de compatibilidade. Ele será lido no repositório e numa prévia local.","requiredLessons":[10,11,12,13,14,18],"skills":["Links descritivos","Texto alternativo","Dialeto declarado"],"questions":[{"id":"q1","options":["Apenas a cor do link, porque ela determina o caminho.","Trocar todos os rótulos por clique aqui e preservar o destino quebrado.","Assumir que caminho iniciado por / sempre significa a pasta do arquivo atual.","A base de resolução do destino e o uso de caminho relativo adequado ao contexto, mantendo rótulo que explique a ação."],"answer":3,"prompt":"O README usa /docs/instalar.md, mas o site é publicado sob um subcaminho e o link quebra. O que revisar junto do rótulo do link?","explanation":"Caminho de raiz e caminho relativo não são equivalentes. Repositório, site e exportação podem resolver destinos de maneiras distintas.","reviewLessons":[10,11,12]},{"id":"q2","options":["Descrever a informação relevante e fornecer explicação textual equivalente quando a relação for complexa.","Copiar apenas o tamanho do arquivo para o texto alternativo.","Remover toda descrição porque o nome do arquivo já é suficiente em qualquer caso.","Usar um emoji como substituto obrigatório de toda explicação."],"answer":0,"prompt":"Uma imagem mostra a relação entre três componentes e seu texto alternativo é somente imagem.png. Como tornar a informação recuperável?","explanation":"O leitor precisa do significado da imagem, não só do nome do recurso. Uma legenda ou descrição longa pode complementar o texto alternativo.","reviewLessons":[13,14]},{"id":"q3","options":["Afirmar que todo renderizador aceita qualquer extensão sem configuração.","Declarar GFM ou adaptar os recursos para a base prometida e conferir as duas prévias previstas.","Usar um link por referência para ativar GFM automaticamente.","Mudar a extensão do arquivo para .md e concluir que compatibilidade está provada."],"answer":1,"prompt":"O documento depende de autolink e texto riscado de GFM, mas a entrega promete CommonMark puro. Qual revisão é necessária?","explanation":"A extensão do arquivo não define sozinha o dialeto. O contrato precisa corresponder aos recursos utilizados e aos destinos realmente testados.","reviewLessons":[10,14,18]}]},{"id":"combo-3","title":"README, tutorial e fronteira de HTML","scenario":"Uma equipe organiza a documentação de um serviço. Parte do texto possui HTML e seções recolhíveis, e contribuições de outras pessoas passam por publicação sanitizada.","requiredLessons":[19,20,21,22,23,24],"skills":["Objetivo de cada documento","HTML e sanitização","Conteúdo essencial"],"questions":[{"id":"q1","options":["Colocar todos os campos dentro de um único título sem índice.","Apagar os pré-requisitos para encurtar o README.","Manter orientação inicial no README, criar tutorial com começo/fim e colocar contratos de campos numa referência própria.","Usar details como substituto de qualquer organização por finalidade."],"answer":2,"prompt":"O README é uma referência extensa de todos os campos e não mostra como iniciar uma tarefa. Como repartir o conteúdo por objetivo?","explanation":"Primeiro contato, tarefa guiada e consulta de contrato têm necessidades diferentes. A separação melhora a navegação sem descartar informação.","reviewLessons":[22,23,24]},{"id":"q2","options":["Todo HTML num .md executará da mesma forma em qualquer destino.","Desabilitar a sanitização de conteúdo de terceiros é sempre a solução correta.","A presença de details concede permissão para executar scripts arbitrários.","O resultado depende da política do renderizador; é preciso adaptar ou fornecer alternativa e testar a publicação real."],"answer":3,"prompt":"Um bloco HTML funciona na prévia local, mas a publicação sanitizada remove parte dele. O que o autor pode afirmar com segurança?","explanation":"Markdown com HTML possui limites de processamento e segurança. Não confunda suporte sintático com autorização para publicar conteúdo ativo.","reviewLessons":[19,20,21]},{"id":"q3","options":["Manter a orientação essencial visível no fluxo principal e usar a seção recolhível para detalhes complementares, com alternativa conforme o destino.","Ocultar também o título do tutorial.","Assumir que todo leitor abrirá qualquer seção recolhível antes de executar.","Mover os pré-requisitos para um atributo HTML invisível."],"answer":0,"prompt":"Um aviso indispensável ficou somente dentro de details fechado no tutorial. Qual mudança preserva orientação e portabilidade?","explanation":"A tarefa deve continuar compreensível quando o recurso recolhível muda ou não é apresentado. Informação essencial precisa de posição clara.","reviewLessons":[20,21,22,23]}]},{"id":"combo-4","title":"Documentação que evolui sem perder leitores","scenario":"O manual passa a ter vários arquivos, um diagrama Mermaid e metadados de gerador. Uma decisão muda a navegação e precisa ser registrada sem prometer suporte universal.","requiredLessons":[25,26,28,29,31,35],"skills":["Navegação estável","Extensões e fallback","Decisões e compatibilidade"],"questions":[{"id":"q1","options":["Assumir que fragmentos são idênticos e imutáveis em todos os sistemas.","Revisar os links/âncoras segundo o renderizador, preservar destinos estáveis quando suportados e registrar a mudança relevante.","Trocar somente o nome do arquivo de imagem.","Adicionar front matter e concluir que qualquer âncora será preservada."],"answer":1,"prompt":"Um título usado como destino foi renomeado e links antigos deixaram de funcionar. Qual ação combina manutenção e estabilidade?","explanation":"Âncoras geradas dependem do título e do destino de publicação. Teste links internos após mudanças de estrutura.","reviewLessons":[25,26,31,35]},{"id":"q2","options":["Afirmar que cerca mermaid é HTML universal.","Remover a explicação textual porque o diagrama é mais curto.","Fornecer uma alternativa textual da ordem e declarar onde Mermaid é renderizado na matriz de compatibilidade.","Usar front matter como garantia de execução do diagrama."],"answer":2,"prompt":"O diagrama Mermaid comunica uma ordem operacional, mas um destino exibe só o código cercado. Qual entrega mantém a informação acessível?","explanation":"Mermaid é uma extensão. O conteúdo necessário precisa sobreviver em destinos sem esse renderizador.","reviewLessons":[25,28,35]},{"id":"q3","options":["Dizer que todo Markdown reconhece os mesmos metadados nativamente.","Colocar senhas nos metadados porque eles nunca ficam visíveis.","Escolher campos aleatórios sem explicar seu consumidor.","Registrar o gerador e os campos esperados, as consequências de portabilidade e a alternativa para destinos sem essa extensão."],"answer":3,"prompt":"O gerador interpreta front matter, enquanto outro visualizador mostra suas linhas como conteúdo. Como documentar a decisão de usá-lo?","explanation":"Metadados só têm significado para um consumidor definido. Registre contexto e consequências para não tratar uma convenção de ferramenta como regra universal.","reviewLessons":[29,31,35]}]}],"finalProject":{"id":"final","title":"Manual portável de um serviço de biblioteca","scenario":"Entregue a documentação de um serviço fictício de cadastro e empréstimos. Outra pessoa deve conseguir entender a finalidade, seguir uma tarefa e consultar o contrato, inclusive num destino com menos extensões.","requirements":["Criar README com finalidade, pré-requisitos, início rápido, limites e navegação para os demais documentos.","Escrever um tutorial de tarefa com entradas, passos, resultado esperado e caminho para investigar divergências.","Documentar campos, estados, erros e exemplos numa referência consistente com o tutorial.","Organizar caminhos, imagens e âncoras, com rótulos descritivos e informação alternativa para conteúdo visual.","Declarar dialetos e extensões usados e publicar uma matriz de compatibilidade com alternativa para diagramas ou recursos opcionais.","Manter registro de decisão, histórico de mudanças e checklist de revisão, sem credenciais ou afirmações de teste não executado."],"deliverables":["README.md, docs/tutorial.md e docs/referencia.md com conteúdo completo e fictício.","Assets e navegação relativos, com exemplos copiados e conferidos na revisão.","Registro de decisão, changelog e guia/checklist de contribuição.","Matriz de destinos e relatório de inspeção das renderizações e dos links."],"rubric":[{"id":"r1","title":"Estrutura e leitura","description":"Hierarquia, listas e blocos representam o conteúdo sem depender de espaços acidentais.","reviewLessons":[2,4,5,7,8,9]},{"id":"r2","title":"Tarefa reproduzível","description":"O tutorial informa estado inicial, ação e resultado, com evidências compatíveis com o escopo.","reviewLessons":[14,15,22,23]},{"id":"r3","title":"Contrato consistente","description":"Referência e exemplos usam os mesmos nomes, tipos e estados do tutorial.","reviewLessons":[16,17,24,27]},{"id":"r4","title":"Navegação e alternativas","description":"Links, fragmentos e imagens têm destinos conferidos e informação compreensível.","reviewLessons":[10,11,12,13,25,26]},{"id":"r5","title":"Publicação consciente","description":"HTML e extensões possuem contrato declarado, sanitização respeitada e fallback.","reviewLessons":[18,19,20,21,28,29,30,35]},{"id":"r6","title":"Manutenção verificável","description":"Decisões, mudanças e revisão registram o que foi efetivamente observado e o que falta.","reviewLessons":[15,31,32,33,34,36]}],"acceptance":[{"title":"Tarefa por leitor novo","setup":"Prepare os arquivos e uma instância fictícia ou descrição reproduzível do ambiente do tutorial.","input":"Peça a um revisor seguir somente o README e o tutorial, registrando dúvidas e resultados.","expected":"O caminho inicial, comandos/entradas e resultado são encontráveis; divergências são registradas e corrigidas no texto, sem presumir sucesso.","reviewLessons":[14,15,22,23,24]},{"title":"Dois destinos declarados","setup":"Escolha uma base CommonMark e um destino GFM ou outro visualizador explicitamente nomeado.","input":"Abra os documentos nos dois e confira listas, cercas, links, tabelas, HTML e alternativas de diagrama.","expected":"A matriz descreve diferenças reais e os conteúdos essenciais continuam compreensíveis; recursos não suportados não são declarados como funcionais.","reviewLessons":[7,8,18,19,21,28,35]},{"title":"Mudança e navegação","setup":"Registre uma decisão que altera uma seção referenciada.","input":"Atualize título/destino, revise links relativos e registre a mudança e as consequências.","expected":"Links usados pelo leitor continuam válidos ou a mudança é tratada conscientemente; decisões e changelog concordam com a versão entregue.","reviewLessons":[25,26,31,32,33]}],"questions":[{"id":"q1","options":["Portabilidade e alternativa textual da informação necessária à tarefa.","A largura obrigatória da imagem em milímetros.","A criação de um backend para cada página.","Nada, pois todo bloco cercado executa a linguagem indicada."],"answer":0,"prompt":"O manual declara CommonMark, mas uma instrução essencial só aparece num diagrama Mermaid sem descrição. Qual requisito está incompleto?","explanation":"Uma cerca identifica conteúdo; o renderizador de uma extensão é outro mecanismo. A tarefa deve ser recuperável no contrato de publicação prometido.","reviewLessons":[7,14,28,35]},{"id":"q2","options":["Sim, aparência substitui consistência técnica.","Não; o contrato e o exemplo precisam usar uma regra coerente e ter o resultado revisado.","Sim, nomes diferentes sempre significam o mesmo sem explicação.","Não, porque referências não podem conter estados."],"answer":1,"prompt":"Um exemplo do tutorial usa estado concluido, mas a referência só aceita finalizado. O preview está bonito. O projeto está consistente?","explanation":"Documentação é uma interface de uso. Revise vocabulário, entradas e saídas entre tarefa e referência, além da renderização.","reviewLessons":[15,23,24,27]},{"id":"q3","options":["Manter a afirmação porque o arquivo termina em .md.","Usar a quantidade de commits como prova de todos os links.","Separar revisão textual das verificações executadas e realizar ou marcar como pendentes os testes de destino.","Apagar os links para não precisar revisar a navegação."],"answer":2,"prompt":"O relatório marca todos os links como conferidos, mas ninguém abriu os documentos no destino publicado. Qual correção de evidência é necessária?","explanation":"A conclusão deve corresponder ao que foi observado. Publique resultados e limites de revisão com o mesmo cuidado aplicado ao conteúdo técnico.","reviewLessons":[12,15,26,33,34,35]}]}},"mongodb":{"courseId":"mongodb","combos":[{"id":"combo-1","title":"Consulta e atualização de estoque","scenario":"Uma coleção de produtos guarda SKU, quantidade e preço com representação definida. A API precisa consultar uma página estável e baixar estoque sem uma sequência vulnerável de leitura e regravação.","requiredLessons":[2,3,4,5,6,7],"skills":["BSON e projeção","Filtro e ordem","Escrita condicional"],"questions":[{"id":"q1","options":["Uma atualização atômica com filtro por estoque suficiente e decremento, verificando matchedCount/modificação antes de anunciar sucesso.","Ler 5 em cada cliente e ambos gravarem 1 sem condição.","Converter o estoque para texto e ordenar por nome.","Usar uma projeção que esconda estoque e concluir que não há disputa."],"answer":0,"prompt":"Um produto tem estoque 5 e duas requisições tentam retirar 4. Qual operação local ao documento evita que ambas aprovem a partir de uma leitura antiga?","explanation":"A condição precisa fazer parte da escrita sobre o documento. Conferir o resultado distingue a baixa aplicada de uma condição que deixou de ser atendida.","reviewLessons":[3,4,7]},{"id":"q2","options":["Assumir que null sempre significa a string literal null.","Combinar os testes de presença/tipo adequados ao domínio e conferir a projeção, sem tratar as duas situações como sempre idênticas.","Usar sort para tornar o campo obrigatório.","Trocar o nome da coleção e manter o mesmo filtro sem teste."],"answer":1,"prompt":"A consulta {devolvidoEm:null} também pode encontrar documentos sem o campo. Se a regra distingue ausência de campo e valor null, o que revisar?","explanation":"Null e ausência têm semânticas de consulta próprias. Uma projeção também pode ocultar o campo, portanto diferencie armazenamento, filtro e resultado.","reviewLessons":[2,4,5]},{"id":"q3","options":["Confiar na ordem natural como garantia permanente.","Remover o filtro de categoria para evitar empates.","Acrescentar um desempate único à ordem e carregar os componentes relevantes na fronteira da página.","Usar limit como substituto de qualquer sort."],"answer":2,"prompt":"A página ordena só por categoria, que se repete. Qual melhoria é necessária antes de usar limite/cursor como fronteira estável?","explanation":"Limitar não define uma ordem. Campos repetidos exigem desempate quando a paginação precisa de uma sequência determinística.","reviewLessons":[4,5,6]}]},{"id":"combo-2","title":"Modelo, validação e relatório sem multiplicação","scenario":"O catálogo tem pedidos com itens e referências a clientes. O relatório deve contar pedidos e unidades corretamente, e documentos inválidos precisam ser recusados conforme um contrato declarado.","requiredLessons":[10,11,12,13,14,15],"skills":["Padrão de acesso","Schema validation","Agregação e cardinalidade"],"questions":[{"id":"q1","options":["$unwind sempre reduz tudo a uma única linha.","Toda referência a cliente impede qualquer duplicação em agregação.","Uma validação JSON Schema recalcula automaticamente relatórios.","O total do pedido pode ser contado três vezes; preserve a granularidade ou reagrupe a medida correta antes de somar."],"answer":3,"prompt":"Cada pedido possui três itens e o pipeline aplica $unwind antes de somar um campo total do pedido. Qual risco precisa ser corrigido?","explanation":"Desdobrar itens muda a quantidade de documentos do fluxo. A medida precisa corresponder à unidade contada e à etapa em que é agregada.","reviewLessons":[10,13,14]},{"id":"q2","options":["A referência não ganhou integridade referencial automática; é preciso um protocolo de validação/manutenção coerente com a regra do domínio.","$lookup cria o cliente faltante automaticamente.","Guardar um ID equivale sempre a uma foreign key SQL obrigatória.","Um array vazio prova falha do servidor, sem considerar os dados."],"answer":0,"prompt":"A aplicação inseriu clienteId inexistente e $lookup retornou um array vazio. Qual conclusão respeita o modelo MongoDB?","explanation":"Referenciar e relacionar dados não cria por si só uma constraint entre coleções. Defina criação, exclusão e tratamento de referências sem correspondência.","reviewLessons":[10,11,15]},{"id":"q3","options":["Apenas imprimir a variável para que o servidor a adote.","Aplicar a validação à coleção pelo comando apropriado e executar casos válidos e inválidos, verificando erro e estado final.","Adicionar $lookup ao objeto e assumir que isso ativa o schema.","Guardar o schema no README e chamar isso de validação aplicada."],"answer":1,"prompt":"Foi declarada uma variável JavaScript contendo $jsonSchema, mas nenhuma coleção recebeu validator. O teste de inserção inválida passou. O que falta fazer e comprovar?","explanation":"Uma representação no cliente não muda a configuração da coleção. A evidência precisa vir do validator ativo e do comportamento de escrita observado.","reviewLessons":[10,11,12]}]},{"id":"combo-3","title":"Índices, transação e repetição","scenario":"Uma operação cria um pedido e reserva estoque em outro documento. A aplicação utiliza índices e precisa lidar com concorrência e resultado incerto após falha de comunicação.","requiredLessons":[19,20,22,25,26,27],"skills":["Índices e custo","Transação entre documentos","Concerns e idempotência"],"questions":[{"id":"q1","options":["Um standalone sem sessão, confiando que dois updateOne sempre formam uma transação.","Somente um índice composto, que confirma todas as escritas juntas.","Uma topologia que suporte transações, uso da mesma sessão e tratamento explícito de commit/abort e erros.","Aumentar limit na consulta e concluir atomicidade global."],"answer":2,"prompt":"Duas alterações em documentos diferentes devem confirmar juntas. Qual combinação é necessária no laboratório, além da lógica de validação?","explanation":"Atomicidade de um documento não se expande automaticamente para vários. Transação tem pré-requisitos de topologia e contexto de sessão.","reviewLessons":[19,25,26]},{"id":"q2","options":["Criar sempre outro pedido com novo ID após qualquer timeout.","Assumir que timeout significa rollback garantido.","Remover o índice único para que a repetição não cause erro.","Identidade única da operação, comparação do conteúdo e tratamento de retry/resultado incerto conforme a API, sem repetir efeitos cegamente."],"answer":3,"prompt":"O cliente recebeu timeout ao confirmar e não sabe se o pedido foi aplicado. Qual protocolo reduz o risco de uma segunda reserva indevida?","explanation":"Incerteza de comunicação não prova ausência de commit. A identidade da operação e a interpretação dos erros permitem distinguir repetição legítima de nova ação.","reviewLessons":[20,25,26,27]},{"id":"q3","options":["Distribuição/volume representativos, trabalho de leitura e custo de escrita, preservando o resultado correto da consulta.","Apenas o tamanho do nome do índice.","Nada, qualquer IXSCAN garante a mesma latência em qualquer sistema.","Remover todos os demais filtros para obter um número menor."],"answer":0,"prompt":"Um índice foi criado e explain de uma coleção pequena parece favorável. O que ainda precisa ser medido antes de prometer desempenho em outra carga?","explanation":"Estratégia de acesso não é tempo garantido. Compare a mesma pergunta e registre execução, cardinalidade e os custos impostos às escritas.","reviewLessons":[19,20,22]}]},{"id":"combo-4","title":"Acesso, evolução e retomada","scenario":"A API recebe filtros externos, evolui documentos versionados e publica alterações por change streams. Um operador prepara uma cópia BSON para recuperação em outra base.","requiredLessons":[28,29,31,33,35,36],"skills":["Consulta controlada","Migração e eventos","Recuperação"],"questions":[{"id":"q1","options":["Confiar em JSON válido como autorização para qualquer consulta.","Construir filtros a partir de campos/operadores permitidos e usar uma conta com privilégios limitados à função.","Usar conta administrativa para que todo operador funcione.","Mudar apenas a extensão do arquivo para .js."],"answer":1,"prompt":"A API aceita um objeto do usuário e o repassa inteiro como filtro, incluindo operadores inesperados. Qual revisão combina validação e autorização?","explanation":"Formato válido não significa intenção autorizada. A fronteira da API deve controlar estrutura e valores, e a identidade do banco deve limitar efeitos.","reviewLessons":[28,29,36]},{"id":"q2","options":["Assumir que qualquer token recria eventos apagados para sempre.","Apagar o estado de todos os usuários sem diagnóstico.","Tratar a impossibilidade de retomar daquele ponto e executar uma estratégia definida de reconciliação/reconstrução, sem prometer replay ilimitado.","Tratar uma migração de schema como garantia de retenção infinita."],"answer":2,"prompt":"O consumidor guardou um resume token, mas ficou parado além do histórico disponível. Qual comportamento precisa existir?","explanation":"Retomada depende do histórico e do estado do fluxo. Versionamento e deduplicação ajudam, mas não recuperam dados que já não estão disponíveis.","reviewLessons":[31,33,35]},{"id":"q3","options":["Apenas renomear o arquivo para sucesso.archive.","Assumir que contar arquivos prova equivalência de todos os dados.","Abrir um change stream e concluir que isso testa qualquer backup.","Conferir tipos, índices/regras necessários e resultados de domínio no destino, além dos logs da ferramenta."],"answer":3,"prompt":"Uma cópia foi restaurada em outra base e os documentos aparecem, mas tipos BSON e invariantes não foram conferidos. Qual etapa falta?","explanation":"A restauração deve produzir o estado utilizável esperado. Ferramenta concluída e dados presentes não bastam para afirmar todos os contratos do projeto.","reviewLessons":[31,35,36]}]}],"finalProject":{"id":"final","title":"Agenda de oficinas com inscrições idempotentes","scenario":"Construa a persistência de oficinas, participantes e inscrições com vagas limitadas. O sistema precisa distinguir pedido novo, repetição idêntica e conflito; consultar relatórios e provar recuperação com dados fictícios.","requirements":["Definir documentos e relações a partir das consultas, com tipos BSON e validators aplicados às coleções.","Reservar vaga e registrar inscrição de forma consistente; quando houver múltiplos documentos, usar transação na topologia apropriada.","Identificar a operação por chave única, comparar conteúdo em repetições e tratar falhas/resultado incerto com política limitada.","Criar consultas paginadas e relatórios de inscrições sem duplicar medidas após $unwind/$lookup; justificar os índices com explain e dados de teste.","Construir filtros permitidos na API e separar a identidade de aplicação da conta administrativa, demonstrando ações recusadas.","Versionar a evolução dos documentos e ensaiar retomada/reconciliação de eventos e backup BSON restaurado em base separada."],"deliverables":["Scripts de coleções, validators, índices e fixtures, com versão/topologia do laboratório.","Cliente ou roteiro funcional das operações, entradas, consultas e respostas esperadas.","Relatório de testes de concorrência, duplicata, recusa, explicação dos planos e limites de retomada.","Runbook de migração, backup/restauração e conferência do destino, com logs e resultados reais."],"rubric":[{"id":"r1","title":"Modelo e contrato","description":"A granularidade e os tipos são definidos e a validação está aplicada, não só declarada no cliente.","reviewLessons":[2,3,10,11,12]},{"id":"r2","title":"Consistência da inscrição","description":"Vagas e inscrição têm unidade de trabalho comprovada, com casos sem capacidade e erro intermediário.","reviewLessons":[7,25,26]},{"id":"r3","title":"Repetição controlada","description":"Chave, conteúdo, erros e janela de repetição fazem parte do protocolo.","reviewLessons":[9,20,25,27]},{"id":"r4","title":"Consulta e desempenho","description":"Paginação, agregação e índices mantêm resultados corretos e medições contextualizadas.","reviewLessons":[6,13,14,15,17,19,22,24]},{"id":"r5","title":"Acesso e diagnóstico","description":"Filtros e permissões limitam a operação e erros são observáveis sem credenciais nos logs.","reviewLessons":[28,29,30,32]},{"id":"r6","title":"Evolução recuperável","description":"Versionamento, eventos e cópia restaurada possuem procedimentos e limites explícitos.","reviewLessons":[21,31,33,34,35,36]}],"acceptance":[{"title":"Duas tentativas para a última vaga","setup":"Crie oficina com uma vaga e duas identidades de operação diferentes; use o replica set local para o fluxo transacional.","input":"Dispare duas tentativas concorrentes de inscrição e consulte vagas e registros confirmados.","expected":"Somente uma inscrição é aceita; vagas não ficam negativas e o estado rejeitado não deixa metade da operação persistida.","reviewLessons":[7,20,25,26,27]},{"title":"Repetição e validação de entrada","setup":"Prepare uma operação confirmada e fixtures inválidas para tipos/campos e estrutura de filtro.","input":"Repita a mesma operação com mesmo conteúdo, depois com conteúdo diferente; tente documento inválido e operador não permitido.","expected":"Repetição idêntica não reserva outra vaga; conflito é distinguido; documento/filtro indevido é recusado com estado preservado.","reviewLessons":[12,20,27,28,29]},{"title":"Cópia, migração e eventos","setup":"Preserve documentos conhecidos, versão de schema, índices e token/estado de consumidor quando o ensaio usar change streams.","input":"Execute backup/restauração em base separada e confira o estado; aplique a migração prevista e ensaie retomada ou reconciliação.","expected":"Dados, tipos e invariantes esperados coincidem no destino; migração e retomada têm resultados e limites registrados, sem prometer histórico infinito.","reviewLessons":[31,33,35,36]}],"questions":[{"id":"q1","options":["A propagação da sessão e os limites de transação/erro em todas as operações da unidade.","Somente a ordem das propriedades JSON no arquivo.","Adicionar um sort à consulta para que escritas sejam confirmadas juntas.","Assumir que qualquer conexão cria transação automática entre documentos."],"answer":0,"prompt":"No projeto, duas coleções ficaram parcialmente atualizadas após erro. Ambas usaram a mesma conexão, mas não a mesma sessão transacional. O que revisar?","explanation":"A unidade transacional exige o contexto apropriado nas operações. Valide também pré-requisitos da topologia e o estado após a falha.","reviewLessons":[7,25,26,27]},{"id":"q2","options":["Sim, devolver o mesmo ID resolve qualquer efeito duplicado.","Não; a decisão de repetição e o efeito precisam estar coordenados para não duplicar a reserva.","Sim, o índice único sempre desfaz atualizações anteriores externas à unidade.","Não, porque IDs não podem ser usados em protocolos."],"answer":1,"prompt":"A repetição retorna o mesmo ID, mas o estoque foi reservado de novo antes de verificar a chave. O requisito de idempotência foi atendido?","explanation":"Identificar a resposta não basta quando um efeito já ocorreu outra vez. Organize a unidade de trabalho e o comportamento de conflito e reentrega.","reviewLessons":[7,20,25,27]},{"id":"q3","options":["A cor do log de terminal.","Apenas o nome da cópia, sem abrir a base.","A configuração de validação e os testes positivos/negativos do estado restaurado.","Nenhuma, porque o processo ter retornado zero prova toda regra do produto."],"answer":2,"prompt":"Os logs de restore registram sucesso, mas a inscrição com tipo inválido continua aceita no destino. Que evidência ainda precisa ser corrigida?","explanation":"A cópia utilizável precisa conservar os contratos exigidos. Verifique os validators, índices e invariantes, além do resultado do executável.","reviewLessons":[12,20,31,35,36]}]}},"mysql":{"courseId":"mysql","combos":[{"id":"combo-1","title":"Cadastro e movimentação InnoDB","scenario":"Um checkout cria pedido e itens em MySQL 8.4 LTS. Os valores precisam ser exatos, referências válidas e qualquer falha deve deixar o estado anterior.","requiredLessons":[4,5,6,7,8,9],"skills":["Domínio exato","Identidade e FK","Transação de escrita"],"questions":[{"id":"q1","prompt":"O total financeiro usa DECIMAL, mas quantidade permite NULL e preço negativo. Qual ajuste completa o domínio?","options":["Confiar que DECIMAL valida qualquer regra de negócio.","Declarar obrigatoriedade e CHECKs apropriados, além de usar representação numérica exata.","Mudar tudo para FLOAT e arredondar apenas na tela.","Retirar as constraints para evitar erro no cliente."],"answer":1,"explanation":"Escolha do tipo, presença e intervalo atendem regras diferentes. Valor exato não torna válido um preço proibido pelo domínio.","reviewLessons":[4,5]},{"id":"q2","prompt":"O pedido recebe AUTO_INCREMENT e seus itens precisam referenciá-lo. Como evitar associar itens ao pedido de outro cliente concorrente?","options":["Consultar MAX(id) global antes de inserir os itens.","Escolher qualquer ID que apareceu no relatório.","Obter o identificador da própria inserção pela conexão/API apropriada e protegê-lo com a FK do item.","Guardar somente o nome do comprador no item, sem referência."],"answer":2,"explanation":"O ID gerado deve pertencer à escrita corrente; a FK protege a referência. MAX global não identifica a operação da sessão.","reviewLessons":[6,7]},{"id":"q3","prompt":"O UPDATE de estoque passou, mas a inclusão de um item obrigatório falhou. Qual ação preserva o checkout como unidade?","options":["Executar COMMIT para salvar a parte que funcionou.","Repetir o UPDATE em outra conexão sem reavaliar o estado.","Usar DELETE sem WHERE para remover a falha.","Reverter a transação completa, conferindo efeitos e evitando confirmar só a baixa."],"answer":3,"explanation":"InnoDB permite agrupar os efeitos obrigatórios. O cliente precisa fechar a transação corretamente em cada caminho de erro.","reviewLessons":[8,9]}]},{"id":"combo-2","title":"Relatórios e navegação do catálogo","scenario":"A tela mostra clientes sem pedidos, uma página estável e indicadores extraídos de documentos JSON nativos. As consultas precisam responder à granularidade definida.","requiredLessons":[10,11,12,13,15,18],"skills":["NULL e multiplicidade","Cursor determinístico","JSON e CTE"],"questions":[{"id":"q1","prompt":"Um cliente sem pedidos desapareceu depois de aplicar WHERE pedido.status=pago a um LEFT JOIN. Como preservar o cliente e contar só pedidos pagos?","options":["Restringir a correspondência em ON e contar uma chave não nula do pedido por cliente.","Trocar o WHERE por ORDER BY e manter COUNT(*) como número de pedidos.","Usar INNER JOIN para preservar ausência.","Transformar NULL em um ID de pedido real."],"answer":0,"explanation":"O filtro na parte direita pode eliminar a linha preservada. COUNT da chave direita separa ausência de filho de uma linha de pedido.","reviewLessons":[10,12,13]},{"id":"q2","prompt":"A página ordena por criado_em,id e existem horários empatados. O próximo cursor guarda apenas criado_em. O que falta?","options":["Retirar ORDER BY para que o banco decida.","Incluir id no cursor e reproduzir os dois critérios no predicado, tratando ausência conforme o contrato.","Assumir que LIMIT resolve os empates sozinho.","Usar apenas o número de linhas da página como identidade permanente."],"answer":1,"explanation":"O cursor representa a posição completa na ordem. Empates e valores ausentes precisam de uma regra consistente de navegação.","reviewLessons":[10,11]},{"id":"q3","prompt":"Uma CTE prepara eventos cujo JSON possui total, e a etapa seguinte soma por tipo. Qual é o contrato necessário para a medida?","options":["Somar o texto JSON bruto e supor conversão válida de qualquer conteúdo.","Contar caracteres do documento como receita.","Extrair e converter total para o tipo numérico esperado, tratar ausência e declarar a granularidade da CTE/agregação.","Presumir que declarar uma CTE valida todos os campos JSON."],"answer":2,"explanation":"JSON nativo valida a representação do documento, não o significado de cada medida. A decomposição da consulta deve conservar o conjunto e a unidade corretos.","reviewLessons":[15,18]}]},{"id":"combo-3","title":"Índices, auditoria e estoque disputado","scenario":"O catálogo indexa campos JSON, o histórico registra mudanças e duas operações concorrentes reservam produtos. A equipe precisa distinguir plano, efeito e falha.","requiredLessons":[19,20,21,23,26,27],"skills":["Acesso por índice","Efeitos da escrita","Locks e retry"],"questions":[{"id":"q1","prompt":"Um índice composto foi criado para filtrar cliente e ordenar por data. Qual evidência deve acompanhar EXPLAIN/ANALYZE?","options":["Somente o nome do índice no texto.","Uma promessa de tempo deduzida do custo estimado.","Nenhum dado, porque todo índice é sempre melhor.","Mesmo resultado, dados representativos e medição comparável; ANALYZE executa o trabalho analisado."],"answer":3,"explanation":"O índice é uma hipótese que o plano e a carga ajudam a avaliar. Resultado funcional e efeitos da instrução não podem ser ignorados.","reviewLessons":[19,20]},{"id":"q2","prompt":"Um campo JSON indexado por coluna gerada mudou e o trigger audita todo UPDATE. Qual teste verifica o comportamento completo?","options":["Conferir o valor/indexabilidade da coluna gerada e se a auditoria registra apenas a mudança de domínio pretendida, inclusive no UPDATE sem mudança.","Conferir só o nome da tabela no cliente.","Assumir que JSON atualizado não altera colunas geradas.","Contar triggers como prova de correção de qualquer índice."],"answer":0,"explanation":"Coluna gerada e auditoria respondem a aspectos diferentes da escrita. O teste precisa observar a representação consultável e o evento que o domínio deseja registrar.","reviewLessons":[21,23]},{"id":"q3","prompt":"Duas transações bloqueiam produtos em ordem inversa e uma vira vítima de deadlock. Qual estratégia é adequada?","options":["Repetir somente o último UPDATE sem reconstruir a decisão.","Tratar a falha, refazer a unidade de negócio com limite e idempotência e reduzir o ciclo usando ordem consistente de locks quando aplicável.","Ignorar o erro e anunciar confirmação.","Afirmar que SELECT FOR UPDATE elimina todo deadlock possível."],"answer":1,"explanation":"Locks protegem invariantes, mas podem formar ciclos. A vítima precisa de protocolo de recuperação, e o retry não pode duplicar efeitos.","reviewLessons":[26,27]}]},{"id":"combo-4","title":"Permissões, evolução e recuperação","scenario":"O serviço possui conta limitada, consultas parametrizadas, dump lógico e binary logs. A implantação altera o esquema enquanto ainda existem consumidores antigos e réplicas.","requiredLessons":[28,29,31,32,33,35],"skills":["Menor privilégio","Dump e PITR","Compatibilidade operacional"],"questions":[{"id":"q1","prompt":"A consulta usa parâmetros, mas a conta da aplicação tem privilégios administrativos globais. O teste de segurança está completo?","options":["Sim, binding limita automaticamente a conta a SELECT.","Sim, senha em prompt elimina qualquer necessidade de roles.","Não; reduza privilégios e teste também comandos que devem ser recusados.","Não, porque parâmetros são incompatíveis com roles."],"answer":2,"explanation":"Binding separa valores da sintaxe, enquanto grants limitam capacidades da identidade. Os dois controles são complementares.","reviewLessons":[28,29]},{"id":"q2","prompt":"O dump foi aberto num destino novo, mas é preciso recuperar uma exclusão ocorrida depois da cópia. O que falta ao plano?","options":["Renomear o dump e assumir que contém operações futuras.","Usar a mesma instância de origem como destino sobrescrito sem conferência.","Concluir que SHOW BINARY LOG STATUS já realizou a recuperação.","Preservar o backup-base e os binlogs necessários e ensaiar a recuperação até o ponto escolhido."],"answer":3,"explanation":"Dump e binlogs têm papéis distintos. Inspecionar posição não aplica os logs nem prova que o alvo foi recuperado.","reviewLessons":[31,32]},{"id":"q3","prompt":"A coluna antiga ainda é usada por uma versão da aplicação e por leitura na réplica. Como executar a migração com menos ruptura?","options":["Expandir e manter compatibilidade, migrar consumidores/dados e só contrair após verificar a transição e o estado da replicação.","Remover a coluna primeiro e esperar que a réplica recrie sozinha.","Assumir que GTID converte automaticamente qualquer contrato da aplicação.","Desligar testes porque DDL atômico equivale a rollback de qualquer implantação."],"answer":0,"explanation":"Atomicidade de uma operação DDL não resolve compatibilidade entre versões nem atraso operacional. A mudança precisa de etapas e verificação dos consumidores.","reviewLessons":[33,35]}]}],"finalProject":{"id":"final","title":"Checkout idempotente e operável no MySQL","scenario":"Implemente o banco de uma loja fictícia com catálogo, pedidos e estoque. Use MySQL 8.4 LTS/InnoDB e clientes locais; dados e credenciais reais não fazem parte da entrega.","requirements":["Integridade exata: tipos monetários, chaves, referências, nulabilidade e limites são protegidos pelo esquema.","Checkout atômico: reserva de estoque e pedido confirmam juntos e erro intermediário não deixa efeitos parciais.","Repetição controlada: chave idempotente, comparação de conteúdo e retorno estável; deadlock tem retry limitado da unidade.","Consultas medidas: relatório sem multiplicação, paginação por chave e índice justificado com resultado funcional conferido.","Acesso e evolução: conta limitada, binding, fronteira TLS documentada e migration compatível com consumidores existentes.","Recuperação verificável: dump restaurado em banco exclusivo, marcadores conferidos e estratégia de binlog/replicação sem prometer ensaio não realizado."],"deliverables":["DDL, fixtures e migrations com versão e pré-requisitos.","Cliente com operações parametrizadas e contrato de repetição.","Testes de concorrência, relatórios e planos com resultados documentados.","Runbook de dump/restore e recuperação por ponto com evidências e limites."],"rubric":[{"id":"r1","title":"Integridade exata","description":"Integridade exata: tipos monetários, chaves, referências, nulabilidade e limites são protegidos pelo esquema.","reviewLessons":[4,5,6]},{"id":"r2","title":"Checkout atômico","description":"Checkout atômico: reserva de estoque e pedido confirmam juntos e erro intermediário não deixa efeitos parciais.","reviewLessons":[8,9,26]},{"id":"r3","title":"Repetição controlada","description":"Repetição controlada: chave idempotente, comparação de conteúdo e retorno estável; deadlock tem retry limitado da unidade.","reviewLessons":[7,27,36]},{"id":"r4","title":"Consultas medidas","description":"Consultas medidas: relatório sem multiplicação, paginação por chave e índice justificado com resultado funcional conferido.","reviewLessons":[11,12,13,19,20]},{"id":"r5","title":"Acesso e evolução","description":"Acesso e evolução: conta limitada, binding, fronteira TLS documentada e migration compatível com consumidores existentes.","reviewLessons":[28,29,30,35]},{"id":"r6","title":"Recuperação verificável","description":"Recuperação verificável: dump restaurado em banco exclusivo, marcadores conferidos e estratégia de binlog/replicação sem prometer ensaio não realizado.","reviewLessons":[31,32,33]}],"acceptance":[{"title":"Requisição repetida","setup":"Um produto com estoque 2 e nenhuma req-1 registrada.","input":"Criar pedido de uma unidade e reenviar a mesma req-1; depois reutilizar a chave com conteúdo diferente.","expected":"A repetição idêntica mantém um pedido/uma baixa; a divergente recebe conflito definido.","reviewLessons":[7,9,27,36]},{"title":"Disputa e deadlock","setup":"Duas conexões sobre tabelas persistentes de laboratório com dois produtos.","input":"Executar reserva concorrente e a intercalação que forma um ciclo de espera.","expected":"A falha é identificada e a unidade é refeita com limite sem pedido parcial ou débito duplicado.","reviewLessons":[25,26,27]},{"title":"Destino restaurado","setup":"Dump da fixture conhecida e banco de restore vazio autorizado.","input":"Importar e conferir contagens, totais e tentativas inválidas no destino.","expected":"Dados e regras conferem; arquivos/logs são preservados conforme o roteiro. PITR depende de ensaio adicional com logs válidos.","reviewLessons":[5,31,32]}],"questions":[{"id":"q1","prompt":"A chave idempotente repetida retorna o mesmo ID, mas uma segunda baixa de estoque ocorreu. Qual requisito falhou?","options":["Somente o texto da resposta.","A coordenação entre deduplicação e efeitos na mesma unidade de negócio.","A escolha da fonte do editor.","O nome AUTO_INCREMENT, que impede transações."],"answer":1,"explanation":"Retorno estável sem efeitos estáveis não é idempotência da operação completa.","reviewLessons":[9,27,36]},{"id":"q2","prompt":"O backup restaurou linhas, mas a conta leitora ainda consegue criar objetos e a API concatena filtros. O projeto está completo?","options":["Sim, restore cobre todas as propriedades da aplicação.","Sim, JSON nativo evita injection em qualquer consulta.","Não; faltam correções e testes de privilégio e parametrização, além da recuperação já verificada.","Não, porque backups nunca são úteis."],"answer":2,"explanation":"Recuperação, autorização e estrutura segura de consulta são critérios independentes.","reviewLessons":[28,29,31]},{"id":"q3","prompt":"Uma réplica passou a mostrar a exclusão acidental da origem. Isso contradiz o funcionamento esperado da replicação?","options":["Sim, toda réplica deve bloquear DELETE automaticamente.","Sim, GTID guarda todas as versões como uma lixeira ilimitada.","Não, porque nenhum banco pode recuperar dados.","Não; ela pode propagar a exclusão, e recuperação histórica requer cópias/logs apropriados."],"answer":3,"explanation":"Replicar efeitos e recuperar um ponto anterior são capacidades diferentes que devem ser planejadas e testadas.","reviewLessons":[31,32,33]}]}},"oracle":{"courseId":"oracle","combos":[{"id":"combo-1","title":"Reserva com regras e relatórios","scenario":"Um schema Oracle 26ai Free guarda recursos e reservas. O cadastro deve diferenciar ausência, rejeitar estados inválidos e produzir um relatório que inclua recursos sem reservas.","requiredLessons":[2,3,5,8,9],"skills":["NULL e domínio","Efeito de UPDATE","Junção e medida"],"questions":[{"id":"q1","prompt":"O nome do recurso é obrigatório e uma entrada vazia é enviada como string vazia no Oracle. Qual regra precisa ser considerada?","options":["Que string vazia sempre é um nome válido e distinto de NULL nesse contrato.","Que CHECK de quantidade valida automaticamente o nome.","O comportamento de string vazia como NULL e uma restrição NOT NULL para o nome, além das demais regras do domínio.","Que um alias nome_obrigatorio torna a coluna obrigatória."],"answer":2,"explanation":"A representação de ausência no Oracle afeta a validação. Obrigatoriedade precisa existir no esquema; não basta um rótulo na consulta.","reviewLessons":[2,3]},{"id":"q2","prompt":"UPDATE reduz vagas somente quando há quantidade suficiente e usa SQL%ROWCOUNT/RETURNING. Nenhuma linha foi alterada. Qual comportamento é correto?","options":["Assumir sucesso e inventar uma linha retornada.","Desligar CHECK para que qualquer saldo seja permitido.","Usar o maior ID global como prova de que a baixa ocorreu.","Tratar recurso ausente ou condição não atendida; não anunciar reserva confirmada apenas porque o bloco executou."],"answer":3,"explanation":"A constraint protege estados válidos e a contagem de efeitos confirma se a condição da escrita foi satisfeita. Execução sem erro não equivale a efeito esperado.","reviewLessons":[3,5]},{"id":"q3","prompt":"Um LEFT JOIN mantém recurso sem reservas, mas COUNT(*) mostra 1. Como obter zero reservas e não multiplicar uma medida do recurso?","options":["Contar a chave não nula da reserva e definir a granularidade antes de agregar.","Trocar para INNER JOIN para manter os ausentes.","Somar a capacidade do recurso uma vez por reserva sem examinar a relação.","Aplicar DISTINCT ao nome e chamar qualquer soma de capacidade."],"answer":0,"explanation":"A linha preservada não é uma reserva real. Medidas do pai e do filho precisam ser calculadas no nível correspondente.","reviewLessons":[8,9]}]},{"id":"combo-2","title":"API PL/SQL e auditoria","scenario":"O banco expõe uma package de reservas, processa conjuntos e registra mudanças por trigger. Os erros devem preservar o limite de trabalho previsto.","requiredLessons":[11,14,15,16,17,18],"skills":["Janela e processamento","Contrato de package","Exceção e auditoria"],"questions":[{"id":"q1","prompt":"Um relatório mantém cada movimento e calcula saldo acumulado; um cursor percorre esse resultado. O que define uma sequência reproduzível?","options":["Apenas a ordem em que o cursor foi declarado.","Ordem/frame da função analítica e ordenação final com desempate no resultado percorrido.","GROUP BY sem as linhas de detalhe, afirmando que nada foi reduzido.","Supor que qualquer plano físico preserva a mesma ordem sem ORDER BY."],"answer":1,"explanation":"A função analítica calcula sobre uma janela e o cursor consome linhas. Cálculo e apresentação precisam de ordem coerente; não dependa de ordem física.","reviewLessons":[11,15]},{"id":"q2","prompt":"Uma procedure pública mudou seus parâmetros, mas somente o body da package foi ajustado. Qual contrato precisa ser revisto?","options":["Apenas o nome do arquivo .sql.","Uma trigger para converter automaticamente qualquer chamada antiga.","A especificação pública, sua implementação e os consumidores que chamam a assinatura alterada.","Remover a especificação porque packages não têm interface."],"answer":2,"explanation":"A package separa interface e implementação. Uma assinatura pública envolve os chamadores e deve evoluir com compatibilidade ou adaptação explícita.","reviewLessons":[16,17]},{"id":"q3","prompt":"Uma etapa após SAVEPOINT altera reserva e o trigger grava auditoria. Um erro leva a ROLLBACK TO dessa etapa. O que esperar da auditoria comum dessa mesma transação?","options":["A auditoria sempre confirma automaticamente em transação independente.","O trigger fica desativado para sempre.","ROLLBACK TO altera somente a variável do bloco, nunca dados.","As mudanças da etapa e sua auditoria posterior ao savepoint são desfeitas juntas."],"answer":3,"explanation":"Savepoint delimita mudanças na unidade. Um trigger transacional comum participa do mesmo limite; auditoria autônoma seria outro contrato.","reviewLessons":[14,18]}]},{"id":"combo-3","title":"Plano e reserva concorrente","scenario":"O serviço consulta por intervalo de data e disputa vagas. O operador precisa compreender o efeito de DDL, snapshots de leitura e leituras bloqueantes em duas sessões.","requiredLessons":[19,20,21,22,23,24],"skills":["Acesso e estatísticas","Commit e visibilidade","FOR UPDATE e NOWAIT"],"questions":[{"id":"q1","prompt":"Há índice sobre instante, mas o filtro aplica função à coluna e o plano não usa o acesso esperado. Qual investigação é adequada?","options":["Revisar um predicado por faixa equivalente quando aplicável, estatísticas e plano, preservando o mesmo resultado antes de medir.","Obrigar qualquer índice sem conferir a semântica da data.","Assumir que EXPLAIN PLAN mede a latência real por definição.","Adicionar índices em todas as colunas e dispensar medição."],"answer":0,"explanation":"Predicado pesquisável, estatísticas e estrutura de acesso influenciam o plano. A reescrita precisa preservar limites temporais e o resultado funcional.","reviewLessons":[19,20,21]},{"id":"q2","prompt":"A altera um valor sem commit e B usa READ COMMITTED, lendo o valor confirmado anterior. A executa DDL comum bem-sucedido, que confirma trabalho pendente. O que B pode observar em uma nova consulta?","options":["Obrigatoriamente o valor antigo para sempre.","O valor de A agora confirmado, pois a nova instrução tem outra visão de leitura.","Dados não confirmados de qualquer sessão, mesmo antes do DDL.","Uma cópia remota criada pelo ALTER."],"answer":1,"explanation":"Consistência de leitura e limites de commit são distintos. DDL Oracle comum pode confirmar a transação; uma nova instrução em READ COMMITTED observa o estado confirmado apropriado.","reviewLessons":[22,23]},{"id":"q3","prompt":"A mantém FOR UPDATE na linha. B faz SELECT comum e depois tenta FOR UPDATE NOWAIT. Qual diferença deve ser prevista?","options":["Ambos sempre recebem o lock sem disputa.","SELECT comum necessariamente confirma a transação de A.","A leitura comum pode ver estado confirmado via MVCC, enquanto a tentativa bloqueante pode falhar imediatamente por recurso ocupado.","NOWAIT significa aguardar indefinidamente até A terminar."],"answer":2,"explanation":"Leitura consistente e aquisição de lock são operações diferentes. NOWAIT evita esperar, não ignora o bloqueio existente.","reviewLessons":[23,24]}]},{"id":"combo-4","title":"Contrato público e recuperação com alvo","scenario":"A API possui usuário limitado e bind variables. Uma migration modifica o esquema, enquanto exportações lógicas e backups físicos precisam ter seu alcance documentado.","requiredLessons":[25,26,30,31,32,33],"skills":["Privilégios e binds","Migração e cópia lógica","RMAN e PITR"],"questions":[{"id":"q1","prompt":"A procedure usa binds, mas seu usuário pode alterar objetos de qualquer aplicação. Qual parte da entrega ainda falha?","options":["Somente a formatação da SQL.","Nenhuma, porque binds substituem qualquer controle de acesso.","A escolha do tablespace apenas.","A definição e o teste de privilégios mínimos; binding não limita a identidade por si só."],"answer":3,"explanation":"Valores ligados evitam misturar entrada e sintaxe, enquanto grants determinam capacidades. Ambos precisam corresponder ao papel da API.","reviewLessons":[25,26]},{"id":"q2","prompt":"Um Data Pump foi exportado antes da migration v2 e importado em schema separado. O destino ainda está no contrato v1. Como conferir corretamente?","options":["Comparar com o ponto exportado e aplicar a migration explicitamente no destino se o objetivo do ensaio incluir chegar à v2.","Assumir que impdp executa automaticamente qualquer migration futura da aplicação.","Mudar só o número da versão para fingir o novo esquema.","Comparar cegamente com a origem já alterada e declarar corrupção por qualquer diferença prevista."],"answer":0,"explanation":"Uma cópia corresponde a um ponto e contrato de origem. Evolução posterior não aparece no dump por previsão; o ensaio precisa declarar qual estado busca recuperar.","reviewLessons":[30,31]},{"id":"q3","prompt":"RMAN RESTORE DATABASE VALIDATE terminou, mas o requisito é abrir uma cópia até um SCN conhecido. O que ainda falta?","options":["Afirmar que VALIDATE já reescreveu datafiles e abriu a cópia.","Executar a recuperação apropriada em alvo descartável com backups/logs necessários e conferir os marcadores do SCN escolhido.","Renomear o arquivo de backup para o número do SCN.","Usar apenas SELECT da origem como prova da recuperação."],"answer":1,"explanation":"VALIDATE verifica insumos, não realiza toda a restauração e abertura. PITR exige alvo, cadeia e evidência do ponto efetivamente recuperado.","reviewLessons":[32,33]}]}],"finalProject":{"id":"final","title":"API de reservas com package e recuperação Oracle","scenario":"Implemente um schema de reservas de recursos em Oracle AI Database 26ai Free. A interface PL/SQL deve ter contrato público, regras verificáveis e ensaios locais que distingam leitura, escrita e recuperação.","requirements":["Modelo de reservas: constraints, referências, identidades e regras de ausência/valores cobrem entradas inválidas e histórico.","API PL/SQL: package com especificação clara, parâmetros validados e tratamento de exceção sem ocultar falhas obrigatórias.","Atomicidade e disputa: reserva e baixa de vagas pertencem à mesma unidade; duas sessões demonstram bloqueio e recusa sem saldo negativo.","Leituras e desempenho: relatórios preservam granularidade, analíticas têm ordem/frame e um índice é investigado com predicado e estatísticas coerentes.","Acesso e evolução: usuário da API recebe privilégios mínimos, SQL dinâmico vincula valores e migrations respeitam commits implícitos do DDL.","Recuperação demonstrada: exportação/importação lógica validada e roteiro físico/PITR com privilégios, caminhos, SCN e estado de ensaio explicitados."],"deliverables":["DDL, fixture fictícia, dicionário e migrations com seus limites de confirmação.","Especificação/body da package, cliente e contrato de erros.","Ensaios de duas sessões, relatórios e investigação de plano com resultados.","Runbook Data Pump/RMAN/PITR que separa preparação, validação e recuperação executada."],"rubric":[{"id":"r1","title":"Modelo de reservas","description":"Modelo de reservas: constraints, referências, identidades e regras de ausência/valores cobrem entradas inválidas e histórico.","reviewLessons":[2,3,4,6]},{"id":"r2","title":"API PL/SQL","description":"API PL/SQL: package com especificação clara, parâmetros validados e tratamento de exceção sem ocultar falhas obrigatórias.","reviewLessons":[14,16,17,18]},{"id":"r3","title":"Atomicidade e disputa","description":"Atomicidade e disputa: reserva e baixa de vagas pertencem à mesma unidade; duas sessões demonstram bloqueio e recusa sem saldo negativo.","reviewLessons":[22,23,24,36]},{"id":"r4","title":"Leituras e desempenho","description":"Leituras e desempenho: relatórios preservam granularidade, analíticas têm ordem/frame e um índice é investigado com predicado e estatísticas coerentes.","reviewLessons":[8,9,11,19,20,21]},{"id":"r5","title":"Acesso e evolução","description":"Acesso e evolução: usuário da API recebe privilégios mínimos, SQL dinâmico vincula valores e migrations respeitam commits implícitos do DDL.","reviewLessons":[25,26,30]},{"id":"r6","title":"Recuperação demonstrada","description":"Recuperação demonstrada: exportação/importação lógica validada e roteiro físico/PITR com privilégios, caminhos, SCN e estado de ensaio explicitados.","reviewLessons":[31,32,33,34]}],"acceptance":[{"title":"Falha na reserva","setup":"Recurso com duas vagas e nenhuma requisição de teste.","input":"Executar reserva válida e provocar falha controlada em etapa obrigatória de outra operação.","expected":"Somente a unidade válida confirma; a falha não conserva baixa parcial nem auditoria transacional indevida.","reviewLessons":[14,18,22,36]},{"title":"Bloqueio em duas sessões","setup":"Tabela persistente do laboratório e A com FOR UPDATE sobre o recurso.","input":"B tenta FOR UPDATE NOWAIT; após A encerrar, B refaz a leitura e a decisão.","expected":"B identifica recurso ocupado antes da liberação e revalida o estado depois, sem assumir vagas antigas.","reviewLessons":[23,24,36]},{"title":"Cópia e ponto recuperado","setup":"Fixture com marcadores e destino lógico/instância de teste preparados por operador autorizado.","input":"Importar a cópia lógica e conferir seus dados; se houver ensaio PITR, recuperar o SCN registrado e abrir o destino.","expected":"O destino lógico corresponde ao ponto exportado; PITR só passa com os marcadores esperados no alvo real, não apenas VALIDATE.","reviewLessons":[31,32,33]}],"questions":[{"id":"q1","prompt":"A package trata qualquer exceção e imprime sucesso, mas uma baixa parcial persiste. Qual correção é necessária?","options":["Apenas trocar o texto para concluído.","Retirar constraints para reduzir exceções.","Restabelecer o contrato de erro e o limite transacional, verificando rollback/efeitos com casos de falha.","Marcar a API como autônoma para esconder a causa."],"answer":2,"explanation":"Tratamento de exceção não pode transformar falha de negócio em sucesso aparente. O estado final precisa preservar a unidade.","reviewLessons":[14,16,22,36]},{"id":"q2","prompt":"A migration pressupõe que todo DDL Oracle será desfeito pelo rollback externo. Como a revisão deve responder?","options":["Aceitar porque qualquer BEGIN altera a regra de DDL.","Desligar logs para não notar commits.","Mover o script para SQLcl e presumir outra semântica do motor.","Exigir etapas e recuperação compatíveis com os commits implícitos dos comandos usados e conferir os dados anteriores."],"answer":3,"explanation":"Cliente não muda a semântica transacional do DDL. Evolução exige planejamento específico do Oracle e evidência de compatibilidade.","reviewLessons":[22,30,31]},{"id":"q3","prompt":"Há uma exportação lógica válida e um relatório de RMAN VALIDATE. O requisito inclui voltar ao SCN anterior a uma operação. O projeto já provou esse requisito?","options":["Não; precisa do ensaio de recuperação por ponto com cadeia e destino apropriados, seguido de consultas de conferência.","Sim, qualquer dump inclui todos os futuros SCNs.","Sim, VALIDATE abre o banco recuperado automaticamente.","Não, porque Oracle não permite recuperar um ponto."],"answer":0,"explanation":"Exportação, validação de backup e PITR são etapas/capacidades distintas. O alvo precisa ser demonstrado no estado recuperado.","reviewLessons":[31,32,33]}]}},"postgresql":{"courseId":"postgresql","combos":[{"id":"combo-1","title":"Pedidos e relatório sem distorção","scenario":"Um serviço PostgreSQL cadastra pedidos e itens, devolve o resultado das escritas e lista clientes com receita, inclusive os que ainda não têm pedidos.","requiredLessons":[3,4,6,7,8,9],"skills":["Constraints e RETURNING","Cardinalidade","CTE e existência"],"questions":[{"id":"q1","prompt":"O INSERT de item precisa rejeitar quantidade ausente ou não positiva e devolver o ID criado. Qual combinação atende?","options":["Apenas CHECK, presumindo que ele rejeita NULL em todo caso.","SELECT do maior ID antes de inserir, sem constraint.","NOT NULL e CHECK(quantidade>0), com RETURNING id na escrita.","Um alias quantidade_valida, que passa a validar o domínio."],"answer":2,"explanation":"A obrigatoriedade e o intervalo são regras distintas. RETURNING associa o resultado à própria escrita, sem disputa pelo maior ID.","reviewLessons":[3,4]},{"id":"q2","prompt":"A junção cliente→pedido→item repete o saldo cadastral do cliente por item. O relatório precisa de receita dos itens e incluir cliente sem venda. Qual caminho é correto?","options":["Somar o saldo repetido e aplicar DISTINCT apenas no nome.","Usar INNER JOIN e afirmar que todos os clientes continuam presentes.","Multiplicar qualquer medida pelo número de linhas da junção.","Definir a granularidade das medidas, agregar os itens no nível adequado e preservar clientes com LEFT JOIN/COALESCE quando necessário."],"answer":3,"explanation":"O efeito da cardinalidade precisa ser previsto antes da soma. Preservar o pai e definir a unidade da receita resolve perguntas diferentes do relatório.","reviewLessons":[6,7]},{"id":"q3","prompt":"Uma CTE reúne pedidos válidos; a tela precisa de clientes que não tenham nenhum desses pedidos. Como expressar a ausência sem multiplicar clientes?","options":["Usar NOT EXISTS correlacionado à identidade do cliente sobre a CTE.","Usar EXISTS sem referência ao cliente externo.","Comparar o nome da CTE com NULL.","Transformar a CTE em texto e usar LIKE no ID."],"answer":0,"explanation":"A CTE dá nome ao conjunto válido; a correlação faz a pergunta para cada cliente. Sem ela, o teste vira uma condição global.","reviewLessons":[8,9]}]},{"id":"combo-2","title":"Concorrência e investigação de consulta","scenario":"Reservas de estoque disputam a mesma linha. Um relatório apresenta acumulados e a equipe avalia um índice para a busca frequente.","requiredLessons":[10,13,14,15,16,18],"skills":["Atomicidade e locks","MVCC e janelas","EXPLAIN com evidências"],"questions":[{"id":"q1","prompt":"Uma reserva bloqueia o estoque e faz duas alterações obrigatórias. Qual limite evita liberar o lock antes de registrar a reserva?","options":["Confirmar logo após SELECT FOR UPDATE e depois gravar a reserva em outra transação.","Manter leitura bloqueante e efeitos na mesma transação, com commit ou rollback da unidade.","Usar tabela temporária distinta em cada sessão e afirmar que ambas disputam a mesma linha.","Trocar o lock por ORDER BY e dispensar a transação."],"answer":1,"explanation":"FOR UPDATE protege dentro de seu limite transacional. Separar os efeitos abre uma janela que pode invalidar a decisão de negócio.","reviewLessons":[13,15]},{"id":"q2","prompt":"Um relatório usa janela acumulada e uma transação de leitura com snapshot. Novas vendas surgem em outra sessão. O que deve ser definido para um resultado interpretável?","options":["Apenas o nome da coluna acumulado.","Que toda janela mostra obrigatoriamente escritas futuras.","O ponto de visibilidade da transação e a ordem/frame da janela, sem supor que a janela cria um snapshot por si só.","Que MVCC elimina qualquer necessidade de ordenar valores empatados."],"answer":2,"explanation":"MVCC governa a visibilidade; a janela governa o cálculo entre linhas visíveis. São contratos complementares.","reviewLessons":[10,14]},{"id":"q3","prompt":"EXPLAIN ANALYZE de uma consulta com índice mostrou tempo menor numa execução isolada. O que sustenta uma conclusão de ganho?","options":["Somente o nome B-tree no plano.","Um custo estimado tratado como milissegundos exatos.","Rodar EXPLAIN ANALYZE em qualquer escrita real sem avaliar seus efeitos.","Resultados equivalentes, carga e distribuição representativas, repetições comparáveis e atenção ao fato de ANALYZE executar a consulta."],"answer":3,"explanation":"O índice é uma hipótese de acesso; o ensaio precisa medir o mesmo trabalho. ANALYZE executa a instrução e exige cuidado com operações que modificam dados.","reviewLessons":[16,18]}]},{"id":"combo-3","title":"Contrato de documento e isolamento entre clientes","scenario":"O catálogo possui JSONB e busca textual. Uma API aplica regras em PL/pgSQL, audita mudanças e precisa impedir que um tenant leia os registros de outro.","requiredLessons":[19,20,23,24,26,27],"skills":["JSONB e busca","Auditoria transacional","RLS e binding"],"questions":[{"id":"q1","prompt":"O documento JSONB possui título textual e campos opcionais; a busca exige termos normalizados. Qual desenho combina representação e acesso sem supor que JSONB já é um motor de busca?","options":["Validar o contrato dos campos e criar a representação/configuração de busca textual e seu índice conforme a consulta.","Usar qualquer índice JSONB e prometer a mesma semântica de full-text.","Converter todos os campos ausentes em zero, inclusive título.","Guardar um documento sem regras e deixar o índice validar qualquer significado."],"answer":0,"explanation":"JSONB organiza documentos; busca textual tem configuração, operadores e estratégia próprios. Contrato do dado e acesso precisam ser projetados juntos.","reviewLessons":[19,20]},{"id":"q2","prompt":"Uma função modifica preço e o trigger grava auditoria; depois a unidade sofre rollback. Qual resultado corresponde a auditoria transacional normal?","options":["O trigger confirma sua própria linha automaticamente em toda execução.","A mudança de preço e a linha de auditoria da mesma transação são desfeitas.","Somente a auditoria permanece, sem regra adicional.","A função deixa de usar transação por estar escrita em PL/pgSQL."],"answer":1,"explanation":"Função e trigger participam do contexto transacional do chamador. Auditoria independente ou externa seria outro desenho, com outros requisitos.","reviewLessons":[23,24]},{"id":"q3","prompt":"A API concatena o tenant enviado pelo usuário num SQL e acredita que ter RLS basta. Qual fronteira precisa ser corrigida?","options":["Aceitar qualquer tenant do corpo e confiar no nome da tabela.","Usar o proprietário com poderes de bypass para provar o isolamento de todos os consumidores.","Usar contexto de tenant confiável e vincular valores, verificando a política sob uma role que não a contorne.","Remover a política porque placeholders substituem autorização."],"answer":2,"explanation":"Binding protege a estrutura SQL, mas não prova autorização. RLS também depende de role, contexto e política corretos.","reviewLessons":[26,27]}]},{"id":"combo-4","title":"Mudança de esquema e recuperação por ponto","scenario":"O volume cresceu e há partições por data, migrações em etapas e transações longas. O serviço precisa provar recuperação e limitar operações lentas.","requiredLessons":[28,29,30,31,32,35],"skills":["Particionamento e compatibilidade","Manutenção","Dump e PITR"],"questions":[{"id":"q1","prompt":"Uma migração adiciona nova restrição numa tabela particionada com dados antigos. O que precisa ser verificado antes de restringir consumidores?","options":["Que o nome da partição contém o ano atual.","Que ADD CONSTRAINT torna qualquer histórico válido por definição.","Que remover a coluna antiga primeiro evita todo bloqueio.","Cobertura das partições e dados existentes, compatibilidade das etapas e validação da regra antes da contração."],"answer":3,"explanation":"Particionamento não substitui integridade nem planejamento de evolução. A migração deve considerar todas as linhas e versões que ainda usam o contrato anterior.","reviewLessons":[28,30]},{"id":"q2","prompt":"Uma transação de leitura fica aberta por horas e o banco acumula versões antigas. Qual ação trata a causa sem matar qualquer processo indiscriminadamente?","options":["Identificar a transação e seu uso, limitar duração com timeouts adequados e revisar a interação com VACUUM.","Apenas criar mais índices para apagar versões antigas.","Desligar VACUUM permanentemente.","Supor que cancelar uma consulta sempre encerra toda transação automaticamente."],"answer":0,"explanation":"Transações antigas podem reter versões necessárias ao snapshot. Diagnóstico e limites de sessão/transação precisam ser coerentes com o fluxo da aplicação.","reviewLessons":[29,35]},{"id":"q3","prompt":"O dump foi restaurado com sucesso, mas o requisito é voltar a um instante entre backups. O que ainda é necessário?","options":["Afirmar que qualquer pg_dump já contém todos os WAL futuros.","Um procedimento PITR com backup-base apropriado, WAL arquivado preservado e alvo de recuperação efetivamente testado.","Usar uma réplica sem retenção como cópia histórica garantida.","Trocar a extensão do dump para wal."],"answer":1,"explanation":"Restauração lógica e recuperação por ponto têm requisitos e alcances diferentes. O alvo recuperado precisa ser demonstrado, não inferido do comando de backup.","reviewLessons":[31,32]}]}],"finalProject":{"id":"final","title":"Serviço de pedidos com isolamento e recuperação","scenario":"Entregue o banco PostgreSQL de um serviço de pedidos para dois tenants fictícios. O cliente pode ser local; a API deve documentar quem pode executar cada operação e como o serviço se recupera.","requirements":["Integridade de pedidos: chaves, nulabilidade, quantidades e valores válidos; totais e estados têm regras documentadas.","Reserva concorrente: duas sessões disputam estoque sem permitir saldo negativo ou pedido parcialmente confirmado.","Consultas justificadas: relatório sem duplicação de medidas, janela com frame e busca/documentos com contrato explícito.","Isolamento e parâmetros: roles limitadas, RLS verificada para dois tenants e valores vinculados pela API do cliente.","Evolução e observação: migration compatível, índice justificado, diagnóstico de bloqueio e limites de duração/conexão.","Recuperação comprovada: dump restaurado e conferido; PITR/replicação têm requisitos e estado de ensaio explicitamente registrados."],"deliverables":["Schema, migrations, fixture de dois tenants e dicionário de regras.","Cliente parametrizado e operações de reserva/cancelamento.","Testes de concorrência, autorização e relatórios com resultados de referência.","Runbook de observação e restore, com evidência do destino e cenários ainda não executados."],"rubric":[{"id":"r1","title":"Integridade de pedidos","description":"Integridade de pedidos: chaves, nulabilidade, quantidades e valores válidos; totais e estados têm regras documentadas.","reviewLessons":[3,4,6,7]},{"id":"r2","title":"Reserva concorrente","description":"Reserva concorrente: duas sessões disputam estoque sem permitir saldo negativo ou pedido parcialmente confirmado.","reviewLessons":[13,14,15]},{"id":"r3","title":"Consultas justificadas","description":"Consultas justificadas: relatório sem duplicação de medidas, janela com frame e busca/documentos com contrato explícito.","reviewLessons":[10,18,19,20]},{"id":"r4","title":"Isolamento e parâmetros","description":"Isolamento e parâmetros: roles limitadas, RLS verificada para dois tenants e valores vinculados pela API do cliente.","reviewLessons":[25,26,27]},{"id":"r5","title":"Evolução e observação","description":"Evolução e observação: migration compatível, índice justificado, diagnóstico de bloqueio e limites de duração/conexão.","reviewLessons":[16,29,30,34,35]},{"id":"r6","title":"Recuperação comprovada","description":"Recuperação comprovada: dump restaurado e conferido; PITR/replicação têm requisitos e estado de ensaio explicitamente registrados.","reviewLessons":[31,32,33,36]}],"acceptance":[{"title":"Última unidade em disputa","setup":"Estoque 1 e dois clientes em sessões distintas.","input":"Reservar simultaneamente uma unidade para pedidos diferentes.","expected":"No máximo uma reserva confirma; a outra recebe recusa ou conflito tratado, sem saldo negativo nem pedido parcial.","reviewLessons":[13,14,15]},{"title":"Tenant incorreto","setup":"Dados diferentes para tenants A e B, role de aplicação sem bypass e contexto confiável.","input":"Consultar como A e tentar alcançar explicitamente o ID pertencente a B.","expected":"B não é devolvido a A; a recusa não depende só de filtro montado na interface.","reviewLessons":[25,26,27]},{"title":"Dump e destino novo","setup":"Fixture conhecida, arquivo pg_dump e banco de destino vazio autorizado.","input":"Restaurar com ferramentas compatíveis e conferir contagens, chaves e resultados de negócio.","expected":"Destino abre e preserva dados/regras; logs e resultados são registrados. PITR só é marcado ensaiado após recuperação real de seu alvo.","reviewLessons":[30,31,32]}],"questions":[{"id":"q1","prompt":"A aplicação usa parâmetros, mas executa como role que contorna RLS. O isolamento entre tenants foi provado?","options":["Sim, placeholders são políticas de acesso.","Sim, o proprietário sempre representa qualquer role limitada.","Não; precisa testar autorização com a identidade e o contexto reais do consumidor.","Não, porque RLS impede qualquer parâmetro."],"answer":2,"explanation":"Estrutura SQL segura e autorização são fronteiras distintas. A identidade usada no ensaio faz parte da evidência.","reviewLessons":[25,26,27]},{"id":"q2","prompt":"A reserva tem lock correto, mas mantém transação aberta enquanto aguarda confirmação humana. Qual ponto revisar?","options":["Aumentar indefinidamente todos os timeouts.","Abrir mais sessões para manter os mesmos locks.","Trocar o nome do trigger.","Encurtar o limite transacional e revalidar a decisão ao escrever, com timeouts e tratamento de conflito."],"answer":3,"explanation":"Locks necessários não justificam segurar recursos durante interação longa. A decisão deve ser revalidada dentro de uma unidade curta.","reviewLessons":[13,15,35]},{"id":"q3","prompt":"A réplica recebe escritas e exclusões, mas não há cópia histórica restaurada. Qual conclusão operacional é correta?","options":["Replicação observada não prova recuperação de exclusão acidental; precisa de backup e ensaio do ponto recuperado.","A réplica conserva todas as versões para sempre automaticamente.","Receber uma linha prova qualquer PITR.","O arquivo de configuração da réplica substitui o dump."],"answer":0,"explanation":"Disponibilidade, propagação e recuperação histórica possuem garantias diferentes.","reviewLessons":[31,32,33]}]}},"python":{"courseId":"python","combos":[{"title":"Importação de pedidos sem estado acidental","scenario":"Um script lê pedidos de um arquivo JSON UTF-8, agrupa por código e calcula totais. Registros inválidos devem ser recusados sem modificar pedidos já carregados nem compartilhar listas entre chamadas.","requiredLessons":[2,4,5,6,8,9],"skills":["Mutabilidade","Contratos","JSON e exceções"],"questions":[{"prompt":"A função usa def carregar(registro, erros=[]), acrescenta uma mensagem à lista e é chamada para dois arquivos. O segundo recebe erros do primeiro. Qual ajuste preserva independência por chamada?","options":["Usar erros=None, criar a lista dentro da função quando necessário e retornar explicitamente o resultado da importação.","Manter a lista padrão e chamar clear em qualquer momento, mesmo com consumidores usando-a.","Trocar a lista por variável global.","Ignorar erros do segundo arquivo para que a saída pareça limpa."],"answer":0,"explanation":"O argumento padrão mutável é criado uma vez e reutilizado. O contrato precisa distinguir uma lista fornecida deliberadamente de uma lista nova por execução.","reviewLessons":[4,6,8],"id":"q1"},{"prompt":"copia = pedidos[:] copia a lista, mas copia[0][\"status\"] = \"pago\" também muda pedidos[0]. Como produzir uma alteração candidata independente para esse registro simples?","options":["Confiar que qualquer slice realiza cópia profunda de todo objeto.","Criar novos dicionários para os registros que serão alterados e só substituir o estado após validar os dados.","Alterar a entrada original e capturar uma exceção depois.","Converter a lista em string e considerar o objeto validado."],"answer":1,"explanation":"A cópia da lista é rasa: os dicionários continuam compartilhados. Uma mudança candidata deve copiar os níveis mutáveis relevantes antes do efeito.","reviewLessons":[4,5,6],"id":"q2"},{"prompt":"Um arquivo contém JSON sintaticamente inválido; outro nem pode ser aberto. Qual tratamento mantém contexto útil sem esconder defeitos inesperados?","options":["Capturar BaseException e retornar lista vazia para qualquer problema.","Considerar um arquivo ausente como pedido confirmado.","Tratar as falhas esperadas de leitura e de parsing separadamente, associar o caminho ao diagnóstico e preservar a causa quando traduzir o erro.","Imprimir sucesso no finally independentemente do resultado."],"answer":2,"explanation":"Falha de acesso e conteúdo inválido têm causas e ações diferentes. Lista vazia não deve fingir que a importação funcionou.","reviewLessons":[6,8,9],"id":"q3"}],"id":"combo-1"},{"title":"Relatório incremental com recursos fechados","scenario":"Um relatório percorre milhares de movimentos, valida cada registro e produz uma soma por categoria. O consumidor pode encerrar cedo e os testes devem conferir resultado, erro e liberação do arquivo.","requiredLessons":[10,11,13,15,16,18],"skills":["Invariantes","Generators","Recursos e testes"],"questions":[{"prompt":"A função recebe movimentos: Iterable[Movimento]. Isso garante em runtime que cada quantidade seja positiva?","options":["Sim, Python rejeita automaticamente qualquer quantidade negativa ao chamar a função.","Sim, Iterable valida todas as linhas antes de iterar.","Não, porque anotações obrigam usar somente listas.","Não; type hints descrevem o contrato, e os dados ainda precisam de validação de domínio na fronteira ou no modelo."],"answer":3,"explanation":"Tipagem estática e verificação de valores cumprem papéis diferentes. O modelo deve rejeitar estados inválidos independentemente da origem dos dados.","reviewLessons":[10,11,16],"id":"q1"},{"prompt":"Um generator mantém um arquivo aberto e a tela só consome as cinco primeiras linhas. Qual desenho permite encerrar esse recurso de forma previsível?","options":["Definir quem possui e fecha o recurso, usar contexto de duração delimitada e encerrar explicitamente o iterador quando o consumo for interrompido.","Esperar que a coleta de lixo ocorra imediatamente em qualquer implementação.","Carregar todo o arquivo para evitar pensar no ciclo de vida.","Deixar o arquivo aberto porque generators não usam recursos."],"answer":0,"explanation":"Processamento incremental não elimina a posse do recurso. Interrupção do consumidor precisa fazer parte do protocolo de fechamento.","reviewLessons":[13,15,18],"id":"q2"},{"prompt":"O teste lê um arquivo do computador do autor e passa, mas falha em outra máquina. Como transformar esse caso em regressão reproduzível?","options":["Usar o caminho absoluto do autor em todas as máquinas.","Criar uma fixture pequena num diretório temporário, escrever o conteúdo conhecido e verificar a soma e o erro esperado sem depender de arquivos externos.","Ignorar a falha em outro sistema.","Testar somente se não ocorreu SyntaxError."],"answer":1,"explanation":"O ensaio deve controlar sua entrada e seus recursos. Uma fixture mínima permite observar a regra e manter o contraexemplo encontrado.","reviewLessons":[15,16,18],"id":"q3"}],"id":"combo-2"},{"title":"CLI e cliente HTTP com confirmação SQLite","scenario":"Uma ferramenta recebe argumentos, consulta um serviço HTTP local e registra uma confirmação no SQLite. Resposta 404, JSON inválido e falha de escrita devem produzir resultados distintos e não deixar meia operação.","requiredLessons":[20,21,22,23,24,27],"skills":["CLI","HTTP","SQLite e composição"],"questions":[{"prompt":"O servidor respondeu HTTP 404 com corpo JSON válido. A CLI pode tratá-lo como sucesso só porque json.loads funcionou?","options":["Sim, JSON válido implica operação bem-sucedida.","Sim, qualquer resposta HTTP confirma o domínio.","Não; deve interpretar o status e o contrato do corpo antes de registrar a confirmação e escolher o código de saída apropriado.","Não, porque 404 nunca pode ter corpo."],"answer":2,"explanation":"Transporte, status e conteúdo são camadas distintas. Parsing bem-sucedido não autoriza efeitos no banco.","reviewLessons":[20,22,24],"id":"q1"},{"prompt":"O nome recebido contém uma aspa e texto semelhante a SQL. Qual construção conserva o valor como dado ao consultar SQLite?","options":["Concatenar o nome entre aspas e confiar no JSON.","Usar f-string para qualquer nome e chamar commit logo depois.","Remover todas as aspas e alterar o nome silenciosamente.","Usar placeholder e parâmetros do driver, mantendo o valor separado da estrutura do comando."],"answer":3,"explanation":"O binding representa valores sem incorporá-los à sintaxe. Transação não corrige uma consulta construída por concatenação.","reviewLessons":[22,23,24],"id":"q2"},{"prompt":"Duas tarefas de um TaskGroup dependem da importação; uma falha antes da confirmação no banco. O que deve ser coordenado?","options":["O ciclo de vida das tarefas e o limite transacional, de modo que uma falha não seja ignorada nem confirme parte da unidade de negócio.","Criar tarefas sem aguardar e imprimir sucesso no fim da função principal.","Presumir que TaskGroup torna SQLite e HTTP uma única transação distribuída.","Confirmar cada linha antes de validar as respostas restantes."],"answer":0,"explanation":"Concorrência estruturada ajuda a observar término e falha; atomicidade dos dados continua exigindo uma transação e um protocolo para efeitos externos.","reviewLessons":[22,24,27],"id":"q3"}],"id":"combo-3"},{"title":"API, fila limitada e recuperação de operação","scenario":"A mesma regra passa a servir CLI e uma API WSGI didática. Trabalho externo entra numa fila limitada; duplicatas, autorização, tempo de espera e medição precisam ter contratos explícitos.","requiredLessons":[24,28,29,30,31,35],"skills":["Fronteiras","Backpressure","Idempotência e diagnóstico"],"questions":[{"prompt":"A requisição traz usuario_id no JSON e solicita um registro de outra pessoa. Qual identidade deve orientar a autorização antes de alterar dados?","options":["Sempre o usuario_id do JSON, porque o cliente conhece sua conta.","A identidade autenticada pelo mecanismo de acesso, confrontada com o dono real do recurso; o corpo não pode escolher quem está autenticado.","O primeiro usuário encontrado no banco.","A identidade de qualquer requisição anterior no processo."],"answer":1,"explanation":"Dados externos não definem a identidade verificada. A decisão de autorização precisa ocorrer sobre o recurso solicitado antes dos efeitos.","reviewLessons":[29,30],"id":"q1"},{"prompt":"O produtor gera mil tarefas por segundo e o consumidor trata cem. A fila cresce sem limite. Qual correção combina desempenho e encerramento?","options":["Adicionar uma lista global sem limite para não perder o retorno do produtor.","Diminuir o intervalo de coleta de lixo e ignorar a taxa de entrada.","Definir capacidade e política de espera/recusa, propagar cancelamento e medir tamanho da fila e latência sob carga controlada.","Criar mais tarefas ilimitadamente, sem esperar seu término."],"answer":2,"explanation":"A diferença sustentada de taxas exige pressão de fluxo ou recusa definida. Medição e limites de ciclo de vida evitam retenção sem controle.","reviewLessons":[28,31],"id":"q2"},{"prompt":"A confirmação SQLite terminou, mas a conexão HTTP caiu antes da resposta. Como a próxima tentativa reconhece o efeito anterior após reiniciar o processo?","options":["Guardar a chave apenas num set em memória e reiniciar para restaurá-la.","Gerar chave diferente a cada retry.","Presumir que falha de resposta significa rollback.","Consultar uma chave idempotente persistida atomicamente com a confirmação e conferir se o conteúdo da repetição corresponde à operação original."],"answer":3,"explanation":"O resultado é incerto para o cliente, mas o banco pode registrar operação e efeito juntos. Memória do processo não garante reconhecimento após reinício.","reviewLessons":[24,28,35],"id":"q3"}],"id":"combo-4"}],"finalProject":{"id":"final","title":"Central de empréstimos de ferramentas em Python","scenario":"Crie uma aplicação local para emprestar e devolver ferramentas, com CLI e API didática usando a mesma regra. Preserve histórico, evite baixa duplicada e demonstre recuperação de uma cópia SQLite.","requirements":["Validar identificadores, quantidades e transições por funções/classes com invariantes, sem confiar somente em type hints.","Usar SQLite com queries parametrizadas, referências e confirmação atômica de empréstimo/estoque/operação.","Expor os mesmos casos de uso por argparse e HTTP local, traduzindo falhas em códigos de saída ou status definidos.","Fechar arquivos e conexões, limitar a fila de tarefas e propagar timeout/cancelamento até o trabalho cooperativo.","Testar fronteiras, duplicação, autorização e falha intermediária com fixtures isoladas e dependências controladas.","Fornecer pyproject, ambiente reproduzível, logs sem segredos, medições justificadas e backup realmente reaberto."],"deliverables":["Pacote Python com CLI, API e camada de persistência separadas.","Suíte de testes com fixtures temporárias e comandos de execução.","README de ambiente, contratos e decisões de concorrência.","Relatório de backup/restauração e limites operacionais observados."],"rubric":[{"id":"r1","title":"Modelo e entrada","description":"Validar identificadores, quantidades e transições por funções/classes com invariantes, sem confiar somente em type hints.","reviewLessons":[6,10,11,30]},{"id":"r2","title":"Persistência transacional","description":"Usar SQLite com queries parametrizadas, referências e confirmação atômica de empréstimo/estoque/operação.","reviewLessons":[23,24,35]},{"id":"r3","title":"Fronteiras reutilizáveis","description":"Expor os mesmos casos de uso por argparse e HTTP local, traduzindo falhas em códigos de saída ou status definidos.","reviewLessons":[20,22,29,34]},{"id":"r4","title":"Recursos e concorrência","description":"Fechar arquivos e conexões, limitar a fila de tarefas e propagar timeout/cancelamento até o trabalho cooperativo.","reviewLessons":[15,25,27,28]},{"id":"r5","title":"Testes observáveis","description":"Testar fronteiras, duplicação, autorização e falha intermediária com fixtures isoladas e dependências controladas.","reviewLessons":[16,17,18,30,35]},{"id":"r6","title":"Entrega e recuperação","description":"Fornecer pyproject, ambiente reproduzível, logs sem segredos, medições justificadas e backup realmente reaberto.","reviewLessons":[19,21,31,32,36]}],"acceptance":[{"title":"Empréstimo confirmado","setup":"Ferramenta F possui 4 unidades disponíveis e operação emp-1 é inédita.","input":"Emprestar 2 unidades com emp-1.","expected":"Disponibilidade 2, um empréstimo e resultado da operação persistidos juntos.","reviewLessons":[10,23,24,35]},{"title":"Falha sem efeito parcial","setup":"Ferramenta F possui 4 unidades; erro injetado após a baixa e antes de inserir histórico.","input":"Executar empréstimo e consultar a base depois do erro.","expected":"Disponibilidade permanece 4 e não existe empréstimo confirmado pela tentativa.","reviewLessons":[16,18,24]},{"title":"Repetição e reabertura","setup":"emp-1 já confirmou 2 unidades; copie a base por procedimento consistente e reabra o destino.","input":"Repetir emp-1 com mesmo conteúdo no estado recuperado.","expected":"Nenhuma segunda baixa; destino contém o empréstimo e os invariantes continuam válidos.","reviewLessons":[23,24,35,36]}],"questions":[{"prompt":"O projeto usa annotations, mas aceita quantidade negativa na API. Qual camada de garantia falta?","options":["Validação de valores e invariantes antes da transação, compartilhada pelos casos de uso.","Mais imports de typing apenas.","Converter toda quantidade em string.","Adicionar sleep antes do commit."],"answer":0,"explanation":"Type hints não tornam valores de entrada válidos automaticamente; as fronteiras devem aplicar o contrato.","reviewLessons":[10,11,30,34],"id":"q1"},{"prompt":"Os testes substituem o relógio, mas ainda usam uma API externa aleatória. O resultado é totalmente determinístico?","options":["Sim, controlar uma dependência controla todas.","Não; a fronteira HTTP também precisa de respostas controladas para os cenários testados.","Sim, rede pública é sempre reproduzível.","Não, porque não se pode testar HTTP."],"answer":1,"explanation":"Cada fonte de variação relevante deve ter contrato e controle no teste.","reviewLessons":[17,18,22],"id":"q2"},{"prompt":"Um backup foi criado, mas as conexões do destino nunca foram abertas. Qual critério do projeto ainda não foi demonstrado?","options":["Que o arquivo possui algum nome.","Que a CLI aceita --help.","Recuperação dos dados e invariantes na cópia, com verificação e duração registradas.","Que Python permite imports."],"answer":2,"explanation":"A comprovação exige leitura do estado recuperado, não só um arquivo produzido.","reviewLessons":[23,24,36],"id":"q3"}]}},"redis":{"courseId":"redis","combos":[{"id":"combo-1","title":"Perfil, participação e cache","scenario":"Um painel guarda perfil em hash, participação única em set e um resumo em cache com validade. O número de acessos precisa crescer sem atualização perdida.","requiredLessons":[2,4,5,6,7,9],"skills":["Modelo por chave","Contagem e participação","TTL e invalidação"],"questions":[{"id":"q1","options":["Usar INCR para acessos e um set de IDs para a participação única, conforme cada pergunta.","Usar SADD no nome de todos os acessos e esperar contagem de visitas repetidas.","Manter GET/SET e adicionar um TTL depois de cada leitura.","Trocar a chave por um hash e continuar com leitura/regravação sem coordenação."],"answer":0,"prompt":"Dois clientes leem o contador 8 e ambos gravam 9. Qual mudança resolve a atualização perdida sem confundir acessos com participantes únicos?","explanation":"Contagem de eventos e cardinalidade de membros são fatos diferentes. A operação de incremento precisa ocorrer atomicamente no servidor.","reviewLessons":[5,7,9]},{"id":"q2","options":["O nome antigo prova que HSET nunca executa.","TTL não sincroniza imediatamente; aplique a política de invalidação/atualização e trate miss consultando a fonte definida.","TTL garante que todo dado será sempre o mais novo até expirar.","Um GET ausente confirma automaticamente que o usuário foi excluído da origem."],"answer":1,"prompt":"O perfil mudou na origem, mas o cache ainda mostra o nome antigo antes de seu TTL. Qual conclusão e ação correspondem ao padrão cache-aside?","explanation":"Prazo de validade, atualização e inexistência no domínio têm significados distintos. Defina o atraso permitido e a recuperação de um miss.","reviewLessons":[4,6,7]},{"id":"q3","options":["O prazo sempre aumenta exatamente um segundo.","SET simples conserva qualquer TTL em todas as circunstâncias.","O TTL pode ser removido; escolha explicitamente EX/PX ou KEEPTTL conforme a intenção e confira a validade depois.","A chave se transforma num set por causa da palavra SET."],"answer":2,"prompt":"Uma atualização usa SET simples numa chave que possuía prazo. Que efeito no ciclo de vida precisa ser verificado?","explanation":"Escrever o valor e manter validade não são uma suposição segura sem opções apropriadas. Teste os códigos de TTL e o comportamento do cache.","reviewLessons":[2,4,6]}]},{"id":"combo-2","title":"Pontuação e reserva de operação","scenario":"Uma aplicação soma pontos e limita requisições. Ela deve distinguir operação nova, repetição e conflito, sem atribuir rollback geral a qualquer bloco Redis.","requiredLessons":[10,13,14,16,17,18],"skills":["Sorted set","Atomicidade e limites","Idempotência e janela"],"questions":[{"id":"q1","options":["Sim, qualquer erro de EXEC reverte tudo como uma transação SQL.","Sim, um score numérico obriga rollback de toda a instância.","Não, porque MULTI nunca executa qualquer comando.","Não; precisa interpretar as respostas e o contrato de erro, pois Redis não fornece rollback geral de comandos já executados."],"answer":3,"prompt":"Um bloco MULTI/EXEC altera uma chave e depois encontra erro de tipo em outro comando. O cliente pode assumir que a alteração anterior foi desfeita?","explanation":"Execução sem intercalação não significa desfazer geral após erro. Planeje tipos, validações e as respostas possíveis de cada operação.","reviewLessons":[10,13,16]},{"id":"q2","options":["Executar a decisão de incrementar e definir o prazo apropriado numa operação/script atômico com argumentos validados.","Usar um sorted set sem regra de prazo e declarar o problema resolvido.","Fazer WATCH numa conexão e EXEC em outra.","Esperar que o cliente retorne para sempre antes de tratar o estado."],"answer":0,"prompt":"O limitador faz INCR e só depois envia PEXPIRE numa segunda requisição; o cliente cai entre elas. Qual desenho reduz a janela de contador sem expiração?","explanation":"A sequência separada permite falha entre efeitos. A unidade atômica deve validar antes de escrever e ainda reconhecer seus limites de erro e persistência.","reviewLessons":[14,16,17]},{"id":"q3","options":["A operação será lembrada para sempre porque seu nome é único na aplicação.","A proteção é limitada à retenção; após o prazo, a mesma identidade pode ser tratada como nova se não existir outra fonte de decisão.","O ranking recompõe automaticamente todas as identidades expiradas.","TTL transforma a deduplicação em commit distribuído entre sistemas."],"answer":1,"prompt":"A deduplicação guarda a operação por 120 segundos e devolve resultado salvo. Uma repetição chega depois de a chave expirar. Qual contrato precisa estar explícito?","explanation":"Identidade precisa de retenção compatível com o protocolo de retries. Não prometa exatamente uma vez indefinidamente por guardar uma chave temporária.","reviewLessons":[10,17,18]}]},{"id":"combo-3","title":"Eventos, reentrega e cópia recuperada","scenario":"Uma solicitação entra num Stream, é processada por um grupo e também gera aviso em Pub/Sub. Um worker pode cair depois do efeito e antes do reconhecimento.","requiredLessons":[19,20,21,22,24,27],"skills":["Stream e grupo","ACK e reclaim","Fonte recuperável"],"questions":[{"id":"q1","options":["Afirmar que XAUTOCLAIM cancela automaticamente qualquer efeito do worker antigo.","Executar o efeito novamente sempre, pois XACK desliga duplicações.","Reconhecer a operação já aplicada e evitar duplicar o efeito na reentrega, respeitando o protocolo do destino.","Apagar toda a origem antes de conferir a operação."],"answer":2,"prompt":"O worker aplicou o efeito e caiu antes de XACK. Outro worker reivindicou a pendência. Qual comportamento deve ser suportado?","explanation":"A pendência pode ser reentregue. Posse de mensagem e conclusão do efeito são estados diferentes; o destino precisa de idempotência/coordenação adequadas.","reviewLessons":[20,21,24]},{"id":"q2","options":["Usar GET no nome do canal para recuperar todo o histórico.","Assumir que PUBLISH conserva cada mensagem até todos se reconectarem.","Considerar a contagem de assinantes uma prova de efeito concluído.","Reconsultar a fonte de estado ou um fluxo retido com cursor/protocolo apropriado, usando o sinal apenas como aviso."],"answer":3,"prompt":"O cliente perdeu a conexão Pub/Sub durante uma atualização. Como o painel pode recuperar seu estado sem depender de replay inexistente no canal?","explanation":"Pub/Sub é efêmero e não mantém replay para o assinante ausente. A retomada precisa de fonte e retenção próprias.","reviewLessons":[19,22,24]},{"id":"q3","options":["Prova a recuperação local daquele estado; não prova retenção de todos os eventos futuros nem tolerância à perda da máquina.","Prova exatamente uma vez para qualquer efeito HTTP externo.","Prova replicação geográfica mesmo sem outro host.","Não prova nada, porque consultar o destino é irrelevante."],"answer":0,"prompt":"Um RDB foi aberto num processo isolado e o marcador do destino confere. O que essa evidência prova e o que ainda não prova?","explanation":"O alcance do teste precisa corresponder à falha ensaiada. Confira também os eventos e cursores esperados no ponto da cópia.","reviewLessons":[19,24,27]}]},{"id":"combo-4","title":"Acesso, manutenção e topologia","scenario":"O serviço cresce. Uma conta de leitura acessa prefixos próprios, a manutenção percorre chaves e a arquitetura considera réplicas e distribuição por slots.","requiredLessons":[28,29,32,33,34,35],"skills":["ACL e transporte","Iteração e memória","Replicação e slots"],"questions":[{"id":"q1","options":["Sim, uma senha automaticamente limita comandos e cifra toda rede.","Não; confirme comandos/chaves autorizados, operações recusadas e proteção do transporte como verificações separadas.","Sim, o prefixo da chave autentica o usuário.","Não, porque ACL não permite limitar leitura."],"answer":1,"prompt":"A conta usa senha, mas pode executar CONFIG e ler qualquer prefixo; o teste não verificou TLS. O requisito de acesso restrito foi demonstrado?","explanation":"Identidade, autorização e transporte cobrem fronteiras diferentes. Testar só uma leitura permitida não demonstra menor privilégio.","reviewLessons":[28,29]},{"id":"q2","options":["Encerrar no primeiro lote vazio e contar cada repetição como chave nova.","Usar COUNT como número exato de resultados obrigatórios e ignorar o cursor.","Continuar pelo cursor até zero e tratar repetição/mudança de chaves, sem assumir que TTL garante presença até o fim.","Assumir que chave com TTL nunca pode sair por pressão de memória."],"answer":2,"prompt":"SCAN devolveu zero chaves e cursor não zero durante limpeza por prefixo. Ao mesmo tempo, chaves com TTL podem sofrer eviction. Qual protocolo é coerente?","explanation":"SCAN não fornece um snapshot nem lotes uniformes. Expiração e eviction podem alterar o conjunto; a tarefa precisa tolerar a evolução observada.","reviewLessons":[32,33]},{"id":"q3","options":["A tag espalha o grupo por todos os slots e a réplica nunca fica atrasada.","Sentinel automaticamente fragmenta cada valor em todos os nós.","TTL converte a réplica em confirmação síncrona sem perda.","A tag concentra esse grupo num slot e a réplica pode observar estado anterior; nenhum desses recursos garante distribuição uniforme e leitura sempre atual."],"answer":3,"prompt":"Todas as chaves usam a tag {global} em Cluster e uma réplica assíncrona está atrasada. Qual interpretação evita duas promessas incorretas?","explanation":"Hash tags agrupam chaves e replicação assíncrona tem atraso. Escolha a unidade de atomicidade e a topologia pelo requisito medido.","reviewLessons":[34,35]}]}],"finalProject":{"id":"final","title":"Painel de atendimento com processamento recuperável","scenario":"Entregue um serviço fictício de solicitações com perfis, prioridade de atendimento, métricas e processamento de eventos. Use Redis conscientemente como estrutura de dados e fonte/cópia conforme o contrato documentado, sem confundir sinal de tela com confirmação durável de trabalho.","requirements":["Definir nomes, tipos e unidade de acesso para perfis, participação, prioridade e cache com prazos explícitos.","Aplicar operações condicionais e incrementos sem atualização perdida, com identidade/conteúdo de operação e retenção de deduplicação documentados.","Processar eventos de Stream por grupo com ACK no ponto definido, limite de tentativas, tratamento de pendências e reentrega idempotente.","Separar contas administrativas e de aplicação, demonstrando comandos/chaves permitidos e recusados e o transporte realmente testado.","Registrar métricas com intervalo, iterar manutenção por SCAN corretamente e escolher política de memória/eviction compatível com cada tipo de dado.","Gerar e reabrir uma cópia em processo isolado, conferir dados e eventos esperados e justificar limites de persistência, replicação e eventual Cluster/Sentinel."],"deliverables":["Contrato de chaves e scripts/cliente do serviço com dados fictícios e versão do Redis.","Roteiros de operação, consumidor e casos de duplicata, conflito, limite e falha.","Relatório de acesso, memória, iteração, métricas e interpretação de resultados variáveis.","Runbook de cópia e recuperação com marcador no destino, estado dos eventos, RPO/RTO e decisão de topologia."],"rubric":[{"id":"r1","title":"Modelo por estrutura","description":"Cada chave tem tipo, identidade, unidade e ciclo de vida compatíveis com as consultas.","reviewLessons":[2,4,5,6,7,8,9,10,11,12]},{"id":"r2","title":"Atomicidade e repetição","description":"A unidade da operação e sua retenção são testadas sem prometer rollback ou deduplicação ilimitada.","reviewLessons":[13,14,15,16,17,18]},{"id":"r3","title":"Processamento recuperável","description":"O protocolo distingue entrega, posse, efeito, ACK, retenção e retomada.","reviewLessons":[19,20,21,22,23,24]},{"id":"r4","title":"Acesso e evolução","description":"ACL, transporte e versões têm verificações e transição documentadas.","reviewLessons":[28,29,30]},{"id":"r5","title":"Operação observável","description":"Métricas, SCAN e memória possuem unidades e tratamento de situações não uniformes.","reviewLessons":[31,32,33]},{"id":"r6","title":"Estado recuperado e topologia","description":"O destino é aberto e conferido; réplicas, Sentinel e Cluster são descritos no escopo realmente ensaiado.","reviewLessons":[25,26,27,34,35,36]}],"acceptance":[{"title":"Operação repetida e conflito","setup":"Prepare chaves vazias próprias do laboratório e uma identidade de solicitação com conteúdo conhecido.","input":"Aplique a mesma operação duas vezes dentro da retenção e depois tente a mesma identidade com conteúdo incompatível.","expected":"O efeito válido ocorre uma vez no prazo definido; a repetição devolve a decisão anterior e o conflito é tratado explicitamente, sem alterar o estado indevidamente.","reviewLessons":[5,10,16,18]},{"title":"Queda antes do ACK","setup":"Crie Stream e grupo, consuma uma entrada e aplique um efeito identificável sem reconhecer a mensagem.","input":"Interrompa o consumidor de ensaio, reivindique a pendência após o limiar escolhido e processe a reentrega.","expected":"O efeito não é duplicado; a entrada tem conclusão/ACK conforme o protocolo e tentativas são observadas. A prova vale sob retenção e persistência ensaiadas.","reviewLessons":[19,20,21,24]},{"title":"Cópia e reabertura","setup":"Crie perfil, prioridade e eventos de referência e preserve o ponto da cópia segundo o modo escolhido.","input":"Abra a cópia em instância isolada e consulte marcadores, ranking e estados de fluxo previstos nesse ponto.","expected":"O destino contém o estado documentado e suas regras; perda possível, retenção e duração são registradas. Não se conclui alta disponibilidade a partir de uma cópia local.","reviewLessons":[25,26,27,34,35]}],"questions":[{"id":"q1","options":["Não; é necessário uma fonte/reconciliação ou retenção que preserve o trabalho devido, pois deduplicação não recria evento ausente.","Sim, a chave da operação reconstrói qualquer payload apagado.","Sim, XACK restaura automaticamente entradas aparadas.","Não, porque idempotência significa sempre duplicar."],"answer":0,"prompt":"O consumidor é idempotente, mas o Stream foi aparado antes de ele ler um evento. A deduplicação basta para recuperar o trabalho perdido?","explanation":"Retenção e repetição tratam falhas diferentes. O protocolo precisa preservar ou reconstruir o que ainda deve ser processado.","reviewLessons":[18,19,21,24]},{"id":"q2","options":["Sim, EVAL é uma transação distribuída universal.","Não; a fronteira entre sistemas exige recuperação e idempotência próprias, com estado da operação documentado.","Sim, TTL confirma e desfaz qualquer chamada externa.","Não, porque Lua não pode ler chaves."],"answer":1,"prompt":"Uma reserva foi gravada pelo script e o efeito HTTP externo falhou. O projeto pode afirmar que a atomicidade Redis desfez automaticamente todos os sistemas?","explanation":"A unidade atômica do Redis não inclui um serviço remoto. Planeje o próximo passo e a repetição sem confundir resposta local com efeito externo concluído.","reviewLessons":[13,16,18,24,36]},{"id":"q3","options":["Apenas um nome mais longo para a instância.","Nada, porque abrir um RDB prova todas as garantias de produção.","Os limites de perda, retenção e visibilidade, além da evidência positiva da cópia recuperada.","Remover os testes para não precisar de limites."],"answer":2,"prompt":"O relatório mostra backup reaberto, mas não registra configuração de persistência, prazo da deduplicação ou atraso da réplica. O que falta para avaliar as garantias?","explanation":"Recuperação e consistência têm janelas específicas. Relate o estado que foi preservado e as condições em que repetição ou leitura antiga ainda podem ocorrer.","reviewLessons":[18,25,26,27,34]}]}},"sqlite":{"courseId":"sqlite","combos":[{"id":"combo-1","title":"Estoque local com representação explícita","scenario":"Um aplicativo local recebe quantidade e preço em centavos. Os itens pertencem a categorias existentes e a baixa deve indicar se realmente encontrou quantidade suficiente.","requiredLessons":[2,4,5,6,7,9],"skills":["Afinidade e STRICT","Integridade por conexão","RETURNING e unidades"],"questions":[{"id":"q1","prompt":"A tabela normal aceita a string doze numa coluna de afinidade INTEGER. O produto exige inteiro não negativo. Qual contrato deve ser reforçado?","options":["Confiar que INTEGER em qualquer tabela rejeita todo texto.","Trocar o número por uma lista de palavras sem validação.","Remover CHECK porque STRICT valida qualquer regra de negócio.","Usar uma tabela STRICT compatível e declarar NOT NULL e CHECK para o domínio, testando a entrada."],"answer":3,"explanation":"Afinidade não é rigidez geral. STRICT trata o tipo, enquanto obrigatoriedade e intervalo ainda precisam de constraints próprias.","reviewLessons":[2,5]},{"id":"q2","prompt":"A aplicação abriu uma conexão nova e aceitou categoria inexistente, apesar da cláusula REFERENCES. O que deve fazer nessa conexão e testar?","options":["Ativar foreign_keys antes da transação e verificar a rejeição da referência inválida.","Trocar a FK por ORDER BY id.","Mudar id para TEXT para ativar referências automaticamente.","Executar RETURNING sem configurar a verificação."],"answer":0,"explanation":"A declaração da referência e a ativação por conexão precisam trabalhar juntas. Testar a tentativa inválida confirma a configuração.","reviewLessons":[4,6]},{"id":"q3","prompt":"UPDATE reduz 3 unidades apenas quando qtd>=3 e usa RETURNING. Nenhuma linha voltou. O preço é guardado em centavos inteiros. Qual interpretação é correta?","options":["A baixa ocorreu e o cliente pode cobrar três vezes um valor em reais sem converter.","A baixa não foi aplicada por ausência ou condição não atendida; o cliente deve tratar isso, mantendo a unidade monetária definida.","RETURNING vazio significa obrigatoriamente três linhas alteradas.","O preço muda de centavos para reais automaticamente ao executar UPDATE."],"answer":1,"explanation":"Escrita condicionada precisa ter seu efeito confirmado. Representação numérica não elimina o dever de explicitar unidades na aplicação.","reviewLessons":[7,9]}]},{"id":"combo-2","title":"Catálogo com análise, JSON e busca","scenario":"O catálogo exibe totais por cliente, um acumulado por movimento e busca textual em títulos. A interface lê uma view de preços e uma trigger registra mudanças efetivas.","requiredLessons":[10,13,14,15,16,17],"skills":["Granularidade e janelas","Busca com contrato","Views e auditoria"],"questions":[{"id":"q1","prompt":"O relatório precisa manter clientes sem pedidos e mostrar acumulado sem perder cada movimento. Qual combinação atende?","options":["INNER JOIN seguido de GROUP BY para garantir todas as linhas originais.","COUNT(*) sem examinar a parte nula e janela sem ordem.","LEFT JOIN com medida que trate ausência e função de janela com ordem/frame definidos para o detalhe.","LIMIT 1 por cliente para substituir o acumulado."],"answer":2,"explanation":"A junção externa preserva o pai e a janela acrescenta medida ao detalhe. Agregar em grupos altera a granularidade e não é substituto automático.","reviewLessons":[10,13]},{"id":"q2","prompt":"Uma opção de busca vem de JSON e o usuário pode digitar operadores de MATCH. Qual cuidado protege a interpretação do produto?","options":["Assumir que qualquer JSON é válido e MATCH é idêntico a LIKE.","Usar a string null como valor padrão para qualquer ausência.","Desligar FTS5 e anunciar que a busca continua funcionando sem outra implementação.","Validar o campo JSON e definir como a linguagem FTS5 será interpretada ou escapada, em vez de tratá-la como substring comum."],"answer":3,"explanation":"Extrair um valor não valida todo o contrato; MATCH possui linguagem própria. Presença, tipo e sintaxe permitida precisam de decisões explícitas.","reviewLessons":[14,15]},{"id":"q3","prompt":"A view deve refletir preço atual, mas a auditoria só deve registrar mudanças efetivas. Como tratar UPDATE que repete o mesmo preço?","options":["Manter a view como consulta e condicionar o trigger à diferença entre OLD e NEW conforme a regra de NULL.","Copiar a view toda a cada leitura e auditar qualquer SELECT.","Guardar dois históricos para toda consulta da view.","Supor que uma view comum materializa e sincroniza sozinha uma cópia externa."],"answer":0,"explanation":"A view define leitura; o trigger define efeito de escrita. A condição de mudança evita auditoria sem alteração de valor.","reviewLessons":[16,17]}]},{"id":"combo-3","title":"Reserva concorrente em WAL","scenario":"Duas conexões usam um arquivo local. A aplicação exige uma reserva aberta por recurso, consulta por cliente e retomada explícita quando há disputa de escritor.","requiredLessons":[19,20,22,23,25,26],"skills":["Índice parcial","Locks e snapshot","Plano por padrão de acesso"],"questions":[{"id":"q1","prompt":"A tela consulta disponibilidade antes da reserva, mas duas requisições podem passar nessa checagem. Qual defesa deve existir na escrita?","options":["Apenas esperar um segundo no botão antes do INSERT.","Uma restrição de unicidade parcial para reservas abertas e uma unidade transacional que trate a recusa.","Desligar a transação para permitir duas reservas abertas.","Usar ORDER BY na checagem e dispensar a restrição."],"answer":1,"explanation":"A consulta anterior pode ficar obsoleta. O índice único parcial protege a invariante no momento da escrita, com erro tratado pela aplicação.","reviewLessons":[20,23]},{"id":"q2","prompt":"Em WAL, B mantém snapshot antigo de leitura e A já é escritor. B tenta iniciar outra escrita e recebe BUSY. Qual conclusão é correta?","options":["WAL garante dois escritores e BUSY pode ser ignorado como sucesso.","O snapshot prova que A perdeu sua alteração.","WAL permite coexistência de leitura e escrita, mas não dois escritores; a aplicação precisa encerrar/reavaliar a unidade e limitar retries.","A solução é apagar -wal enquanto A escreve."],"answer":2,"explanation":"A visão do leitor e a disputa pelo escritor são contratos distintos. WAL não remove a exclusividade de escrita nem o tratamento de erro.","reviewLessons":[25,26]},{"id":"q3","prompt":"A consulta filtra cliente_id e ordena por instante,id. Um índice composto foi criado. O que deve orientar sua avaliação?","options":["Quantidade de letras no nome do índice.","Um tempo fixo deduzido do número interno do plano.","Supor que qualquer índice elimina toda leitura.","Correspondência com filtro/ordem, resultado correto e estratégia observada em EQP, sem depender do texto exato do plano como API."],"answer":3,"explanation":"A ordem do índice acompanha o acesso e EQP é diagnóstico. Formato e escolha de plano podem mudar; meça o trabalho relevante.","reviewLessons":[19,22]}]},{"id":"combo-4","title":"Migração e recuperação verificáveis","scenario":"O aplicativo migra seu esquema, recebe filtros do usuário e precisa produzir uma cópia que possa ser aberta num diretório separado com dados e regras conferidos.","requiredLessons":[28,29,30,31,32,33],"skills":["Binding e testes","Versionamento","Cópia independente"],"questions":[{"id":"q1","prompt":"Uma entrada com aspas foi ligada por placeholder e não alterou a consulta. Qual teste ainda é necessário para confiar no caminho de erro?","options":["Testar também a entrada legítima e confirmar que falhas esperadas têm causa e estado final corretos.","Tratar qualquer exceção como aprovação de todos os testes.","Concatenar a entrada para comparar desempenho sem controle.","Remover o fechamento da conexão porque binding o faz automaticamente."],"answer":0,"explanation":"Binding resolve a separação de valores, mas testes devem distinguir sucesso, falha prevista e erro inesperado. Recursos também precisam de fechamento.","reviewLessons":[28,30]},{"id":"q2","prompt":"user_version foi alterado, mas a coluna nova não apareceu na cópia reaberta. O que o procedimento deveria garantir?","options":["Supor que user_version executa o ALTER por conta própria.","Aplicar a migração real e sua versão de forma coordenada, depois copiar e conferir o esquema/dados no destino.","Editar sqlite_schema manualmente para fingir a coluna.","Declarar recuperação válida só porque existe o arquivo."],"answer":1,"explanation":"O inteiro é metadado da aplicação, não um motor de migrations. A cópia precisa preservar uma versão realmente aplicada e ser inspecionada.","reviewLessons":[29,31]},{"id":"q3","prompt":"VACUUM INTO gerou um destino novo. integrity_check retorna ok, mas a regra de domínio ainda não foi conferida. Qual sequência completa a evidência?","options":["Apagar a origem antes de qualquer leitura.","Assumir que ok conhece toda regra do produto.","Abrir o destino, verificar também referências e consultas de negócio com resultados conhecidos.","Copiar só o arquivo -shm e descartar a cópia gerada."],"answer":2,"explanation":"Integridade estrutural é uma evidência; referências e invariantes do produto têm verificações próprias. A cópia precisa ser lida.","reviewLessons":[32,33]}]}],"finalProject":{"id":"final","title":"Aplicativo local de reservas com recuperação","scenario":"Construa a persistência de um agendador local de recursos. O cliente pode ser uma CLI Python; todos os arquivos de ensaio devem ficar em diretório de laboratório identificado.","requirements":["Domínio explícito: tabelas STRICT compatíveis, unidades documentadas, chaves e referências habilitadas por conexão.","Reserva protegida: no máximo uma reserva aberta por recurso e alteração condicional que confirme seu efeito.","Concorrência observada: duas conexões reproduzem snapshot WAL e BUSY; retries são limitados e transações são curtas.","Leitura eficiente: relatórios preservam pais sem filhos e um índice é justificado por consulta, EQP e medição comparável.","Cliente evolutivo: valores parametrizados, conexões fechadas, migrations versionadas e testes de erro que conferem causa e estado.","Cópia recuperável: backup por API ou VACUUM INTO, reabertura independente e comparação de integridade, referências e dados conhecidos."],"deliverables":["DDL, contrato das unidades e lista de capacidades do build SQLite.","CLI Python e scripts de migration versionados.","Testes reproduzíveis com duas conexões, casos inválidos e relatório de planos.","Runbook de cópia/reabertura com saídas e limites da implantação escolhida."],"rubric":[{"id":"r1","title":"Domínio explícito","description":"Domínio explícito: tabelas STRICT compatíveis, unidades documentadas, chaves e referências habilitadas por conexão.","reviewLessons":[2,4,5,6,9]},{"id":"r2","title":"Reserva protegida","description":"Reserva protegida: no máximo uma reserva aberta por recurso e alteração condicional que confirme seu efeito.","reviewLessons":[7,20,23]},{"id":"r3","title":"Concorrência observada","description":"Concorrência observada: duas conexões reproduzem snapshot WAL e BUSY; retries são limitados e transações são curtas.","reviewLessons":[25,26,27]},{"id":"r4","title":"Leitura eficiente","description":"Leitura eficiente: relatórios preservam pais sem filhos e um índice é justificado por consulta, EQP e medição comparável.","reviewLessons":[10,19,22]},{"id":"r5","title":"Cliente evolutivo","description":"Cliente evolutivo: valores parametrizados, conexões fechadas, migrations versionadas e testes de erro que conferem causa e estado.","reviewLessons":[28,29,30]},{"id":"r6","title":"Cópia recuperável","description":"Cópia recuperável: backup por API ou VACUUM INTO, reabertura independente e comparação de integridade, referências e dados conhecidos.","reviewLessons":[31,32,33,36]}],"acceptance":[{"title":"Reserva e recusa concorrente","setup":"Recurso 1 sem reserva; duas conexões reais ao mesmo arquivo local.","input":"Tentar duas reservas abertas do recurso e concluir as transações conforme o protocolo.","expected":"Só uma reserva aberta persiste; a segunda recebe recusa tratada e não há efeito parcial.","reviewLessons":[20,23,25,30]},{"title":"Snapshot de leitura","setup":"WAL confirmado; B abre transação e lê versão 1.","input":"A confirma versão 2; B lê antes e depois de encerrar seu snapshot.","expected":"B observa 1 dentro da transação antiga e 2 numa leitura posterior ao encerramento.","reviewLessons":[23,25,26]},{"title":"Migração e reabertura","setup":"Base na versão anterior com fixture conhecida e destino novo.","input":"Migrar, copiar pelo mecanismo escolhido, fechar e abrir a cópia em outra conexão.","expected":"Versão, esquema, dados e regras conferem no destino; não basta o nome do arquivo existir.","reviewLessons":[29,31,32,33]}],"questions":[{"id":"q1","prompt":"A interface impede clique duplo, mas o banco aceita duas reservas abertas após duas conexões. O que precisa ser revisto?","options":["Somente a cor do botão.","Apenas o nome do arquivo de backup.","A contagem aproximada de tabelas.","A restrição no banco e o protocolo transacional/erro da escrita concorrente."],"answer":3,"explanation":"A interface não coordena todas as requisições. A defesa final precisa existir na escrita e ser testada sob disputa.","reviewLessons":[20,23,25]},{"id":"q2","prompt":"O projeto copia apenas .db enquanto há WAL ativo e declara recuperação sem reabertura. Qual requisito está faltando?","options":["Cópia coordenada pelo mecanismo apropriado e prova de leitura/validação do destino.","Mais campos na tabela de usuários.","Um checkpoint anunciado como cópia remota.","Desligar FKs para evitar divergência no restore."],"answer":0,"explanation":"Páginas confirmadas podem estar no WAL. A integridade da cópia e sua utilidade precisam de procedimento e conferência reais.","reviewLessons":[27,31,33]},{"id":"q3","prompt":"Os testes passam só em ordem fixa porque reutilizam o arquivo deixado pelo teste anterior. Qual melhoria torna a evidência mais confiável?","options":["Guardar a senha no arquivo de fixture.","Isolar fixtures, controlar migrations e permitir que cada cenário prepare e confira seu próprio estado.","Ignorar falhas da primeira execução.","Trocar assertions por mensagens de sucesso incondicionais."],"answer":1,"explanation":"Testes devem separar implementação correta de efeitos acidentais do ambiente. Estado escondido reduz reprodutibilidade.","reviewLessons":[29,30,36]}]}},"sqlserver":{"courseId":"sqlserver","combos":[{"id":"combo-1","title":"Pedidos e relatórios em T-SQL","scenario":"Um banco SQL Server 2022 recebe nomes com acentos, cria pedidos com itens e precisa listar clientes sem movimento. A saída da escrita deve identificar a operação correta.","requiredLessons":[2,4,5,6,8,9],"skills":["Unicode e domínio","FK e OUTPUT","Junção e contagem"],"questions":[{"id":"q1","prompt":"O cadastro precisa preservar nomes Unicode e rejeitar quantidade não positiva. Qual escolha atende aos dois requisitos?","options":["Apenas usar literal sem considerar o tipo da coluna e remover CHECK.","Converter todo nome em ID numérico para evitar validação.","Afirmar que a escolha de nvarchar valida qualquer quantidade.","Representação Unicode adequada e constraints explícitas de presença/intervalo."],"answer":3,"explanation":"Tipo textual e regra numérica resolvem problemas distintos. O esquema deve registrar ambos os contratos.","reviewLessons":[2,4]},{"id":"q2","prompt":"Um pedido recém-inserido precisa ser associado a itens e ter o ID devolvido ao cliente. Qual defesa combina identidade e integridade?","options":["Obter o ID da própria escrita por OUTPUT/API apropriada e usar FK nos itens.","Consultar MAX(id) global e remover a FK porque o número parece correto.","Copiar o primeiro ID mostrado no SSMS.","Guardar somente o nome do cliente em cada item sem referência."],"answer":0,"explanation":"O retorno precisa corresponder à escrita atual e a relação deve ser protegida. Uma consulta global não identifica a operação da sessão.","reviewLessons":[5,6]},{"id":"q3","prompt":"Depois de LEFT JOIN, cliente sem pedido tem COUNT(*)=1. O relatório exige zero pedidos e preservar esse cliente. O que mudar?","options":["Trocar para INNER JOIN para fazer o zero aparecer.","Contar a chave do pedido e agrupar na granularidade do cliente.","Somar o saldo do cliente em cada item relacionado.","Aplicar HAVING COUNT(*)>0 e afirmar que os ausentes continuam presentes."],"answer":1,"explanation":"A linha preservada é uma linha de resultado, não um pedido real. A coluna direita nula permite contar correspondências de fato.","reviewLessons":[8,9]}]},{"id":"combo-2","title":"Carga de documentos e auditoria por conjunto","scenario":"Uma rotina importa itens JSON e atualiza várias linhas. O relatório precisa de acumulados por pedido e a equipe investiga uma consulta de busca.","requiredLessons":[11,12,14,15,16,17],"skills":["OPENJSON e janela","Rotinas e triggers","Índice e plano"],"questions":[{"id":"q1","prompt":"OPENJSON expande três itens de um pedido e a tela deve manter os três detalhes com um total acumulado ordenado. Qual estrutura corresponde?","options":["Usar GROUP BY apenas no pedido e esperar conservar os três detalhes.","Somar a string JSON bruta como total.","Projetar os itens com tipos definidos e usar janela com ordem/frame adequados, sem agrupá-los numa única linha.","Presumir que OPENJSON cria uma ordem de negócio estável automaticamente."],"answer":2,"explanation":"A expansão define as linhas de item; a janela acrescenta uma medida sem reduzir a granularidade. Tipos e ordem precisam ser explícitos.","reviewLessons":[11,12]},{"id":"q2","prompt":"Uma procedure faz UPDATE de duas linhas e o trigger usa apenas uma variável escalar retirada de inserted. Qual correção é necessária?","options":["Chamar a procedure uma vez a mais para compensar a linha perdida.","Assumir que todo trigger SQL Server recebe uma linha por execução.","Desativar o trigger em qualquer atualização múltipla.","Tratar inserted/deleted como conjuntos e registrar todas as correspondências conforme a chave."],"answer":3,"explanation":"Procedures podem afetar várias linhas por instrução. O trigger deve operar sobre o conjunto, sem perder dados por escolha escalar arbitrária.","reviewLessons":[14,15]},{"id":"q3","prompt":"Foi criado um índice com INCLUDE para cobrir a consulta. O plano mostra menos leituras num ensaio. Que evidência ainda deve ser preservada?","options":["Resultado equivalente, dados/carga do ensaio e medidas comparáveis de leituras/tempo, com permissões necessárias para coletar planos.","Somente uma captura do nome do índice.","A promessa de que INCLUDE ordena qualquer coluna automaticamente.","Nenhum teste funcional porque um plano real sempre prova a regra do negócio."],"answer":0,"explanation":"Cobertura e estratégia de acesso devem ser avaliadas com o mesmo trabalho. Plano real não substitui conferir a resposta da consulta.","reviewLessons":[16,17]}]},{"id":"combo-3","title":"Transações e autorização em disputa","scenario":"O serviço faz alterações concorrentes, executa SQL dinâmico com valores do usuário e aplica isolamento de linhas por identidade. É preciso tratar erros sem ampliar privilégios.","requiredLessons":[19,20,21,22,23,24],"skills":["Falha transacional","Autorização e parâmetros","Isolamento"],"questions":[{"id":"q1","prompt":"Uma transação sofre erro/deadlock após parte das alterações. Qual caminho deve ser validado antes de repetir?","options":["Repetir apenas a última linha de UPDATE e ignorar efeitos anteriores.","Inspecionar o estado transacional, desfazer quando necessário e refazer a unidade com limite, preservando a identidade da operação.","Anunciar sucesso porque BEGIN TRAN foi executado.","Deixar a transação aberta para que o próximo usuário a resolva."],"answer":1,"explanation":"TRY/CATCH, XACT_STATE e o contrato do erro ajudam a fechar corretamente a unidade. Retry sem estado conhecido pode criar efeitos duplicados ou pendentes.","reviewLessons":[19,21]},{"id":"q2","prompt":"A consulta usa sp_executesql com parâmetros, mas o usuário tenta consultar o dono de outra linha. Qual proteção ainda precisa ser testada?","options":["Apenas que a string SQL não contém aspas.","Que a aplicação conecta sempre como administrador para ver tudo.","A política de linha sob identidade/contexto confiáveis; parâmetros não substituem autorização.","Que o nome do parâmetro contém tenant."],"answer":2,"explanation":"Binding protege valores e estrutura. RLS depende de política e contexto corretos para restringir as linhas acessíveis.","reviewLessons":[23,24]},{"id":"q3","prompt":"Uma role só tem SELECT. O cliente muda para READ UNCOMMITTED e tenta UPDATE. A mudança de isolamento deve conceder escrita?","options":["Sim, READ UNCOMMITTED concede qualquer comando.","Sim, toda role de leitura pode alterar uma linha não bloqueada.","Não, porque esse nível elimina a conexão.","Não; isolamento altera visibilidade/coordenação, enquanto as permissões de escrita continuam precisando ser autorizadas."],"answer":3,"explanation":"Permissão e isolamento são dimensões distintas. Testes devem confirmar operações recusadas, não apenas leitura bem-sucedida.","reviewLessons":[20,22]}]},{"id":"combo-4","title":"Restore, regressão e mudança compatível","scenario":"O serviço possui backup-base e logs, Query Store e migrations. Uma atualização de cliente usa versão otimista; o procedimento operacional precisa separar dados recuperados e desempenho.","requiredLessons":[25,26,27,28,31,35],"skills":["Cadeia de recuperação","Evidência funcional e plano","Versão de esquema e de linha"],"questions":[{"id":"q1","prompt":"O requisito é recuperar até antes de um DELETE. Qual conjunto permite planejar esse ensaio em vez de só conferir um .bak?","options":["Modelo de recuperação apropriado, backup-base válido e cadeia de logs necessária, aplicados até o alvo num destino de teste.","Qualquer arquivo com extensão .trn, sem base ou ordem conhecida.","Somente mudar SIMPLE para FULL depois da falha e presumir logs anteriores.","Executar VERIFYONLY e afirmar que a linha já voltou."],"answer":0,"explanation":"Recuperação por ponto depende de configuração e cadeia coerentes. Validar mídia não executa a restauração do estado escolhido.","reviewLessons":[25,27]},{"id":"q2","prompt":"O destino restaurado contém os marcadores corretos, mas uma consulta ficou lenta após migration. Que investigação complementa a prova de dados?","options":["Declarar restore inválido apenas porque um plano mudou.","Usar evidências de Query Store/planos e carga para a regressão, mantendo separada a validação funcional do restore.","Reaplicar o backup repetidamente sem investigar consultas.","Afirmar que recuperar linhas garante latência idêntica em qualquer ambiente."],"answer":1,"explanation":"Recuperação funcional e comportamento de desempenho têm evidências diferentes. A regressão precisa de medições e contexto de execução.","reviewLessons":[26,28]},{"id":"q3","prompt":"Uma migration altera o esquema e a API usa uma coluna versao para concorrência otimista. Os dois números podem ser tratados como a mesma versão?","options":["Sim, aumentar a versão do esquema autoriza qualquer UPDATE obsoleto.","Sim, a linha muda de tabela a cada conflito.","Não; versão de migration controla o contrato do esquema e versão da linha detecta atualização concorrente de um registro.","Não, porque SQL Server não aceita números de versão na aplicação."],"answer":2,"explanation":"A evolução do esquema e o controle de disputa têm escopos distintos. Ambos precisam de protocolo e verificação próprios.","reviewLessons":[31,35]}]}],"finalProject":{"id":"final","title":"Pedidos com outbox e recuperação no SQL Server","scenario":"Implemente um banco de pedidos e estoque em SQL Server 2022 Developer para ensaio local. Uma mudança de pedido deve poder registrar seu evento na mesma unidade de trabalho, sem depender de envio externo dentro da transação.","requirements":["Modelo e entrada: constraints, referências, Unicode e valores de domínio são validados no esquema e nos procedimentos.","Unidade transacional: pedido, baixa e outbox são coordenados com TRY/CATCH e encerramento correto após falha.","Concorrência e repetição: atualização otimista ou lock protege estoque e retries idempotentes não duplicam efeitos.","Leitura e acesso: consultas preservam granularidade, parâmetros separam valores e roles/RLS são testadas para permitidos e recusados.","Evolução e investigação: migration versionada, plano/Query Store e diagnóstico de bloqueios acompanham a entrega.","Recuperação: backup completo e restauração em destino separado são verificados; recuperação no tempo só é declarada após ensaio real com a cadeia correta."],"deliverables":["DDL, procedimentos, outbox, fixtures e migrations.","Cliente parametrizado com contratos de conflito e repetição.","Testes funcionais, concorrentes e de autorização; evidências de planos/Query Store.","Runbook operacional com caminhos do servidor, permissões, cópias e verificação do destino."],"rubric":[{"id":"r1","title":"Modelo e entrada","description":"Modelo e entrada: constraints, referências, Unicode e valores de domínio são validados no esquema e nos procedimentos.","reviewLessons":[2,4,5,14]},{"id":"r2","title":"Unidade transacional","description":"Unidade transacional: pedido, baixa e outbox são coordenados com TRY/CATCH e encerramento correto após falha.","reviewLessons":[19,34,36]},{"id":"r3","title":"Concorrência e repetição","description":"Concorrência e repetição: atualização otimista ou lock protege estoque e retries idempotentes não duplicam efeitos.","reviewLessons":[20,21,35]},{"id":"r4","title":"Leitura e acesso","description":"Leitura e acesso: consultas preservam granularidade, parâmetros separam valores e roles/RLS são testadas para permitidos e recusados.","reviewLessons":[8,9,22,23,24]},{"id":"r5","title":"Evolução e investigação","description":"Evolução e investigação: migration versionada, plano/Query Store e diagnóstico de bloqueios acompanham a entrega.","reviewLessons":[16,17,28,29,31]},{"id":"r6","title":"Recuperação","description":"Recuperação: backup completo e restauração em destino separado são verificados; recuperação no tempo só é declarada após ensaio real com a cadeia correta.","reviewLessons":[25,26,27]}],"acceptance":[{"title":"Falha entre pedido e evento","setup":"Fixture de estoque e nenhuma operação de teste aplicada.","input":"Provocar erro após alteração de pedido, antes de concluir a outbox.","expected":"A unidade é desfeita; pedido, estoque e evento permanecem coerentes, sem transação aberta.","reviewLessons":[19,34,36]},{"title":"Atualização obsoleta","setup":"Duas leituras da mesma linha com a mesma versão inicial.","input":"Aplicar a primeira atualização e tentar a segunda com a versão antiga.","expected":"A segunda não altera a linha e a API trata conflito; não anuncia sucesso silencioso.","reviewLessons":[20,35,36]},{"title":"Restore em destino distinto","setup":"Backup-base real e diretórios/nomes lógicos verificados no servidor.","input":"Restaurar em banco exclusivo e consultar marcadores, contagens e regras conhecidas.","expected":"Destino fica acessível e contém o ponto esperado; VERIFYONLY sozinho não é tratado como esse resultado.","reviewLessons":[25,26,27]}],"questions":[{"id":"q1","prompt":"A outbox contém um evento, mas o pedido que o gerou foi revertido. Qual propriedade precisa ser corrigida?","options":["A cor do dashboard.","O nome do login no SSMS.","A ordem de campos do JSON apenas.","A atomicidade local entre mudança de negócio e registro do evento."],"answer":3,"explanation":"Outbox só atende ao objetivo quando participa da mesma unidade de confirmação do estado de negócio.","reviewLessons":[19,34,36]},{"id":"q2","prompt":"Um cliente reenvia uma operação após perder a resposta e o sistema cria novo pedido. Qual aspecto falta além do tratamento de deadlock?","options":["Identidade da operação e protocolo idempotente coordenado aos efeitos.","Apenas um timeout maior.","Uma segunda conexão administrativa para repetir qualquer comando.","Desligar a chave única para evitar erro."],"answer":0,"explanation":"Resultado incerto e conflito de lock não são o mesmo problema. Repetição precisa reconhecer efeitos já confirmados.","reviewLessons":[21,34,35]},{"id":"q3","prompt":"A restauração passou, mas uma role de leitura consegue alterar qualquer linha e a API usa SQL concatenado. Que conclusão vale?","options":["O restore aprova automaticamente toda a segurança.","A recuperação é uma evidência parcial; autorização e parametrização ainda não atendem aos critérios.","Somente o arquivo .bak precisa ser renomeado.","Não existe diferença entre permissões e backup."],"answer":1,"explanation":"Os critérios do projeto são independentes e cada um exige sua própria comprovação.","reviewLessons":[22,23,26]}]}}};
